export const NEFROLOGIE_V2=[
q("nefrologie-adv-001",["Sindromul nefrotic comparativ cu sindromul nefritic:",
 ["în sindromul nefrotic proteinuria depășește 3,5 g/zi","cauza nefrotică cea mai frecventă: lezarea podocitelor","sindromul nefritic asociază hematurie și proteinurie nefrotică","în sindromul nefritic sunt implicate principal podocitele","proteinuria sindromului nefrotic este sub 1 g/zi"],"AB",1353,"Glomerulul și afectarea glomerulară — Clasificarea clinică: sindrom nefrotic versus nefritic",
 "Diferențierea celor două sindroame glomerulare majore după proteinurie, compartimentul celular predominant afectat și tabloul nefritic acut.",
 ["Sindromul nefrotic se definește prin proteinurie masivă (>3,5 g/zi), hipoalbuminemie, edeme, lipidurie și hiperlipidemie.","Cauza cea mai frecventă a sindromului nefrotic este malfuncția sau lezarea podocitelor.","Nu: sindromul nefritic (glomerulonefrita acută) asociază hematurie glomerulară cu proteinurie de rang non-nefrotic, edeme, hipertensiune și afectare renală tranzitorie.","Nu: podocitele sunt principal implicate în sindromul nefrotic, iar celulele endoteliale și mezangiale în bolile care se prezintă ca nefrită.","Nu: sindromul nefrotic se definește printr-o proteinurie de peste 3,5 g/zi, însoțită de hiperlipidemie."]],
 [8,"Distractorii inversează compartimentele celulare din același paragraf și coboară proteinuria nefrotice sub pragul explicit de 3,5 g/zi."],[">3,5 g/zi","malfuncţia sau lezarea podocitelor"]),

q("nefrologie-adv-002",["În tratamentul general al sindromului nefrotic se recomandă:",
 ["dietă bogată în proteine, de 80–90 g/zi","evitarea repausului prelungit la pat (risc tromboembolic)","profilaxia antibiotică pe termen lung a infecțiilor","IECA și/sau ARA II, pentru efectul antiproteinuric","furosemid plus spironolactonă 5 mg/zi la neresponsivi"],"BD",1354,"Glomerulul și afectarea glomerulară — Sindromul nefrotic: tratament, măsuri generale",
 "Aplicarea măsurilor generale corecte în sindromul nefrotic (aport proteic, profilaxia trombozei, abordarea infecțiilor, blocada SRA, diuretice) și evitarea erorilor frecvente.",
 ["Nu: se recomandă un aport proteic normal; dieta bogată în proteine (80–90 g/zi) crește proteinuria și poate fi dăunătoare.","Repausul prelungit la pat trebuie evitat, deoarece tromboembolismul este foarte frecvent, mai ales în nefropatia membranoasă.","Nu: se preferă depistarea precoce și tratamentul agresiv al infecțiilor, nu profilaxia antibiotică pe termen lung.","IECA și/sau ARA II sunt indicați pentru proprietățile lor antiproteinurice, mai ales în sindromul nefrotic.","Nu: la pacienții neresponsivi se asociază furosemidului (40–120 mg/zi) amiloridul 5 mg/zi, nu spironolactona."]],
 [8,"Distractorii inversează două recomandări intuitive (dieta hiperproteică, profilaxia antibiotică) și schimbă diureticul economisitor de potasiu din text."],["proprietăţile lor antiproteinurice","tromboembolismul este foarte frecvent"]),

q("nefrologie-adv-003",["Nefropatia cu leziuni minime:",
 ["proteinurie neselectivă, cu pierdere de imunoglobuline","20–25% din sindroamele nefrotice ale adultului","atopie prezentă la circa 30% dintre pacienți","imunofluorescența arată depozite granulare de complexe imune","două treimi dintre copii recidivează după corticoterapie"],"BCE",1354,"Glomerulul și afectarea glomerulară — Cauzele sindromului nefrotic: nefropatia cu leziuni minime",
 "Recunoașterea caracteristicilor clinice, epidemiologice și imunohistologice ale nefropatiei cu leziuni minime, inclusiv rata de recidivă la copii.",
 ["Nu: proteinuria este de obicei „înalt selectivă”: se pierde albumina, dar nu imunoglobulinele.","Nefropatia cu leziuni minime reprezintă 20–25% din cazurile de sindrom nefrotic la adulți.","Atopia este prezentă în 30% din cazuri, iar reacțiile alergice pot declanșa sindromul nefrotic.","Nu: la imunofluorescență nu se evidențiază nici complexe imune, nici anticorpi anti-MBG.","Două treimi dintre copii prezintă recidive după corticoterapie și necesită cure suplimentare de corticosteroizi."]],
 [8,"Cere reținerea mai multor procente exacte și a aspectului negativ la imunofluorescență, distractorul împrumutând un aspect din glomerulonefritele cu complexe imune."],["înalt selectivă","Atopia este prezentă în 30%"]),

q("nefrologie-adv-004",["Glomeruloscleroza focală și segmentară (GSFS) primară versus secundară:",
 ["fuziunea pedicelară masivă, și în glomerulii normali, indică forma primară","hipoalbuminemia este tipică formei secundare","varianta perihilară este frecventă în forma primară","recidiva rapidă pe grefă indică forma secundară","ștergerea pedicelelor limitată la glomerulii sclerozați indică forma primară"],"A",1355,"Glomerulul și afectarea glomerulară — Glomeruloscleroza focală și segmentară: morfopatologie",
 "Diferențierea GSFS primare de cea secundară pe baza gradului și distribuției fuziunii pedicelelor podocitare și a trăsăturilor clinice asociate.",
 ["Fuziunea masivă a pedicelelor, atât în glomerulii sclerozați, cât și în cei normali, indică cel mai probabil GSFS primară.","Nu: în GSFS secundară proteinuria poate fi importantă, dar hipoalbuminemia este neobișnuită; relația este inversată.","Nu: varianta perihilară se observă frecvent în GSFS secundară, nu în cea primară.","Nu: recidiva pe rinichiul transplantat, uneori în câteva zile, caracterizează GSFS primară.","Nu: ștergerea pedicelelor evidentă izolat în glomerulii sclerozați face improbabilă GSFS primară."]],
 [8,"Fiecare distractor inversează o relație reală primar/secundar din același paragraf, cerând cunoașterea criteriului ultrastructural de diferențiere."],["fuziunea este masivă","joncţiunii corticomedulare"]),

q("nefrologie-adv-005",["Un bărbat de 52 de ani cu proteinurie de 6 g/zi are la biopsie excrescențe ale membranei bazale și anticorpi anti-PLA2R. Referitor la această afecțiune:",
 ["în forma autoimună, circa 75% au anticorpi IgG4 anti-PLA2R","anticorpi anti-THSD7A la 10% dintre cei PLA2R-negativi","corticoterapia orală în monoterapie induce remisiunea","depozite subendoteliale, cu dublarea membranei bazale","remisiune spontană la cel puțin o treime"],"ABE",1357,"Glomerulul și afectarea glomerulară — Glomerulonefrita membranoasă: patogeneză și tratament",
 "Integrarea tabloului histologic și serologic al glomerulonefritei membranoase autoimune cu datele de patogeneză (PLA2R, THSD7A), evoluție naturală și tratament.",
 ["La 75% dintre pacienții cu forma autoimună apar autoanticorpi IgG4 împotriva receptorului fosfolipazei A2 de tip M (PLA2R).","Anticorpii anti-THSD7A sunt identificați la 10% dintre pacienții PLA2R-negativi (și la 3% dintre cei PLA2R-pozitivi).","Nu: corticosteroizii orali nu aduc beneficiu în monoterapie, ci doar aditiv, asociați altor medicamente.","Nu: depozitele electronodense sunt subepiteliale, înconjurate de excrescențe ale membranei bazale; aspectul subendotelial cu dublare este al GNMC tip 1.","O treime sau mai mulți pacienți au remisiune spontană dacă sunt urmăriți 6–12 luni, mai ales cu funcție renală normală, titru redus de anti-PLA2R și proteinurie mică."]],
 [8,"Vignetă care cere corelarea serologiei cu procente exacte, cu localizarea ultrastructurală a depozitelor și cu lipsa de eficiență a corticoterapiei singure."],["receptorului de fosfolipazei A2","remisiuni spontane"]),

q("nefrologie-adv-006",["Un diabetic de 61 de ani are la biopsie leziuni Kimmelstiel-Wilson și glomeruloscleroză globală în 30% din glomeruli. Conform Societății de Patologie Renală, nefropatia este de:",
 ["clasa I","clasa IIa","clasa IIb","clasa III","clasa IV"],"D",1359,"Glomerulul și afectarea glomerulară — Nefropatia diabetică: clasificarea Societății de Patologie Renală",
 "Aplicarea criteriilor histologice (leziuni nodulare și procentul de glomeruloscleroză globală) pentru încadrarea nefropatiei diabetice în clasele I–IV.",
 ["Nu: clasa I înseamnă îngroșarea izolată a MBG, fără expansiune mezangială sau glomeruloscleroză globală >50%.","Nu: clasa IIa corespunde expansiunii mezangiale ușoare, fără leziuni nodulare.","Nu: clasa IIb corespunde expansiunii mezangiale severe, fără leziuni nodulare.","Clasa III se definește prin glomeruloscleroză nodulară intercapilară (≥1 leziune Kimmelstiel-Wilson) și <50% glomeruloscleroză globală (Cadranul 36.11).","Nu: clasa IV necesită glomeruloscleroză diabetică avansată, cu >50% glomeruloscleroză globală, prag nedepășit aici."]],
 [8,"Vignetă numerică ce impune aplicarea pragului de 50% glomeruloscleroză globală pentru a separa clasa III de clasa IV."],["Kimmelstiel-Wilson","glomeruloscleroză globală"]),

q("nefrologie-adv-007",["Nefropatia cu IgA:",
 ["GN proliferativă focală cu depozite mezangiale de IgA1","hematuria macroscopică recurentă indică un prognostic nefavorabil","până la 50% au IgA seric crescut, monoclonal","risc de BCR terminală ~25% la proteinurie >1 g/zi","prednisolon plus ciclofosfamidă, cu beneficiu clar la eGFR <60"],"AD",1362,"Glomerulul și afectarea glomerulară — Nefropatia cu IgA: histologie, tablou clinic, tratament",
 "Cunoașterea trăsăturilor histologice, a factorilor de prognostic (inclusiv semnificația paradoxală a hematuriei macroscopice) și a limitelor imunosupresiei în nefropatia cu IgA.",
 ["Histologic apare o GN proliferativă focală și segmentară cu depozite mezangiale de IgA1 polimerice.","Nu: hematuria macroscopică recurentă este, surprinzător, un semn de prognostic bun, pacienții prezentându-se precoce.","Nu: până la 50% dintre pacienți prezintă IgA seric crescut, dar de tip policlonal.","Riscul de BCR terminală este de aproximativ 25% la cei cu proteinurie peste 1 g/zi; alți factori sunt creatinina crescută, HTA, izoforma DD a ECA și fibroza tubulointerstițială.","Nu: prednisolonul singur sau cu ciclofosfamidă timp de 3 luni nu a demonstrat beneficiu la pacienții cu risc crescut și eGFR sub 60 ml/min."]],
 [8,"Exploatează semnificația contraintuitivă a hematuriei macroscopice recurente și un rezultat negativ al imunosupresiei ușor de presupus pozitiv."],["lgA seric crescut","hematuria macroscopică recurentă"]),

q("nefrologie-adv-008",["Nefrita tubulointerstițială acută indusă de medicamente:",
 ["medicamentele cauzează circa 70% din NTI acute","infiltratul interstițial include adesea eozinofile","AINS pot asocia leziuni minime cu sindrom nefrotic","prednisonul 60 mg/zi poate reduce necesarul de dializă","infecțiile cauzează circa 40% din NTI acute"],"ABCD",1385,"Nefritele tubulointerstițiale — Nefrita tubulointerstițială acută indusă de medicamente",
 "Recunoașterea etiologiei predominant medicamentoase a NTI acute, a markerilor eozinofilici, a asocierii AINS–leziuni minime și a rolului corticoterapiei.",
 ["În aproximativ 70% din cazuri NTI acută este o reacție de hipersensibilitate la medicamente, cel mai adesea peniciline, AINS sau inhibitori de pompă de protoni.","Mulți pacienți au eozinofilie și eozinofilurie, iar histologia arată un infiltrat interstițial care include adesea eozinofile.","AINS pot produce o glomerulopatie cu leziuni minime asociată NTI, pacientul prezentându-se cu sindrom nefrotic.","Dozele mari de prednison (60 mg/zi) pot reduce riscul de IRA severă cu necesar de dializă și timpul de recuperare.","Nu: infecțiile sunt responsabile de aproximativ 15% din cazurile de NTI acută (Cadranul 36.27), nu de 40%."]],
 [8,"Combină procentele din Cadranul 36.27 cu un mecanism dublu (NTI plus leziuni minime) al AINS, distractorul folosind un procent greșit din același tabel."],["eozinofilie şi eozinofilurie","reacţie de hipersensibilitate"]),

q("nefrologie-adv-009",["Stadializarea bolii cronice de rinichi (BCR):",
 ["RFG 75 ml/min izolată înseamnă BCR stadiul G2","subdivizarea stadiului 3: 3a (RFG 45–59), 3b (30–44)","G4 (RFG 15–29 ml/min) definește boala renală terminală","cistatina C este propusă pentru stratificarea stadiului 5","majoritatea cazurilor de BCR sunt în stadiul 4"],"B",1392,"Boala cronică de rinichi — Stadializarea și prevalența",
 "Aplicarea corectă a categoriilor G ale clasificării KDIGO, inclusiv condiția suplimentară pentru stadiul G2 și motivul divizării stadiului 3.",
 ["Nu: în categoria G2 pacienții nu au boala decât dacă există și o altă manifestare a afectării renale (hematurie, proteinurie, modificări structurale).","Stadiul 3 a fost divizat în 3a (RFG 45–59) și 3b (RFG 30–44 ml/min), pacienții din stadiul mai avansat având mai multe complicații cardiovasculare.","Nu: boala renală terminală corespunde stadiului G5 (RFG <15 ml/min); G4 înseamnă RFG foarte scăzută.","Nu: cistatina C a fost propusă pentru pacienții în stadiul 3, pentru o mai bună stratificare a riscului.","Nu: prevalența BCR este estimată la 11–15%, iar majoritatea cazurilor sunt în stadiul 3."]],
 [8,"Distractorii mută praguri și stadii cu o singură treaptă și omit condiția suplimentară necesară pentru diagnosticul în stadiul G2."],["G3bA3","majoritatea cazurilor fiind în stadiul 3"]),

q("nefrologie-adv-010",["Un hemodializat cu Hb 88 g/L nu răspunde la epoetină-α 300 U/kg/săptămână; feritina este 620 µg/L, iar PCR este crescută. În acest caz:",
 ["se exclud carența de fier, sângerarea, infecția","feritina >500 µg/L exclude deficitul funcțional de fier","hepcidina crește absorbția intestinală a fierului","ținta hemoglobinei este de 100–120 g/L","fierul oral este preferat celui intravenos"],"AD",1394,"Boala cronică de rinichi — Complicațiile BCR: anemia și tratamentul cu ASE",
 "Interpretarea rezistenței la eritropoietină în BCR, inclusiv conceptul de deficit funcțional de fier în inflamație și rolul hepcidinei.",
 ["Lipsa răspunsului la 300 U/kg epoetină-α pe săptămână impune căutarea deficitului de fier, sângerărilor, malignităților, infecțiilor, inflamației sau anticorpilor neutralizanți.","Nu: deficitul funcțional de fier apare frecvent în inflamația cronică chiar cu feritina >500 µg/L, iar fierul intravenos optimizează răspunsul la ASE.","Nu: hepcidina, reactant de fază acută sintetizat hepatic ca răspuns la IL-6, inhibă absorbția intestinală a fierului și îl sechestrează în ficat.","Ținta hemoglobinei este 100–120 g/L; studiile în predializă nu au arătat beneficii pentru ținte >120 g/L.","Nu: suplimentarea cu fier intravenos este preferată celei orale pentru optimizarea răspunsului la ASE."]],
 [8,"Vignetă cu valori de laborator care par să excludă deficitul de fier, testând conceptul de deficit funcțional și inversând calea de administrare preferată."],["Deficitul funcţional de fier","hepcidină"]),

q("nefrologie-adv-011",["Tulburările minerale osoase asociate BCR (TMO-BCR):",
 ["FGF23, eliberat din osteocite, stimulează 1α-hidroxilaza renală","hiperparatiroidismul secundar asociază hipocalcemie și hiperfosfatemie","boala adinamică: PTH scăzut, fosfatază alcalină normală","coloana în „tricou de rugby” indică osteomalacie","la dializați, ținta PTH este de 2–3 ori limita superioară"],"BCE",1395,"Boala cronică de rinichi — Tulburările minerale osoase asociate BCR: patogeneză și tratament",
 "Corelarea modificărilor biochimice și radiologice cu tipurile de boală osoasă din BCR și înțelegerea rolului FGF23 și al țintei terapeutice pentru PTH.",
 ["Nu: FGF23, eliberat din osteocite ca răspuns la retenția de fosfat, induce fosfaturie și inhibă 1α-hidroxilaza renală.","Hiperparatiroidismul secundar se asociază cu hipocalcemie, hiperfosfatemie, PTH ridicat și fosfatază alcalină crescută.","În boala osoasă adinamică fosfataza alcalină serică este normală, iar PTH-ul este scăzut, cu osteopenie la DXA.","Nu: aspectul de „tricou de rugby” se datorează osteosclerozei din hiperparatiroidismul persistent, nu osteomalaciei.","La dializați se urmărește un PTH de 2–3 ori limita superioară a normalului, pentru ca turnoverul osos să continue și să nu apară boala adinamică."]],
 [8,"Cere diferențierea profilurilor biochimice ale mai multor tipuri de boală osoasă și atribuirea corectă a unui semn radiologic clasic."],["osteita fibroasă chistică","tricou de rugby"]),

q("nefrologie-adv-012",["Prevenția nefropatiei de contrast:",
 ["diabetul izolat nu este factor de risc","metformin oprit la creatinină >130 µmol/L","dopamina și teofilina sunt benefice în prevenție","N-acetilcisteina are un beneficiu major","hidratarea peri-procedurală trebuie evitată"],"AB",1392,"Boala cronică de rinichi — Nefropatia de contrast: prevenție (context de injurie renală acută)",
 "Aplicarea măsurilor reale de prevenție a IRA post-contrast și recunoașterea intervențiilor fără beneficiu (dopamină, teofilină, dializă profilactică).",
 ["Diabetul zaharat în sine nu este considerat un factor de risc pentru nefropatia de contrast.","Metforminul poate precipita acidoza lactică și se oprește dacă creatinina depășește 130 µmol/L, cu reluare când funcția renală revine la nivelul de bază.","Nu: dopamina, teofilina și dializa profilactică nu sunt benefice în prevenție.","Nu: N-acetilcisteina poate oferi cel mult un beneficiu marginal, nu unul major.","Nu: prevenția include hidratarea cu 1 L ser fiziologic 0,9% sau bicarbonat 1,4%, evitând supraîncărcarea doar la pacienții la risc."]],
 [8,"Capcana principală este statutul diabetului ca factor de risc, pe care textul îl neagă, alături de intervenții profilactice frecvent prescrise fără evidență."],["Diabetul în sine nu este un factor de risc","130 µmol/L"]),

q("nefrologie-adv-013",["Hemodializa și momentul inițierii:",
 ["dializa tinde să înceapă la RFG ~10 ml/min","debit sanguin necesar: 250–450 mL/min","ținta URR este peste 65% pe ședință","dializantul cu potasiu 1–3 mmol/L dă bilanț pozitiv","amiloidoza de dializă se datorează albuminei"],"ABC",1399,"Boala cronică de rinichi — Hemodializa: inițiere, principii și obiective",
 "Reținerea pragului practic de inițiere (RFG ~10 ml/min), a parametrilor cantitativi ai hemodializei și a mecanismului amiloidozei asociate dializei.",
 ["Există o tendință generală de a începe dializa la o RFG în jur de 10 ml/min, decizia fiind adaptată simptomelor și preferințelor pacientului.","O dializă eficientă necesită un debit sanguin între 250 și 450 mL/min prin abordul vascular.","URR are valoarea țintă >65% pe ședință, ca parametru minim al unei dialize adecvate.","Nu: dializantul cu potasiu redus (1–3 mmol/L) permite un bilanț negativ al potasiului de 1–2 mmol/kg pe ședință.","Nu: amiloidoza asociată dializei se datorează eliminării deficitare a β2-microglobulinei (11,8 kDa), nu a albuminei."]],
 [8,"Testează pragul de inițiere și valori numerice precise, inversând totodată sensul bilanțului potasiului și molecula implicată în amiloidoză."],["în jur de 10 ml/min","250 şi 450 mL/min"]),

q("nefrologie-adv-014",["Boala polichistică renală autozomal dominantă (BPRAD):",
 ["PKD1 (cromozomul 16) explică circa 85% din cazuri","calculii sunt predominant oxalocalcici, radioopaci","anevrism intracranian asimptomatic la circa 10%","forma autozomal recesivă implică gena PKD2 (cromozomul 4)","70% ajung la 70 de ani fără substituție renală"],"AC",1405,"Bolile renale chistice — Boala polichistică renală autozomal dominantă",
 "Cunoașterea bazei genetice a BPRAD, a complicațiilor extrarenale (anevrisme intracraniene) și a datelor prognostice, cu diferențierea de forma autozomal recesivă.",
 ["Mutațiile PKD1 (cromozomul 16) sunt responsabile de 85% din cazuri, restul fiind date de PKD2.","Nu: calculii apar la 10–20% dintre pacienți, dar sunt mai frecvent din acid uric și radiotransparenți.","Aproximativ 10% au un anevrism intracranian asimptomatic; screeningul se recomandă între 18 și 40 de ani la cei cu istoric familial pozitiv.","Nu: forma autozomal recesivă se datorează genei PKHD1 de pe cromozomul 6p21.1-p12; PKD2 (cromozomul 4) aparține formei dominante.","Nu: probabilitatea de a supraviețui până la 70 de ani fără necesar de substituție renală este de 30%, nu de 70%."]],
 [8,"Amestecă genele și cromozomii formelor dominantă și recesivă și inversează compoziția calculilor și procentul de supraviețuire fără dializă."],["policistina","anevrism intracranian asimptomatic"]),

q("nefrologie-adv-015",["Scintigrafia renală cu radioizotopi:",
 ["99mTc-DTPA este excretat predominant prin secreție tubulară","99mTc-DMSA, legat de tubii proximali, evidențiază cicatricile","MAG3 este secretat tubular, obstrucția întârziind golirea","furosemidul este contraindicat în renogramă, mascând obstrucția","cistouretrografia înlocuiește MAG3 în obstrucția adultului"],"BC",1351,"Investigații — Scintigrafia renală și urografia",
 "Diferențierea căilor de excreție ale DTPA, DMSA și MAG3 și a rolului furosemidului în confirmarea obstrucției.",
 ["Nu: 99mTc-DTPA este excretat prin filtrare glomerulară și evaluează perfuzia renală, de exemplu în stenoza de arteră renală.","99mTc-DMSA este filtrat și se leagă de celulele tubulare proximale; ariile cu deficiență de fotoni sugerează cicatrici sau infarcte.","MAG3 este excretat prin secreție tubulară; obstrucția prelungește tranzitul parenchimatos și întârzie golirea pelvisului.","Nu: furosemidul se administrează tocmai pentru a crește debitul urinar și a sublinia întârzierea golirii în obstrucție.","Nu: cistouretrografia studiază refluxul vezico-ureteral și nu înlocuiește MAG3 în diagnosticul obstrucției."]],
 [8,"Cere atribuirea corectă a trei trasori cu căi de excreție diferite și inversează indicația furosemidului din același paragraf."],["secreţie tubulară","deficienţă de fotoni"]),

q("nefrologie-adv-016",["Cistouretrografia:",
 ["verifică refluxul vezico-ureteral la copii cu infecții recurente","este de elecție la adult, hipertrofia vezicală accentuând refluxul","se face prin puncție percutanată pielocaliceală","nu necesită cateterism vezical, contrastul fiind injectat intravenos","complicația principală este anevrismul arteriovenos (~20%)"],"A",1351,"Investigații — Cistouretrografia",
 "Recunoașterea indicației pediatrice a cistouretrografiei și a motivului pentru care este rar adecvată la adult.",
 ["Este utilizată la copiii cu infecții urinare recurente, după instilarea contrastului și îndepărtarea cateterului, pentru a verifica refluxul în timpul golirii.","Nu: este rar adecvată la adulți, deoarece hipertrofia vezicală duce la dispariția refluxului, nu la accentuarea lui.","Nu: puncția percutanată a sistemului pielocaliceal definește pielografia anterogradă, nu cistouretrografia.","Nu: procedura începe prin cateterizarea vezicii și instilarea contrastului, nu prin injectare intravenoasă.","Nu: anevrismul arteriovenos (~20%) figurează printre complicațiile biopsiei renale, nu ale cistouretrografiei."]],
 [8,"Distractorii mută detalii reale (pielografie, biopsie) pe o investigație învecinată și inversează efectul hipertrofiei vezicale la adult."],["Cistouretrografia","infecţii urinare recurente"]),

q("nefrologie-adv-017",["După biopsia renală transcutanată se recomandă:",
 ["repaus la pat 8–24 de ore","evitarea ridicării de greutăți 2 săptămâni","maximizarea aportului de lichide, contra cheagurilor","mobilizare imediată și restricție de lichide","puls și TA verificate abia la hematurie"],"ABC",1352,"Glomerulul și afectarea glomerulară — Biopsia renală transcutanată: Cadranul 36.6",
 "Aplicarea măsurilor post-biopsie din Cadranul 36.6 (repaus, efort, hidratare, monitorizare).",
 ["Se recomandă pansament sub presiune pe locul biopsiei și repaus la pat 8–24 de ore (Cadranul 36.6).","Pacientul este sfătuit să evite ridicarea de greutăți sau grădinăritul timp de 2 săptămâni.","Se recomandă maximizarea aportului de lichide pentru a preveni formarea de cheaguri.","Nu: se recomandă repaus la pat 8–24 de ore și maximizarea aportului de lichide, nu mobilizare imediată și restricție hidrică.","Nu: pulsul și tensiunea arterială se verifică regulat după biopsie, nu doar la apariția hematuriei."]],
 [8,"Distractorii inversează două măsuri consecutive din același cadran (hidratare versus restricție, monitorizare versus așteptarea hematuriei)."],["8-24 ore","2 săptămâni"]),

q("nefrologie-adv-018",["Complicațiile biopsiei renale transcutanate:",
 ["hematurie macroscopică la până la 10%","hematurie cu necesar de transfuzie în 1–3%","o mortalitate de aproximativ 10%","ocluzie angiografică sau nefrectomie la 1 din 40","anevrism arteriovenos la ~2%, cu impact hemodinamic"],"AB",1352,"Glomerulul și afectarea glomerulară — Complicațiile biopsiei: Cadranul 36.7",
 "Reținerea frecvențelor numerice ale complicațiilor biopsiei, inclusiv a evenimentelor rare dar grave.",
 ["Hematuria macroscopică apare la până la 10% dintre pacienți (Cadranul 36.7).","Hematuria abundentă care necesită transfuzie apare în 1–3% din cazuri.","Nu: rata mortalității este de aproximativ 0,1%, nu de 10%.","Nu: ocluzia angiografică a vasului sau nefrectomia sunt necesare la aproximativ 1 din 400 de pacienți, nu 1 din 40.","Nu: anevrismul arteriovenos apare la aproximativ 20% și este aproape fără semnificație clinică."]],
 [8,"Toate distractorii folosesc ordine de mărime reale din același tablou, deplasate cu un factor de 10."],["până la10%","aproximativ 0,1%"]),

q("nefrologie-adv-019",["În descrierea leziunilor glomerulare:",
 ["focal: leziunea afectează o parte dintre glomeruli","difuz (global): peste 75% din glomeruli afectați","semilunele: proliferare endotelială în spațiul lui Bowman","segmentar: implicarea simetrică a întregului glomerul","proliferativ: perete capilar îngroșat, fără celularitate crescută"],"AB",1352,"Glomerulul și afectarea glomerulară — Termeni des utilizați",
 "Aplicarea definițiilor histologice (focal, difuz, semilune) și evitarea confuziei cu „segmentar” și „modificări ale membranei”.",
 ["„Focal” înseamnă că leziunea este prezentă în unii, dar nu în toți glomerulii (Cadranul 36.8).","„Difuz (global)” înseamnă că majoritatea glomerulilor (>75%) conțin leziunea.","Nu: formarea de semilune înseamnă proliferarea celulelor epiteliale, cu celule mononucleare, în spațiul lui Bowman.","Nu: „segmentar” înseamnă că este afectată doar o parte a glomerulului, nu întregul glomerul.","Nu: „proliferativ” înseamnă creșterea numărului de celule; îngroșarea peretelui capilar corespunde „modificărilor membranei”."]],
 [8,"Distractorii schimbă etichetele a două perechi de termeni adiacenți din același cadran (segmentar/global, proliferativ/membranar)."],[">75%","Formarea de semilune"]),

q("nefrologie-adv-020",["Bariera de filtrare glomerulară:",
 ["cuprinde endoteliul fenestrat, membrana bazală și podocitele","diafragma cu fante conține nefrină, podocină și CD2AP","anomaliile α-actininei-4 provoacă sindromul Alport","rearanjarea actinei șterge procesele podocitare, cu albuminurie","nefrina fixează podocitele de MBG prin distroglicani"],"ABD",1352,"Glomerulul și afectarea glomerulară — Bariera de filtrare (diafragma cu sită)",
 "Corelarea structurii barierei de filtrare cu proteinele diafragmei și cu consecința anomaliilor de citoschelet.",
 ["Bariera de filtrare este alcătuită din endoteliul fenestrat, membrana bazală glomerulară și podocite.","Proteinele diafragmei cu fante includ nefrina, CD2AP, TRPC6, podocina, P-caderina, cateninele și zonula occludens-1.","Nu: anomaliile proteinelor citoscheletale precum α-actinina-4 provoacă glomeruloscleroză focală și segmentară ereditară.","Rearanjarea citoscheletului de actină produce ștergerea proceselor podocitare, cu trecerea albuminei în urină.","Nu: podocitele se atașează de MBG prin molecule de adeziune (α3β1 și distroglicani); nefrina aparține diafragmei cu fante."]],
 [8,"Distractorul plasează nefrina la joncțiunea podocit–MBG, inversând rolurile a două seturi de proteine din același paragraf."],["diafragma cu fante","a-actinina-4"]),

q("nefrologie-adv-021",["Un bărbat de 34 de ani are edeme, proteinurie de 8 g/zi și albumină serică 18 g/L. Referitor la sindromul său nefrotic:",
 ["hiperlipidemia rezultă din sinteza crescută de lipoproteine","ficatul sănătos produce 10–12 g albumină/zi","pierderea de 3,5 g/zi poate produce hipoalbuminemie","hiperlipidemia reflectă sinteza scăzută de apolipoproteină B","hipoalbuminemia apare abia la proteinurie >10 g/zi"],"ABC",1353,"Glomerulul și afectarea glomerulară — Fiziopatologia sindromului nefrotic",
 "Înțelegerea discordanței dintre pierderea urinară de 3,5 g/zi, capacitatea de sinteză hepatică și mecanismul hiperlipidemiei.",
 ["Hiperlipidemia rezultă din sinteza crescută de lipoproteine (apoB, C-III, Lp(a)), ca urmare a nivelului scăzut de albumină.","Ficatul sănătos sintetizează 10–12 g de albumină pe zi, iar aportul obișnuit este de aproximativ 70 g proteine zilnic.","O pierdere de 3,5 g/zi este suficientă pentru a produce hipoalbuminemie, în ciuda sintezei hepatice și a aportului dietetic.","Nu: hiperlipidemia se datorează sintezei crescute de lipoproteine, inclusiv apolipoproteina B, nu scăderii acesteia.","Nu: o pierdere de 3,5 g/zi poate duce la hipoalbuminemie, deși aportul obișnuit este de aproximativ 70 g proteine/zi."]],
 [8,"Vigneta cere reconcilierea unui prag de 3,5 g/zi cu o sinteză hepatică aparent superioară și cu mecanismul hiperlipidemiei."],["10-12 g pe","aproximativ 70 g"]),

q("nefrologie-adv-022",["În sindromul nefrotic:",
 ["pierderea de imunoglobuline favorizează infecțiile pneumococice","se recomandă vaccinarea antipneumococică","statina este tratamentul inițial al hipercolesterolemiei","tromboza venei renale impune anticoagulare permanentă","sepsisul este o cauză minoră de mortalitate"],"ABCD",1354,"Glomerulul și afectarea glomerulară — Sindromul nefrotic: infecții, lipide și tromboză",
 "Completarea măsurilor generale cu riscul infecțios (pneumococ, vaccinare), hiperlipidemia tratată cu statină și indicațiile de anticoagulare.",
 ["Susceptibilitatea la infecții se datorează parțial pierderii urinare de imunoglobuline, iar infecțiile pneumococice sunt frecvente.","Vaccinarea antipneumococică este recomandată explicit în sindromul nefrotic.","Tratamentul hipercolesterolemiei începe cu un inhibitor al HMG-CoA reductazei (statină).","Anticoagularea profilactică pe termen lung poate fi indicată, iar tromboza venei renale impune anticoagulare permanentă.","Nu: sepsisul este o cauză majoră de deces în sindromul nefrotic, nu un eveniment minor."]],
 [8,"Extinde un capitol deja abordat spre detalii ușor omise (pneumococ, statină, tromboza venei renale) și inversează ierarhia cauzelor de deces."],["Vaccinarea anti-pneumococică","inhibitor al HMG-CoA"]),

q("nefrologie-adv-023",["Corticoterapia în nefropatia cu leziuni minime:",
 ["la copii, prednisolonul 60 mg/m²/zi reduce proteinuria la peste 95%","la adulți, răspunsul poate apărea abia după mai multe luni","remisiunea de 4 luni face recidiva foarte rară","se începe imediat, chiar fără edeme sau hipoalbuminemie","răspunsul adulților este similar celui al copiilor"],"AB",1354,"Glomerulul și afectarea glomerulară — Nefropatia cu leziuni minime: corticoterapia",
 "Reținerea protocolului pediatric (doze, durate, rata de 95%) și a particularităților de răspuns, durată a remisiunii și temporizare la adult.",
 ["La copii, prednisolon 60 mg/m² zilnic (maximum 80 mg/zi) 4–6 săptămâni, urmat de 40 mg/m² la două zile încă 4–6 săptămâni, reduce proteinuria la peste 95%.","La adulți, răspunsul poate apărea abia după mai multe luni: 12 săptămâni de terapie zilnică plus 12 săptămâni în zile alternative.","Nu: o recidivă ulterioară devine foarte rară dacă remisiunea durează 4 ani după corticoterapie, la copii și la adulți.","Nu: terapia ar trebui în general temporizată dacă pierderea proteică nu produce hipoalbuminemie sau edeme.","Nu: ratele de răspuns la adulți sunt semnificativ mai mici decât la copii."]],
 [8,"Cele două scheme (4–6 săptămâni versus 12+12 săptămâni) sunt ușor de inversat, iar distractorul transformă temporizarea rațională într-o indicație urgentă."],["maximum 80 mg/zi","mai mult de 95%"]),

q("nefrologie-adv-024",["Terapia de linia a doua în nefropatia cu leziuni minime recidivantă:",
 ["ciclosporina/tacrolimusul se continuă pe termen lung","ciclofosfamidă 1,5–2,0 mg/kg/zi timp de 8–12 luni","la copii, maximum două cure de ciclofosfamidă","levamisol 2,5 mg/kg în zile alternative, la copii corticodependenți","rituximabul (anti-CD20) este inactiv, boala fiind strict podocitară"],"ACD",1355,"Glomerulul și afectarea glomerulară — Nefropatia cu leziuni minime: agenți de linia a doua",
 "Ierarhizarea CNI, ciclofosfamidei (doză, durată, limita de două cure la copii), levamisolului și rituximabului în NLM recidivantă.",
 ["Ciclosporina sau tacrolimusul pot fi eficiente, dar trebuie continuate pe termen lung pentru a preveni recidiva la întrerupere.","Nu: ciclofosfamida 1,5–2,0 mg/kg/zi se administrează 8–12 săptămâni, cu prednisolon 7,5–15 mg/zi, crescând șansa remisiunii de lungă durată.","La copii nu se prescriu mai mult de două cure de ciclofosfamidă, din cauza riscului de infertilitate (azoospermie, insuficiență ovariană).","Levamisolul 2,5 mg/kg (maximum 150 mg) în zile alternative poate menține remisiunea la copiii dependenți de corticoizi.","Nu: rituximabul, anticorp monoclonal anti-CD20, este menționat ca opțiune terapeutică în nefropatia cu leziuni minime."]],
 [8,"Combină doze exacte din trei clase și o limită pediatrică de toxicitate, iar distractorul neagă un agent biologic explicit din text."],["1,5-2,0 mg/kg","2,5 mg/kg"]),

q("nefrologie-adv-025",["Sindromul nefrotic congenital prin mutația nefrinei:",
 ["frecvență de 1/8.200 nașteri în unele populații","răspunde prompt la corticoterapia pediatrică standard","nefrina este un lanț de colagen IV (COL4A5)","frecvență de 1/8 milioane de nașteri","se datorează genei PKHD1 de pe cromozomul 6"],"A",1355,"Glomerulul și afectarea glomerulară — Sindromul nefrotic congenital și mutațiile podocitare",
 "Recunoașterea nefrinei ca proteină a diafragmei și a heterogenității genetice a SNRS, distinctă de Alport.",
 ["Mutația nefrinei apare cu o frecvență de 1 la 8.200 de nașteri în unele populații și se prezintă ca sindrom nefrotic congenital.","Nu: formele genetice definesc rezistența la steroizi, nu un răspuns prompt.","Nu: nefrina este o proteină transmembranară a diafragmei cu fante, nu un lanț de colagen IV.","Nu: frecvența este de 1 la 8.200; incidența de 1 la 2 milioane aparține bolii anti-MBG.","Nu: gena PKHD1 aparține bolii polichistice autozomal recesive, nu sindromului nefrotic congenital."]],
 [8,"Distractorii atribuie acestor mutații fie răspunsul steroidian al NLM, fie gena Alport, ambele din capitolul imediat învecinat."],["1 la 8.200","mai mult de 30 de gene"]),

q("nefrologie-adv-026",["Glomeruloscleroza focală și segmentară primară:",
 ["rezistența la prednisolon se declară după 6 săptămâni","BCR terminală la circa 50% în 10 ani","recidivează foarte frecvent pe grefă, cu prognostic rezervat","ciclosporina și tacrolimusul nu reduc proteinuria","varianta perihilară este tipică formei primare"],"BC",1356,"Glomerulul și afectarea glomerulară — GSFS: tratament și evoluție",
 "Reținerea duratei de 6 luni înainte de a declara rezistența, a riscului de 50% ESRD/10 ani și a recidivei pe grefă.",
 ["Nu: prednisolonul 0,5–2 mg/kg pe zi se continuă 6 luni înainte ca pacientul să fie considerat rezistent, rezistența fiind frecventă.","Aproximativ 50% progresează spre BCR terminală în 10 ani de la diagnostic, mai ales cei rezistenți la terapie.","Rata de reapariție a bolii pe grefa renală este foarte mare, cu prognostic rezervat.","Nu: ciclosporina sau tacrolimusul pot reduce proteinuria; plasmafereza are rezultate modeste post-transplant.","Nu: varianta perihilară se observă frecvent în GSFS secundară, nu ca marcă a formei primare."]],
 [8,"Pragurile 6 luni și 50%/10 ani sunt ușor de permutat, iar distractorii inversează rolul CNI și al variantei perihilare."],["6 luni","50% dintre pacienţi"]),

q("nefrologie-adv-027",["GSFS secundară se asociază frecvent cu:",
 ["infecții virale: HIV-1, parvovirus B19, CMV, virusul Epstein-Barr","heroina, interferonii, litiul, sirolimusul, inhibitorii de calcineurină","variantele G1/G2 ale APOL1 (cromozomul 22)","infecția podocitară cu HIV-1, cu pierderea sinaptopodinei","varianta colabantă, patognomonică pentru GSFS primară autoimună"],"ABCD",1356,"Glomerulul și afectarea glomerulară — GSFS secundară: asocieri",
 "Recunoașterea asocierilor virale, toxice și genetice (APOL1) ale GSFS secundare, inclusiv a HIVAN ultrastructural.",
 ["Infecțiile virale asociate includ HIV-1, parvovirusul B19, citomegalovirusul, virusul Epstein-Barr și virusul simian 40.","Medicamentele și drogurile asociate includ heroina, interferonii, steroizii anabolizanți, litiul, sirolimusul, pamidronatul și inhibitorii de calcineurină.","Sunt citate mutațiile genei APOL1 de pe cromozomul 22, variantele G1/G2.","În HIVAN, infecția directă a podocitelor cu HIV-1 se asociază cu pierderea factorului tumoral Wilms și a sinaptopodinei.","Nu: varianta colabantă este descrisă în HIVAN, deci în GSFS secundară, nu ca marcă a formei primare autoimune."]],
 [8,"Cere reținerea concomitentă a listei de viruși, a toxicului iatrogen și a locusului APOL1, cu un distractor care mută varianta colabantă la forma primară."],["APOL1","sinaptopodina"]),

q("nefrologie-adv-028",["Tratamentul glomerulonefritei membranoase autoimune cu risc de progresie:",
 ["rituximabul induce și menține remisiunea","ciclofosfamidă 1,5–2,5 mg/kg/zi 6–12 luni, plus prednisolon","clorambucil în lunile pare, prednisolon în lunile impare","ciclosporina sau tacrolimusul, cu recidive rare","corticoterapie orală în monoterapie, ca primă linie"],"ABC",1357,"Glomerulul și afectarea glomerulară — Glomerulonefrita membranoasă: tratament imunosupresor",
 "Memorarea regimurilor rituximab, ciclofosfamidă și clorambucil (inclusiv luni alternative) și a limitei CNI (recidivă frecventă).",
 ["Rituximabul (anti-CD20) este eficient în inducerea și menținerea remisiunii.","Ciclofosfamida 1,5–2,5 mg/kg pe zi timp de 6–12 luni se asociază cu prednisolon 1 mg/kg în zile alternative în primele 2 luni.","Clorambucilul 0,2 mg/kg pe zi se dă în lunile 2, 4 și 6, alternând cu prednisolon 0,4 mg/kg în lunile 1, 3 și 5.","Nu: ciclosporina sau tacrolimusul sunt utile, dar recidiva este frecventă, iar curele sunt mai lungi.","Nu: corticosteroizii orali în monoterapie nu aduc beneficiu; alchilanții sunt tratament de inducție, nu de rezervă."]],
 [8,"Cele două scheme cu alchilanți diferă prin luni și doze ușor permutabile, iar distractorul reia capcana corticoterapiei în monoterapie."],["anti-CD20","0,2 mg/kg pe zi"]),

q("nefrologie-adv-029",["Amiloidoza cu afectare renală:",
 ["formele cele mai frecvente sunt AL și AA","proteinuria Bence Jones caracterizează forma AA","colorația Roșu Congo arată birefringență în lumină polarizată","imunohistochimia identifică AL în ~40%, AA în ~100%","macroglosia caracterizează forma AA, nu AL"],"ACD",1358,"Glomerulul și afectarea glomerulară — Amiloidoza renală: clasificare și diagnostic",
 "Diferențierea AL de AA după precursor, proteină Bence Jones, Roșu Congo și randamentul imunohistochimiei.",
 ["Formele cele mai frecvente sunt AL (lanțuri ușoare sau imunoglobulină) și AA (proteina serică amiloid A), dintre cel puțin 20 de precursori.","Nu: în amiloidoza AL lanțurile ușoare (kappa sau lambda) se excretă în urină ca proteină Bence Jones; AA derivă din proteina serică amiloid A.","Colorația Roșu Congo examinată în lumină polarizată evidențiază birefringența caracteristică.","Imunohistochimia identifică AL în doar ~40% din cazuri, față de aproape 100% în AA.","Nu: macroglosia este descrisă în amiloidoza AL (și nu apare în ATTR), nu ca marcă a formei AA."]],
 [8,"Procentele 40% versus 100% și atribuirea greșită a macroglosiei testează detalii ușor inversabile din același capitol."],["Bence Jones","Roşu Congo"]),

q("nefrologie-adv-030",["Amiloidoza ATTR (transtiretină):",
 ["se transmite autozomal recesiv, transtiretina fiind hepatică","peste 80 de substituții descrise, ca Met30 și Ala60","transplantul hepatic este considerat terapia definitivă","creierul nu este afectat în amiloidoza sistemică dobândită","tratamentul de elecție: bortezomib cu rituximab"],"BCD",1358,"Glomerulul și afectarea glomerulară — Amiloidoza ATTR: genetică și tratament",
 "Recunoașterea transmiterii, a mutațiilor transtiretinei și a rolului transplantului hepatic, distinct de terapia AL.",
 ["Nu: amiloidoza ATTR este o boală autozomal dominantă; transtiretina este sintetizată predominant în ficat.","Sunt descrise peste 80 de substituții de aminoacizi, cu Met30 la toate rasele și Ala60 la englezi și irlandezi.","Transplantul hepatic, care îndepărtează proteina mutantă din sânge, este considerat terapia definitivă.","Creierul nu este afectat în amiloidoza sistemică dobândită, spre deosebire de depunerile din boala Alzheimer.","Nu: bortezomibul și rituximabul vizează amiloidoza AL (mielom), nu ATTR."]],
 [8,"Distractorul aplică tratamentul AL unei forme ereditare al cărei tratament definitiv este transplantul hepatic."],["autosomal dominantă","Met 30"]),

q("nefrologie-adv-031",["Nefropatia diabetică:",
 ["apare la 20–30% dintre diabetici","precoce scad RFG și volumul renal","țintele: TA <130/80 mmHg și HbA1c <7%","inhibitorii SGLT2 și agoniștii GLP-1 sunt citați în renoprotecție","afectează sub 5% dintre diabeticii de tip 2"],"ACD",1359,"Glomerulul și afectarea glomerulară — Nefropatia diabetică: istorie naturală și renoprotecție",
 "Integrarea prevalenței, a hiperfiltrării inițiale și a țintelor din Cadranul 36.12 cu noile clase antidiabetice.",
 ["Nefropatia diabetică apare la 20–30% dintre pacienții cu diabet zaharat tip 1 sau 2.","Nu: modificările precoce sunt hiperfiltrarea glomerulară (RFG >150 ml/min pe m²) și creșterea volumului renal.","Țintele de renoprotecție (Cadranul 36.12) includ TA <130/80 mmHg, proteinurie <0,3 g/24 h, HbA1c <7% și dietă de 0,8–1 g/kg.","Inhibitorii SGLT2 (dapagliflozin, canagliflozin, empagliflozin) și agoniștii GLP-1 (liraglutidă, semaglutidă) sunt menționați explicit.","Nu: prevalența este de 20–30%, iar boala este principala cauză de BCR terminală în Occident."]],
 [8,"Combină un prag de hiperfiltrare cu țintele numerice de renoprotecție, distractorul coborând drastic prevalența reală."],["20-30%","<130/80 mmHg"]),

q("nefrologie-adv-032",["Glomerulonefrita rapid progresivă (GNRP):",
 ["poate evolua cu depozite imune sau pauci-imun (ANCA)","patternul liniar de imunofluorescență corespunde bolii anti-MBG","patternul granular de imunofluorescență corespunde bolii anti-MBG","vasculitele ANCA-asociate sunt forme pauci-imune de GNRP","forma pauci-imună are depozite liniare de IgG"],"ABD",1360,"Glomerulul și afectarea glomerulară — GNRP: tipuri și imunofluorescență",
 "Clasificarea GNRP după patternul de imunofluorescență (liniar, granular, pauci-imun) și corespondența cu anti-MBG, complexe imune și ANCA.",
 ["GNRP poate evolua cu depozite imune (anti-MBG sau complexe imune) sau pauci-imun (ANCA: PR3 și/sau MPO).","Patternul liniar de imunofluorescență corespunde bolii anti-MBG (Cadranul 36.13).","Nu: patternul granular corespunde GNRP mediate de complexe imune; boala anti-MBG are pattern liniar.","Vasculitele ANCA-asociate sunt listate la forma pauci-imună a GNRP.","Nu: forma pauci-imună nu are depozite de imunoglobuline; depozitele liniare de IgG caracterizează boala anti-MBG."]],
 [8,"Cere harta IF–etiologie; distractorul atribuie patternul granular unei boli fără depozite."],["pauci-imune","anti-MBG"]),

q("nefrologie-adv-033",["Glomerulonefrita poststreptococică:",
 ["nefrita apare la 1–3 săptămâni după infecție","proliferare endocapilară cu neutrofile, IgG și complement","aspecte similare apar în nefropatia cu leziuni minime","recuperare completă la sub 5%","nefrita debutează simultan cu faringita streptococică"],"AB",1361,"Glomerulul și afectarea glomerulară — Glomerulonefrita poststreptococică",
 "Fixarea intervalului postinfecțios, a tabloului histologic cu neutrofile și a prognosticului de recuperare de ~50%.",
 ["Nefrita acută apare la 1–3 săptămâni după o infecție streptococică.","Histologia arată proliferare endocapilară cu neutrofile și depunere de IgG și complement.","Nu: aspecte similare apar în GN postinfecțioase non-streptococice, nu în nefropatia cu leziuni minime, care nu are depozite.","Nu: recuperarea completă este citată în aproximativ 50% din cazuri, nu sub 5%.","Nu: nefrita urmează la 1–3 săptămâni după infecție; hematuria sincronă cu infecția căilor aeriene este a nefropatiei cu IgA."]],
 [8,"Capcana clasică este inversarea intervalului latență (poststreptococic) versus sinchronicitate (IgA)."],["1-3 săptămâni","aproximativ 50%"]),

q("nefrologie-adv-034",["Clasificarea Oxford a nefropatiei cu IgA:",
 ["4–5 celule pe arie mezangială înseamnă scor 1","histologia are valoare prognostică independentă de clinică","S1 înseamnă scleroza unei părți din ghem","semilunele sunt frecvente, mai ales după hematurie","înlocuiește imunofluorescența în diagnostic"],"ABCD",1362,"Glomerulul și afectarea glomerulară — Nefropatia cu IgA: clasificarea Oxford",
 "Aplicarea pragurilor celulare ale scorului M și înțelegerea valorii prognostice independente a histologiei Oxford.",
 ["Hipercelularitatea mezangială se notează 0 pentru <4 celule pe arie mezangială, 1 pentru 4–5, 2 pentru 6–7 și 3 pentru ≥8, apoi se face media pe glomeruli.","Caracteristicile histologice din clasificarea Oxford au semnificație prognostică independentă de tabloul clinic.","Scorul include glomeruloscleroza: S1 când o parte din ghemul glomerular este afectată.","Formarea concomitentă de semilune este frecventă, mai ales după un episod de hematurie.","Nu: diagnosticul rămâne imunofluorescența cu depozite mezangiale de IgA1; clasificarea Oxford stadializează, nu înlocuiește IF."]],
 [8,"Pragurile 4–5 versus 6–7 celule sunt ușor de permutat, iar distractorul transformă un scor prognostic într-un substitut de diagnostic."],["4-5 celule","Clasificarea histologică Oxford"]),

q("nefrologie-adv-035",["Sindromul Alport:",
 ["transmitere legată de X (COL4A5) la circa 85%","anomalii oculare (lenticonus anterior) la circa 15%","cauzează circa 5% din ESKD-ul pediatric","asociază surditate de transmisie și boală renală progresivă","se transmite autozomal recesiv, prin gena PKHD1"],"ABC",1362,"Glomerulul și afectarea glomerulară — Sindromul Alport",
 "Corelarea geneticii COL4A5 legate de X cu manifestările extrarenale (ochi, auz neurosenzorial) și contribuția la ESKD pediatric.",
 ["La aproximativ 85% dintre pacienți mutația este legată de cromozomul X, în gena COL4A5.","Aproximativ 15% au anomalii oculare, precum lenticonus anterior bilateral și pete retiniene.","Boala este progresivă și reprezintă circa 5% din cazurile care ajung la ESKD în copilărie sau adolescență.","Nu: sindromul Alport asociază surditate neurosenzorială cu boală renală progresivă.","Nu: gena PKHD1 de pe cromozomul 6p definește forma autozomal recesivă a bolii polichistice, nu sindromul Alport."]],
 [8,"Distractorul mută gena și cromozomul bolii polichistice recesive pe Alport, o confuzie clasică de locus."],["COL4a5","surditate neurologica"]),

q("nefrologie-adv-036",["Boala anti-MBG (sindromul Goodpasture):",
 ["reprezintă 15–20% din glomerulonefritele rapid progresive","aproape două treimi dintre pacienți au hemoragie pulmonară","se tratează cu plasmafereză, corticosteroizi și ciclofosfamidă","insuficiența renală oligurică este de regulă reversibilă","evoluează cu remisiuni și reactivări, ca LES"],"ABC",1363,"Glomerulul și afectarea glomerulară — Boala anti-MBG: epidemiologie, tratament, prognostic",
 "Integrarea epidemiologiei, a triadei terapeutice și a pragului de ireversibilitate, cu recunoașterea naturii „single hit”.",
 ["Boala anti-MBG reprezintă 15–20% din GNRP, dar sub 5% din toate glomerulonefritele, cu o incidență de 1 la 2 milioane.","Aproape două treimi au hemoragie pulmonară (Goodpasture); restul, peste 50 de ani, au afectare strict renală, egal la ambele sexe.","Tratamentul combină plasmafereza, corticosteroizii și ciclofosfamida.","Nu: odată cu apariția oliguriei, insuficiența renală este de cele mai multe ori ireversibilă.","Nu: spre deosebire de alte boli autoimune, nu urmează un ciclu remisie–reactivare; autoanticorpii dispar spontan în ~3 ani („single hit”)."]],
 [8,"Pragul de creatinină și contrastul cu bolile cu recăderi sunt capcane; distractorul atribuie evoluția lupică unei boli „single hit”."],["1 la 2 milioane","schimburi plasmatice"]),

q("nefrologie-adv-037",["Vasculitele ANCA-asociate cu afectare renală:",
 ["sunt pauci-imune, fără depozite de imunoglobuline în vase","includ GPA, poliangeita microscopică și vasculita limitată renal","patru clase histologice: focală, cu semilune, mixtă, sclerotică","serologia ANCA este standardul de aur diagnostic","granulomatoza eozinofilică cu poliangeită este aproape constant ANCA-pozitivă"],"ABC",1363,"Glomerulul și afectarea glomerulară — Vasculite ANCA: spectru și clasificare histologică",
 "Recunoașterea spectrului pauci-imun, a celor patru clase histologice, a histologiei ca standard de aur și a excepției eozinofilice frecvent ANCA-negative.",
 ["Sunt vasculite pauci-imune, caracterizate prin absența depozitelor de imunoglobuline în pereții vaselor mici.","GPA, poliangeita microscopică și vasculita limitată renal sunt enumerate; EGPA este frecvent ANCA-negativă.","Clasificarea histologică are patru categorii: focală (≥50% glomeruli normali), cu semilune, mixtă și sclerotică (≥50% scleroză globală).","Nu: histologia renală este considerată standardul de aur pentru diagnostic și prognostic.","Nu: granulomatoza eozinofilică cu poliangeită (EGPA) este frecvent ANCA-negativă."]],
 [8,"Pragurile de 50% din patru clase sunt ușor de amestecat, iar distractorul inversează serologia EGPA."],["imunglobuline","standard de aur"]),

q("nefrologie-adv-038",["Serologia ANCA în vasculitele de vase mici:",
 ["PR3-ANCA pozitiv la >90% în GPA activă","anti-MPO este prezent la majoritatea pacienților cu MPA","dublă pozitivitate PR3/MPO la până la 10%","vasculita prin propiltiouracil este de obicei PR3-ANCA","ANCA și anticorpii anti-MBG sunt incompatibili serologic"],"ABC",1364,"Glomerulul și afectarea glomerulară — ANCA: specificități PR3/MPO și forme induse de medicamente",
 "Maparea PR3–GPA versus MPO–MPA, a dublei pozitivități (~10%) și a vasculitei medicamentoase MPO-ANCA, cu recunoașterea overlap-ului anti-MBG.",
 ["PR3-ANCA este pozitiv la peste 90% dintre pacienții cu GPA activă și la până la 50% dintre cei cu MPA.","Anti-MPO este prezent la majoritatea pacienților cu poliangeită microscopică (MPA).","Pozitivitatea pentru ambele specificități (PR3 și MPO) apare la până la 10% dintre pacienți.","Nu: propiltiouracilul, hidralazina, minociclina și penicilamina pot induce vasculită cel mai frecvent MPO-ANCA, adesea în titruri foarte mari.","Nu: ANCA pot apărea împreună cu anticorpii anti-MBG, la pacienți cu istoric de Goodpasture."]],
 [8,"Procentele >90%, 50% și 10% sunt permutabile, iar distractorul neagă overlap-ul ANCA–anti-MBG descris în același paragraf."],[">90%","propiltiouracil"]),

q("nefrologie-adv-039",["Tratamentul vasculitelor ANCA-asociate:",
 ["inducție cu steroizi orali și ciclofosfamidă intravenos","azatioprina poate înlocui ciclofosfamida după remisiune","rituximabul la 3 luni menține remisiunea","până la 25% din PR3-ANCA au anticorpi anti-plasminogen","micofenolatul este superior azatioprinei în menținere"],"ABCD",1364,"Glomerulul și afectarea glomerulară — Vasculite ANCA: inducție și întreținere",
 "Reținerea schemei de inducție, a superiorității azatioprinei față de MMF și a rituximabului de întreținere la 3 luni.",
 ["Inducția se face cu corticosteroizi orali în doze mari și ciclofosfamidă intravenos pe termen scurt (6–12 luni).","După remisiune, azatioprina poate înlocui ciclofosfamida și a fost mai eficientă decât micofenolatul într-un studiu comparativ.","Rituximabul administrat la fiecare 3 luni, în doză fixă, s-a dovedit util în menținerea remisiunii.","Până la 25% dintre pacienții PR3-ANCA dezvoltă anticorpi împotriva plasminogenului uman și/sau a t-PA.","Nu: azatioprina a fost mai eficientă decât micofenolatul în menținerea remisiunii, iar rituximabul rămâne o opțiune de întreținere."]],
 [8,"Inversează ierarhia azatioprină–MMF, un rezultat de studiu contraintuitiv față de uzul reumatologic al MMF."],["Azatioprina","la fiecare 3 luni"]),

q("nefrologie-adv-040",["Glomerulonefrita mezangiocapilară (membranoproliferativă):",
 ["tipul 1: depozite subepiteliale, dublarea membranei bazale","tipul 2 se poate asocia cu lipodistrofie parțială","tipul 3 combină trăsăturile tipurilor 1 și 2","C3 scăzut, C4 păstrat: activarea căii alterne","tipul 1: depozite dense intramembranoase, C3 normal"],"BCD",1365,"Glomerulul și afectarea glomerulară — GNMC: tipuri 1, 2 și 3",
 "Diferențierea ultrastructurală și complementologică a celor trei tipuri de GNMC, inclusiv asocierea tipului 2 cu lipodistrofia.",
 ["Nu: tipul 1 are proliferare mezangială, depozite subendoteliale și dublarea membranei bazale (aspect de „linie de tramvai”).","Nefropatia C3 / tipul 2 (boala cu depozite dense) se colorează puternic pentru C3 și se poate asocia cu pierderea grăsimii faciale și toracice.","Tipul 3 are caracteristici mixte ale tipurilor 1 și 2.","În nefropatia C3, C3 scăzut cu C4 relativ păstrat sugerează activarea căii alterne a complementului (convertaza C3).","Nu: depozitele dense intramembranoase definesc tipul 2, nu tipul 1; tiparul C3/C4 este de asemenea inversat."]],
 [8,"Cele trei tipuri se deosebesc prin sediul depozitelor și prin C3 versus C4, ușor de oglindit."],["linie de tramvai","factor nefritic C3"]),

q("nefrologie-adv-041",["Tratamentul glomerulonefritei mezangiocapilare și al nefropatiei C3:",
 ["proteinurie non-nefrotică, funcție normală: control TA suficient","copii nefrotici: prednison 40 mg/m² în zile alternative","aspirină și/sau dipiridamol, încercate 6–12 luni","eculizumabul, anticorp anti-CD20, este eficient în nefropatia C3","nefropatia C3 genetică recidivează rar pe grefă"],"ABC",1365,"Glomerulul și afectarea glomerulară — GNMC: tratament",
 "Adaptarea intensității (observație, steroizi, antiagregare, eculizumab anti-C5) la fenotipul clinic și recunoașterea recurenței C3 pe grefă.",
 ["În forma idiopatică cu funcție renală normală și proteinurie non-nefrotică nu este necesară terapie specifică, ci controlul TA, ideal cu IECA.","La copiii cu proteinurie nefrotică se poate justifica prednison 40 mg/m² în zile alternative, timp de 6–12 luni.","Antiagregarea cu aspirină 325 mg și/sau dipiridamol 75–100 mg zilnic poate fi încercată 6–12 luni.","Nu: eculizumabul este un anticorp anti-C5, folosit cu succes în nefropatia C3, inclusiv în recurențele post-transplant.","Nu: nefropatia C3 genetică recidivează pe grefă la o proporție mare, de obicei în primul an, mai frecvent decât GNMC tip 1."]],
 [8,"Inversează riscul de recurență pe grefă între nefropatia C3 și tipul 1, pe lângă dozele antiagregante ușor de confudat."],["eculizumab","40 mg/m2"]),

q("nefrologie-adv-042",["Glomerulopatia fibrilară din spectrul MGRS:",
 ["fibrilele au 20–30 nm, sunt DNAJB9-pozitive și Roșu Congo-negative","proteinurie nefrotică la aproximativ 60% dintre pacienți","40–50% ajung la BCR terminală în 2–6 ani","forma imunotactoidă: microtubuli mai mari, 30–40 nm","fibrile identice amiloidului AL, Roșu Congo-pozitive"],"ABCD",1366,"Glomerulul și afectarea glomerulară — Glomerulopatia fibrilară și imunotactoidă",
 "Diferențierea ultrastructurală (calibru, DNAJB9, Roșu Congo) și a prognosticului față de amiloid și de forma imunotactoidă.",
 ["Glomerulopatia fibrilară este DNAJB9-pozitivă, are fibrile de 20–30 nm (față de ~10 nm în amiloidoză) și nu se colorează cu Roșu Congo.","Proteinuria de rang nefrotic apare la ~60%, hematuria microscopică la ~70%, iar HTA și BCR la ~50%.","40–50% dintre pacienți ajung la BCR terminală în 2–6 ani, fără tratament eficient în forma idiopatică.","Glomerulopatia imunotactoidă are microtubuli mai mari, de 30–40 nm.","Nu: negativitatea la Roșu Congo și calibrul mai mare (20–30 nm) deosebesc glomerulopatia fibrilară de amiloid."]],
 [8,"Caliibrele 10, 20–30 și 30–40 nm sunt concepute să fie permutabile între amiloid, fibrilară și imunotactoidă."],["DNAJB9","20-30"]),

q("nefrologie-adv-043",["Clasificarea ISN/RPS a nefritei lupice:",
 ["clasa III: focală, <50% glomeruli afectați","clasa IV: difuză, >50% glomeruli afectați","clasa V (membranoasă) coexistă uneori cu alte clase","clasa VI: pragul este de 50% glomeruli sclerozați global","clasa IV este forma cea mai ușoară"],"ABC",1366,"Glomerulul și afectarea glomerulară — Nefrita lupică: clasificarea ISN/RPS",
 "Aplicarea pragurilor 50% (III versus IV) și 90% (VI) și a caracteristicilor claselor III și V.",
 ["Clasa III este nefrită lupică focală, cu implicarea a <50% din glomeruli, și reprezintă 10–20% din NL (Cadranul 36.16).","Clasa IV este nefrită lupică difuză, cu implicarea a >50% din glomeruli.","Clasa V (membranoasă) afectează 10–20% dintre pacienți și poate coexista cu alte clase.","Nu: clasa VI (nefrită lupică sclerozantă avansată) cere ≥90% glomeruli sclerozați global.","Nu: clasa IV este forma proliferativă difuză severă, cu >50% glomeruli afectați, nu forma cea mai ușoară."]],
 [8,"Pragurile 50% și 90% sunt deplasate deliberat, o capcană tipică de stadializare."],["<50% din glomeruli","Clasa VI"]),

q("nefrologie-adv-044",["Tratamentul nefritei lupice proliferative:",
 ["steroizi și ciclofosfamidă i.v. în doze mari, pentru inducție","în populația albă, ciclofosfamida în doze mici este inferioară dozelor mari","MMF poate depăși ciclofosfamida în unele populații","rituximabul poate fi util în formele refractare severe","azatioprina de întreținere este inferioară ciclosporinei"],"ACD",1367,"Glomerulul și afectarea glomerulară — Nefrita lupică: tratament",
 "Nuanțarea inducției (ciclofosfamidă în doze mari versus mici, MMF) și a locului rituximabului, fără a inversa datele de întreținere.",
 ["Steroizii și ciclofosfamida intravenos în doze mari sunt scheme de inducție.","Nu: în populația albă, ciclofosfamida în doze mici are eficacitate similară dozelor mari, cu toxicitate mai redusă.","MMF poate avea eficacitate similară, iar ciclofosfamida poate fi inferioară MMF în unele populații.","Rituximabul poate fi util în formele refractare severe, deși trialurile randomizate nu au fost consistente.","Nu: azatioprina are eficacitate similară cu ciclosporina în reducerea riscului de recidivă."]],
 [8,"Capcana este inversarea relației azatioprină–ciclosporină și generalizarea MMF ca unic standard, ignorând nuanța etnică a ciclofosfamidei."],["doze mici","nefritele lu pice refractare"]),

q("nefrologie-adv-045",["Crioglobulinemiile cu afectare glomerulară:",
 ["tipurile II și III sunt crioglobulinemii mixte","tipul II: antiglobulină de obicei IgM monoclonală","peste 90% din cazuri sunt de tip I","sub 1% din formele mixte sunt idiopatice","histologia este similară nefropatiei cu leziuni minime"],"AB",1367,"Glomerulul și afectarea glomerulară — Crioglobulinemiile mixte",
 "Diferențierea tipurilor II/III, a frecvenței tipului III și a histologiei similare GNMC, nu NLM.",
 ["Tipurile II și III sunt mixte, antiglobulinele legându-se de fragmentul Fc al IgG policlonale.","În tipul II, antiglobulinele sunt de obicei IgM monoclonale.","Nu: 40–50% din toate crioglobulinemiile sunt de tip III; tipul I nu reprezintă peste 90% din cazuri.","Nu: în aproximativ 30% dintre crioglobulinemiile mixte nu se identifică o cauză.","Nu: histologia este similară glomerulonefritei mezangiocapilare, nu nefropatiei cu leziuni minime."]],
 [8,"Procentele 40–50% și 30% sunt ușor de permutat, iar distractorul mută histologia spre NLM."],["tip III","30% dintre"]),

q("nefrologie-adv-046",["O femeie de 48 de ani cu sclerodermie sistemică dezvoltă HTA accelerată și creșterea bruscă a creatininei. Despre această complicație:",
 ["afectează circa 10% dintre pacienții cu SSc","este o vasculită ANCA-pozitivă, identică cu GPA","leziunea dominantă: semilune, ca în Goodpasture","afectează peste 70% în primii doi ani","CXCL4 scade în SSc și protejează de fibroză"],"A",1368,"Glomerulul și afectarea glomerulară — Criza renală din scleroza sistemică",
 "Recunoașterea crizei renale sclerodermice (prevalență ~10%, microangiopatie trombotică) și diferențierea de vasculita ANCA.",
 ["Aproximativ 10% dintre pacienții cu scleroză sistemică (SSc) dezvoltă crize renale.","Nu: leziunea este o tromboză a arterelor mici și arteriolelor, nu o vasculită ANCA de tip GPA.","Nu: semilunele caracterizează GNRP, inclusiv Goodpasture, nu criza renală sclerodermică.","Nu: crizele renale apar la aproximativ 10% dintre pacienții cu SSc, nu la peste 70%.","Nu: CXCL4, produs de celulele dendritice plasmocitoide, se asociază cu fibroza, nu o previne."]],
 [8,"Vigneta împinge spre un diagnostic de vasculită ANCA, în timp ce textul descrie o microangiopatie trombotică în ~10% din SSc."],["10% dintre pacienţii cu SSc","CXCL4"]),

q("nefrologie-adv-047",["Tuberculoza renală și abcesul renal:",
 ["histologia arată nefrită interstițială granulomatoasă cazeoasă","imagistica se repetă la 2–3 luni de tratament","abcesul hematogen poate avea urină normală","abcesul asociază de regulă septicemie stafilococică","stricturile sunt maxime în prima săptămână"],"ABCD",1385,"Nefritele tubulointerstițiale — Tuberculoza renală și abcesul",
 "Recunoașterea granulomului cazeos, a momentului apariției stricturilor (2–3 luni) și a particularităților abcesului hematogen cu urină „normală”.",
 ["Histologia poate arăta nefrită interstițială granulomatoasă cazeoasă cu celule gigante, bacilii fiind evidențiați cu Ziehl-Neelsen.","Urografia sau CT-ul se repetă la 2–3 luni de la începutul tratamentului, deoarece stricturile ureterale se dezvoltă în faza de vindecare.","Abcesul hematogen (stafilococic) care nu comunică cu bazinetul lasă urina fără anomalii și se poate extinde perirenal.","Diagnosticul abcesului este ecografic sau prin CT, iar septicemia stafilococică este de regulă prezentă.","Nu: stricturile se dezvoltă în faza de vindecare, motiv pentru care controlul imagistic la 2–3 luni este necesar."]],
 [8,"Capcana este momentul stricturilor (vindecare versus debut) și urina normală într-un abces care nu comunică cu bazinetul."],["2-3 luni","Ziehel-Neelsen"]),

q("nefrologie-adv-048",["Nefrita tubulointerstițială cronică și sarcoidoza renală:",
 ["până la 20% din sarcoidoze au NTI","NTI asociată IgG4 are IgG4 seric crescut","sarcoidoza renală poate fi manifestarea inaugurală","NTI cronice au de regulă proteinurie nefrotică","sarcoidoza renală este corticorezistentă"],"ABC",1386,"Nefritele tubulointerstițiale — NTI cronică, IgG4 și sarcoidoză",
 "Fixarea prevalenței NTI din sarcoidoză (~20%), a profilului IgG4, a proteinuriei ușoare din NTI cronice și a răspunsului rapid la corticoizi.",
 ["Până la 20% dintre pacienții cu sarcoidoză pot prezenta o nefrită tubulointerstițială.","NTI asociată IgG4 se caracterizează prin concentrații serice crescute de IgG4, cu formare de complexe imune.","Sarcoidoza renală granulomatoasă poate fi prima manifestare a bolii, iar corticosteroizii dau un răspuns rapid în majoritatea cazurilor.","Nu: proteinuria din NTI cronice este de regulă ușoară, sub 1 g/zi.","Nu: sarcoidoza renală se tratează cu corticosteroizi, cu răspuns rapid în majoritatea cazurilor, nu cu antituberculoase."]],
 [8,"Distractorul confundă granulomul sarcoid cu TB și neagă răspunsul corticoid explicit din text."],["Până la 20%","lgG4"]),

q("nefrologie-adv-049",["Nefropatia endemică balcanică și nefropatia prin ierburi chinezești:",
 ["ipoteza etiologică principală: acidul aristolohic","afectează câmpia dunăreană, cu fântâni superficiale","progresează spre BCR terminală în 3 luni–10 ani","forma prin ierburi chinezești evoluează mai lent","afectează zonele de deal, cu izvoare profunde"],"ABC",1387,"Nefritele tubulointerstițiale — Nefropatia endemică balcanică și ierburile chinezești",
 "Corelarea geografiei (câmpie/Dunăre/fântâni), a acidului aristolohic și a carcinomului urotelial, cu contrastul evoluției mai agresive a ierburilor chinezești.",
 ["Ipoteza etiopatogenică principală a nefropatiei balcanice, asociată cu carcinoame uroteliale, este intoxicația cu acid aristolohic.","Sunt afectați locuitorii de câmpie de lângă Dunăre, cu apă din fântâni superficiale; boala nu a apărut la cei de la deal.","Debutul este insidios, cu proteinurie ușoară care progresează spre BCR terminală în 3 luni–10 ani, fără tratament curativ.","Nu: nefropatia prin ierburi chinezești are histologie similară, dar evoluție mai agresivă și mai multe carcinoame uroepiteliale.","Nu: sunt afectate zonele de câmpie cu fântâni superficiale, nu dealul, iar asocierea cu carcinoamele uroteliale este caracteristică."]],
 [8,"Inversează geografia câmpie versus deal, detaliul cel mai specific al paginii."],["acid aristolohic","fântâni superfi"]),

q("nefrologie-adv-050",["Nefropatia hiperuricemică acută din sindromul de liză tumorală:",
 ["uratul plasmatic depășește 0,75 mmol/L","alopurinol 100–200 mg ×3/zi, înainte de chimioterapie","febuxostatul înlocuiește alopurinolul netolerat, la RFG >30 ml/min","rasburicaza este un inhibitor de xantin-oxidază","alcalinizarea urinei este contraindicată, acidul uric fiind mai solubil în mediu acid"],"ABC",1387,"Nefritele tubulointerstițiale — Nefropatia hiperuricemică acută",
 "Reținerea pragurilor de urat, a schemei de alopurinol/febuxostat și a mecanismului rasburicazei, cu direcția corectă a pH-ului urinar.",
 ["Urații plasmatici depășesc 0,75 mmol/L și pot trece uneori de 4,5 mmol/L.","Alopurinolul 100–200 mg de 3 ori pe zi, timp de 5 zile, se dă înainte și în timpul radio- și chimioterapiei.","Febuxostatul, inhibitor selectiv nepurinic de xantin-oxidază, este alternativa la intoleranța la alopurinol dacă RFG >30 ml/min.","Nu: rasburicaza este o oxidază de urați recombinantă (ca și pegloticaza) care scade rapid uratul; inhibitorul selectiv de xantin-oxidază citat este febuxostatul.","Nu: alcalinizarea urinei este recomandată, deoarece acidul uric este mai solubil în mediu alcalin."]],
 [8,"Inversează relația de solubilitate a uratului cu pH-ul, o capcană clasică, pe lângă praguri numerice precise."],["0,75 mmol/L","Rasburicaza"]),

q("nefrologie-adv-051",["Epidemiologia bolii cronice de rinichi (BCR):",
 ["diabetul, HTA și ateroscleroza explică peste 70% din cazuri","BCR terminală este de 3–4 ori mai rară la rasa neagră","cistatina C, propusă ca marker în stadiul 3","G2 fără alte semne renale nu înseamnă boală","majoritatea cazurilor sunt în stadiul 5"],"ACD",1393,"Boala cronică de rinichi — Epidemiologie și nuanțe de stadializare",
 "Reținerea celor trei cauze dominante (>70%), a excesului de risc la rasa neagră și a condiției suplimentare pentru G2.",
 ["Peste 70% din cazurile de BCR sunt datorate diabetului zaharat, hipertensiunii arteriale și aterosclerozei.","Nu: incidența bolii renale terminale este de 3–4 ori mai mare la rasa neagră.","Cistatina C a fost propusă ca marker mai fidel al RFG la pacienții în stadiul 3, pentru o stratificare mai bună a riscului.","Pacienții din stadiul G2 nu au boala în absența unei alte manifestări (hematurie, proteinurie, modificări structurale).","Nu: prevalența BCR este de 11–15%, iar majoritatea cazurilor sunt în stadiul 3, nu în stadiul 5."]],
 [8,"Distractorul mută masa cazurilor din stadiul 3 în stadiul 5, contrazicând explicit textul de prevalență."],["Mai mult de 70%","3-4 ori"]),

q("nefrologie-adv-052",["Un hemodializat are PTH de patru ori limita superioară a normalului. Despre controlul fosforului și al PTH:",
 ["tenapanorul inhibă NHE3 și transportorul intestinal Na/Pi2b","calcitriolul se dă la PTH ≥3 × limita superioară","calcimimeticele scad PTH-ul și produsul calciu × fosfor","paricalcitolul produce hipercalcemie mai frecvent decât calcitriolul","tenapanorul este un analog intravenos de vitamină D"],"ABC",1396,"Boala cronică de rinichi — TMO-BCR: chelatori, vitamină D și calcimimetice",
 "Diferențierea mecanismului tenapanorului de analogii de vitamină D și de calcimimetice, cu pragul PTH de 3× ULN și profilul paricalcitolului.",
 ["Tenapanorul, moleculă mică minim absorbită, inhibă schimbătorul Na/H 3 (NHE3) și transportorul intestinal de fosfat Na/Pi2b.","Calcitriolul sau analogii (alfacalcidol, paricalcitol) se folosesc pentru a suprima PTH-ul dacă acesta este de trei ori sau mai mare decât limita superioară.","Calcimimeticele (cinacalcet, etelcalcetid) scad PTH-ul și produsul calciu × fosfor.","Nu: paricalcitolul (19-nor-1,25 dihidroxivitamina D2) are o probabilitate mai mică de hipercalcemie decât calcitriolul.","Nu: tenapanorul nu este un analog de vitamină D; acționează intestinal, pe NHE3 și Na/Pi2b."]],
 [8,"Trei clase cu ținte diferite (NHE3, VDR, CaSR) sunt ușor de amestecat; distractorul mută tenapanorul în clasa vitaminei D."],["Tenapanor","cinacalcet"]),

q("nefrologie-adv-053",["Calcifilaxia și riscul cardiovascular în BCR:",
 ["hiperparatiroidismul, hiperfosfatemia și warfarina favorizează calcifilaxia","warfarina inhibă carboxilarea dependentă de vitamina K","riscul cardiovascular este de 16 ori mai mare","transplantul crește riscul cardiovascular din stadiul 5","acidul folic, B6 și B12 reduc mortalitatea cardiovasculară"],"ABC",1396,"Boala cronică de rinichi — Calcifilaxia și riscul cardiovascular",
 "Recunoașterea factorilor de calcifilaxie (inclusiv warfarina), a magnitudinii riscului CV (×16) și a efectului transplantului, cu eșecul vitaminelor B.",
 ["Factorii de risc pentru calcifilaxie includ hiperparatiroidismul, fosforul seric crescut, obezitatea morbidă și warfarina.","Warfarina acționează prin inhibarea carboxilării (activării) dependente de vitamina K.","Riscul de boală cardiovasculară la pacienții cu BCR este de 16 ori mai mare decât în populația generală.","Nu: transplantul renal scade riscul cardiovascular observat în stadiul 5 al BCR.","Nu: suplimentele de acid folic, vitamina B6 și B12 s-au dovedit ineficiente."]],
 [8,"Factorul ×16 și ineficiența vitaminelor B sunt contraintuitive; distractorul transformă un rezultat negativ într-un beneficiu."],["de 16 mai mare","warfarinei"]),

q("nefrologie-adv-054",["Studiul SHARP și fibroza sistemică nefrogenă (FSN):",
 ["ezetimib-simvastatina ar putea evita ~1/4 din IMA și AVC","combinația ezetimib–simvastatină a îmbunătățit supraviețuirea","gadoliniul este implicat în peste 95% din FSN","FSN este cronică, fără ameliorare la circa 30%","gadoliniul este sigur la RFG <30 ml/min"],"ACD",1397,"Boala cronică de rinichi — SHARP și fibroza sistemică nefrotică",
 "Disocierea reducerii evenimentelor ischemice de absența beneficiului de supraviețuire în SHARP și recunoașterea gadoliniului ca agent al FSN.",
 ["SHARP, pe peste 9500 de pacienți cu BCR, a arătat că ezetimib plus simvastatină ar putea evita circa un sfert din IMA, AVC și revascularizări.","Nu: în SHARP, combinația ezetimib–simvastatină nu a adus beneficiu asupra supraviețuirii.","Agenții de contrast pe bază de gadoliniu au fost implicați în peste 95% din cazurile de FSN.","FSN este cronică și ireversibilă: ~30% fără ameliorare, ~20% cu ameliorare modestă, ~30% cu un oarecare beneficiu doar după transplant.","Nu: se recomandă evitarea gadoliniului la RFG <30 ml/min sau la pacienții dializați."]],
 [8,"Capcana SHARP este disocierea evenimente versus mortalitate; distractorul FSN mută agentul de la gadoliniu la iod."],["peste 9500","peste 95%"]),

q("nefrologie-adv-055",["În stadiile avansate ale BCR, înaintea dializei:",
 ["hiperkaliemia răspunde frecvent la restricția de potasiu","patiromerul și ciclosilicatul de zirconiu-sodiu scad potasemia","bicarbonat de sodiu oral 4,8 g, eficient în acidoză","restricția proteică încetinește declinul RFG în stadiile 4–5","spironolactona și amiloridul sunt preferate în hiperkaliemia uremică"],"ABCD",1398,"Boala cronică de rinichi — Pregătirea pentru substituție: K+, acidoză, proteină",
 "Aplicarea măsurilor conservatoare (restricție K+, patiromer/SZC, bicarbonat 4,8 g, restricție proteică) și evitarea diureticelor care economisesc potasiul.",
 ["Hiperkaliemia răspunde frecvent la restricția de potasiu, iar medicamentele care rețin potasiul trebuie sistate.","Patiromerul și ciclosilicatul de zirconiu și sodiu au fost folosite cu succes în controlul hiperpotasemiei (studii de fază 3).","Bicarbonatul de sodiu oral (4,8 g = 57 mmol de Na+ și HCO3−) este eficient în tratamentul acidozei.","Reducerea aportului proteic încetinește rata de declin a RFG în stadiile 4 și 5.","Nu: spironolactona și amiloridul (ca și substituenții de sare cu potasiu) sunt periculoase în acest context."]],
 [8,"Doza de bicarbonat și pragul proteic 1,8 g sunt ușor de confudat, iar distractorul transformă o contraindicație (economisitoare de K+) în tratament."],["patiromer","4,8 g"]),

q("nefrologie-adv-056",["Organizarea terapiei de substituție renală:",
 ["în Marea Britanie, circa 53.000 de pacienți sunt tratați pentru BRT","fistula arteriovenoasă se creează la o creatinină de 400–500 µmol/L","se evită venipunctura de rutină pe venele destinate fistulei","la nivel mondial, circa trei milioane de persoane primesc HD, DP sau transplant","în Marea Britanie, peste 80% dintre pacienții cu BRT fac dializă peritoneală"],"ABCD",1398,"Boala cronică de rinichi — Organizarea BRT și pregătirea abordului",
 "Reținerea cifrelor BRT (53.000 în Marea Britanie, ponderea DP de 8%, trei milioane global) și a momentului creării FAV (creatinină 400–500).",
 ["În Marea Britanie, circa 53.000 de pacienți sunt tratați pentru BRT: ~50% transplantați, 42% hemodializați și 8% în DP.","Fistula arteriovenoasă se creează din timp, la o creatinină de circa 400–500 µmol/L, pe brațul nedominant.","Venipunctura de rutină pe venele destinate viitoarei fistule trebuie evitată.","La nivel mondial, aproximativ trei milioane de persoane sunt tratate prin HD, DP sau transplant.","Nu: în Marea Britanie, DP acoperă circa 8% dintre pacienți, iar transplantul circa 50%."]],
 [8,"Permută 8% și 80% pentru DP, o capcană de ordin de mărime pe cifrele de registru."],["53.000","42% sunt hemodializaţi"]),

q("nefrologie-adv-057",["Adecvarea hemodializei:",
 ["4–5 ore de două ori pe săptămână sunt considerate adecvate","până la 5–6 ședințe pe săptămână pot oferi un control mai bun","HDF cu peste 20 L convecție/ședință a fost sugerată post-hoc","URR țintă rămâne peste 65% pe ședință","o ședință săptămânală de 2 ore este suficientă la debit >200 ml/min"],"BCD",1400,"Boala cronică de rinichi — Hemodializa: durată, frecvență și HDF",
 "Contrastarea schemei standard 4–5 h de trei ori pe săptămână cu intensificarea (5–6× sau 6–8 h) și pragul HDF de 20 L.",
 ["Nu: schema considerată adecvată este de 4–5 ore de trei ori pe săptămână.","Ședințele mai frecvente (până la 5–6 pe săptămână) sau mai lungi (6–8 ore de trei ori pe săptămână) pot oferi un control mai bun.","Analizele post-hoc au sugerat HDF cu un volum de convecție de peste 20 L pe ședință.","Ținta URR rămâne peste 65% pe ședință.","Nu: adecvarea cere 4–5 ore de trei ori pe săptămână, nu o ședință săptămânală de 2 ore."]],
 [8,"Pragurile de durată/frecvență și volumul HDF de 20 L sunt ușor de subestimat spre o schemă „minimă”."],["4 şi 5 ore","peste 20 litri"]),

q("nefrologie-adv-058",["Dializa peritoneală continuă ambulatorie (CAPD):",
 ["soluțiile mai hipertone de glucoză elimină mai puțin lichid","presupune 3–5 schimburi zilnice de 1,5–3 L","peritonita apare cu o frecvență de circa un episod la 2 ani","în circa 20% dintre peritonite nu se identifică germenul","are ca țintă un Kt/V săptămânal de 0,5"],"BCD",1401,"Boala cronică de rinichi — Dializa peritoneală: tehnică și peritonită",
 "Reținerea efectului osmolalității glucozei/icodextrinei, a ritmului schimburilor și a epidemiologiei peritonitei (1/2 ani, 20% culturi negative).",
 ["Nu: ultrafiltrarea depinde de glucoză sau icodextrină, iar soluțiile mai hipertone (1,5–4% glucoză) elimină mai mult lichid.","Se fac 3–5 schimburi pe zi, cu 1,5–3 L, fiecare durând 20–40 de minute.","Rata peritonitei este de circa un episod la 2 ani; peste 100 leucocite/mm³ în lichid sunt sugestive.","Germenii includ stafilococi, E. coli, Pseudomonas și Candida; în circa 20% nu se identifică germenul.","Nu: clinicienii țintesc un Kt/V săptămânal de 2,0 și un clearance al creatininei de 60 L/săptămână."]],
 [8,"Kt/V 2,0 versus 0,5 și pragul >100 leucocite sunt capcane numerice pe un protocol de DP altfel familiar."],["1,5-3 L","2 ani de tratament"]),

q("nefrologie-adv-059",["Peritonita sclerozantă și adecvarea dializei peritoneale:",
 ["peritonita sclerozantă poate fi fatală după CAPD îndelungată","ținta include un clearance al creatininei de 60 L/săptămână","Kt/V săptămânal țintă este de 0,5","hemodializa oferă cea mai bună supraviețuire dintre tratamentele BRT","peritonita sclerozantă se remite în câteva zile prin mai multe schimburi"],"AB",1402,"Boala cronică de rinichi — Complicațiile tardive ale CAPD și țintele Kt/V",
 "Recunoașterea gravității peritonitei sclerozante, a țintelor de adecvare (Kt/V 2,0, clearance 60 L/săptămână) și a superiorității transplantului.",
 ["Peritonita sclerozantă este o complicație potențial fatală a CAPD de lungă durată.","Majoritatea clinicienilor țintesc un Kt/V săptămânal de 2,0 asociat unui clearance al creatininei de 60 L pe săptămână.","Nu: ținta citată este un Kt/V săptămânal de 2,0, asociat unui clearance al creatininei de 60 L/săptămână.","Nu: transplantul, când este disponibil, rămâne modalitatea de BRT cu cea mai bună supraviețuire.","Nu: peritonita sclerozantă este o complicație gravă, potențial fatală, nu benignă și reversibilă în câteva zile."]],
 [8,"Kt/V 2,0 și caracterul potențial fatal sunt ușor de minimizat; un distractor banalizează sclerozarea peritoneală."],["Peritonita sclerozantă","KtN săptămânal de 2,0"]),

q("nefrologie-adv-060",["Rezultatele transplantului renal:",
 ["circa 80% dintre grefe supraviețuiesc 5–10 ani","timpul de înjumătățire al alogrefelor este de 13–16 ani","transplantul preemptiv, înaintea dializei, nu aduce beneficii","rejetul precoce apare la sub 20% dintre primitorii de la donator viu","incompatibilitatea ABO contraindică transplantul de la donator viu"],"ABD",1402,"Boala cronică de rinichi — Transplantul renal: supraviețuirea grefei",
 "Reținerea supraviețuirii 80%/5–10 ani, a half-life 13–16 ani, a avantajului preemptiv și a ratei de rejet <20% la donator viu.",
 ["În centrele cu experiență, circa 80% dintre grefe supraviețuiesc 5–10 ani, iar 50% supraviețuiesc 10–30 de ani.","Timpul de înjumătățire al alogrefelor renale este încă de 13–16 ani.","Nu: transplantul preemptiv, efectuat înaintea dializei, oferă beneficii.","Rejetul din primele luni apare la mai puțin de 20% dintre primitorii de la donator viu, majoritatea episoadelor fiind reversibile.","Nu: transplantul rinichilor ABO-incompatibili, mai ales de la donator viu, este de rutină, cu rezultate comparabile."]],
 [8,"Half-life 13–16 ani este contraintuitiv față de supraviețuirea 80% la 5–10 ani, iar distractorul neagă transplantul ABO-incompatibil descris ca rutină."],["13-16 ani","transplant preemptiv"]),

q("nefrologie-adv-061",["Imunosupresia și complicațiile precoce după transplant renal:",
 ["se folosește de regulă o combinație de imunosupresoare","rejetul acut apare la 10–30%, mai ales în primele 3 luni","rejetul umoral se tratează cu IgIV, plasmafereză și anti-CD20","infecțiile bacteriene urinare și de plagă apar tipic după 6 luni","depunerea de C4d marchează rejetul celular"],"ABC",1404,"Boala cronică de rinichi — Rejetul acut și infecțiile precoce",
 "Distingerea rejetului celular de cel humoral (C4d, DSA, plasmafereză/anti-CD20) și a ferestrei <1 lună pentru infecțiile bacteriene.",
 ["Cadranul 36.40 descrie combinațiile de imunosupresoare folosite de regulă.","Rejetul acut apare la 10–30% dintre transplantați, de obicei în primele 3 luni, iar biopsia confirmă diagnosticul.","Rejetul mediat de anticorpi (DSA circulanți, C4d) se tratează empiric cu Ig intravenos, plasmafereză și anti-CD20.","Nu: infecțiile bacteriene (tract urinar, plăgi, torace) apar precoce, în prima lună după transplant.","Nu: C4d peritubular/glomerular marchează rejetul mediat de anticorpi (umoral), nu pe cel celular."]],
 [8,"Inversează markerul C4d (humoral versus celular) și fereastra temporală a infecțiilor bacteriene."],["C4d","10-30%"]),

q("nefrologie-adv-062",["Bărbat de 42 de ani cu HIV, CD4 280/mm³, ARN HIV nedetectabil, ARV stabil de 5 luni; candidat la transplant renal:",
 ["transplantul e sigur la CD4 ≥200, ARN nedetectabil și ARV stabil 16 săptămâni","supraviețuirea a fost de 95% la 1 an și 88% la 3 ani","infecțiile cauzează 50% dintre decesele post-transplant","limfoproliferările post-transplant se asociază frecvent cu EBV","infecția HIV rămâne o contraindicație absolută a transplantului"],"ABD",1404,"Boala cronică de rinichi — Transplantul la pacienții cu HIV și complicații tardive",
 "Aplicarea criteriilor de eligibilitate HIV (CD4 ≥200, viremie nedetectabilă, ARV 16 săptămâni) și a ponderii CV (50% din decese).",
 ["Un studiu pe 150 de pacienți HIV-pozitivi a arătat siguranța la CD4 ≥200/mm³, ARN HIV-1 nedetectabil și ARV stabil 16 săptămâni.","Supraviețuirea a fost de 95% la 1 an și 88% la 3 ani, mai mică decât în populația generală transplantată.","Nu: bolile cardiovasculare cauzează 50% dintre decesele de după transplant.","Tulburările limfoproliferative post-transplant sunt frecvent asociate infecției cu EBV.","Nu: HIV a fost o contraindicație, dar transplantul este sigur și eficient la pacienții selectați."]],
 [8,"Vigneta testează depășirea contraindicației istorice HIV prin praguri numerice exacte (CD4, 16 săptămâni, 95%/88%)."],["200 celule/mm3","16 săptămâni"]),

q("nefrologie-adv-063",["Chisturile renale simple și boala chistică dobândită:",
 ["chisturile simple apar la circa 5% dintre persoanele peste 50 de ani","persoanele cu chisturi simple sunt adesea asimptomatice","chisturile dobândite sunt frecvente la dializați și transplantați","intră în diagnosticul diferențial al BPRAD","chisturile simple după 50 de ani echivalează cu BPRAD"],"BCD",1405,"Bolile renale chistice — Chisturi simple și boala chistică dobândită",
 "Separarea chisturilor simple (50% peste 50 de ani, asimptomatice) și a bolii chistice dobândite de dializă de BPRAD.",
 ["Nu: chisturile simple sunt frecvente la vârstnici, 50% dintre persoanele peste 50 de ani putându-le avea.","Persoanele cu chisturi simple sunt adesea asimptomatice.","Chisturile dobândite sunt frecvente în BCR terminală tratată prin dializă sau transplant.","Cadranul 36.42 include aceste entități în diagnosticul diferențial al BPRAD.","Nu: chisturile simple nu echivalează cu BPRAD și nu impun screeningul anevrismelor."]],
 [8,"Capcana este echivalarea chisturilor simple ale vârstnicului cu BPRAD, o confuzie de prevalență (50% versus 1:400–1:1000)."],["peste 50 de","asimptomatice"]),

q("nefrologie-adv-064",["Boala polichistică renală autozomal dominantă (BPRAD):",
 ["asociază chisturi hepatice, ocazional cu efect de masă","asociază prolaps de valvă mitrală la circa 20% dintre pacienți","sub un RFG de 50 ml/min, declinul mediu este de 5 ml/min pe an","agoniștii receptorilor V2 ai vasopresinei reduc creșterea chisturilor","calculii de acid uric sunt excepționali"],"ABC",1405,"Bolile renale chistice — BPRAD: extra-renal, declinul RFG și vaptanii",
 "Completarea tabloului extra-renal (ficat, PVM) și a dinamicii RFG (5 ml/min/an sub 50) cu mecanismul vaptanilor (inhibitori V2).",
 ["Chisturile hepatice sunt frecvente în BPRAD (50% într-un pasaj, ~30% în altul) și pot da ocazional efect de masă.","Prolapsul de valvă mitrală apare la 20% dintre persoanele cu BPRAD.","După scăderea RFG sub 50 ml/min, rata medie de declin este de 5 ml/min pe an.","Nu: inhibitorii receptorilor V2 ai vasopresinei (vaptanii) sunt abordarea care reduce AMPc și creșterea chisturilor.","Nu: calculii din BPRAD sunt mai frecvent din acid uric, radiotransparenți, nu din oxalat de calciu."]],
 [8,"Declinul de 5 ml/min/an și PVM 20% completează itemul genetic deja existent; distractorul reia capcana compoziției calculilor."],["5 ml/min pe an","Prolapsul de valvă mitrală"]),

q("nefrologie-adv-065",["Pielografia anterogradă:",
 ["presupune puncția percutanată a sistemului pielocaliceal","permite plasarea de tuburi de dren și stenturi","este prima intenție în refluxul vezico-ureteral la copil","se realizează prin cateterizarea vezicii și instilarea contrastului","se complică cu anevrism arteriovenos în circa 20% din cazuri"],"AB",1351,"Investigații — Pielografia anterogradă",
 "Recunoașterea căii percutanate a pielografiei anterograde și a posibilității de dren/stent, distincte de cistouretrografie.",
 ["Constă în puncția percutanată a sistemului pielocaliceal și injectarea de contrast până la nivelul obstrucției.","În timpul procedurii pot fi amplasate tuburi de dren și stenturi.","Nu: refluxul vezico-ureteral la copil se studiază prin cistouretrografie.","Nu: cateterizarea vezicii cu instilarea contrastului definește cistouretrografia.","Nu: anevrismul arteriovenos de ~20% figurează la complicațiile biopsiei renale, nu ale pielografiei."]],
 [8,"Distractorii mută indicația pediatrică a cistouretrografiei și complicația biopsiei pe o investigație de puncție pielocaliceală."],["Pielografia anterogradă","tuburi de dren"]),

q("nefrologie-adv-066",["Arteriografia renală (inclusiv DSA):",
 ["se folosește diagnostic și terapeutic în stenoza de arteră renală","permite angioplastia cu balon și stentarea","se complică cu embolii de colesterol sau nefropatie de contrast","înlocuiește MAG3 în evaluarea obstrucției pielocaliceale","este rezervată evaluării refluxului vezico-ureteral"],"ABC",1351,"Investigații — Angiografia renală",
 "Recunoașterea dublului rol diagnostic-terapeutic al DSA și a celor două complicații citate (colesterol, contrast).",
 ["Arteriografia este folosită diagnostic și terapeutic în suspiciunea de stenoză de arteră renală.","Permite angioplastia cu balon și stentarea ulterioară.","Complicațiile citate sunt embolia cu cristale de colesterol și leziunile renale induse de contrast.","Nu: obstrucția pielocaliceală se evaluează cu MAG3, nu prin arteriografie.","Nu: arteriografia este indicată tocmai în stenoza de arteră renală, nu în evaluarea refluxului."]],
 [8,"Capcana este confuzia cu MAG3/cistouretrografie; complicațiile reale (colesterol, contrast) trebuie ținute împreună."],["embolia cu cristale de colesterol","angioplastia cu balon"]),

q("nefrologie-adv-067",["În timpul biopsiei renale transcutanate (Cadranul 36.6):",
 ["pacientul stă în decubit ventral, cu o pernă tare sub abdomen","biopsia se efectuează sub anestezie generală, după reperaj ecografic","pacientul ține respirația în momentul biopsiei","pacientul este mobilizat imediat, fără anestezie","pacientul stă în decubit dorsal, ca la biopsia hepatică"],"AC",1352,"Glomerulul și afectarea glomerulară — Biopsia: timpul procedurii",
 "Aplicarea pașilor intra-procedurali din Cadranul 36.6 (decubit ventral, ecograf și anestezic local, apnee).",
 ["Cadranul 36.6 cere decubit ventral, cu o pernă tare sub abdomen.","Nu: rinichiul este localizat ecografic, iar pe calea de biopsie se injectează anestezic local.","Pacientul este instruit să țină respirația în momentul efectuării biopsiei.","Nu: pe calea de biopsie se injectează anestezic local, iar mobilizarea imediată contrazice cadranul.","Nu: poziția pentru biopsia renală este decubitul ventral, nu cel dorsal."]],
 [8,"Inversează poziția (ventral versus dorsal) și cerința de apnee, două detalii consecutive din același cadran."],["decubit ventral","țină respiraţia"]),

q("nefrologie-adv-068",["Afecțiunile glomerulare, cauză de boală renală terminală:",
 ["în Europa și SUA sunt a treia cauză, după diabet și HTA","reprezintă circa 10–15% dintre cazuri","sunt prima cauză în Occident, înaintea diabetului","afectează de regulă un singur rinichi","evoluează fără leziuni interstițiale"],"AB",1352,"Glomerulul și afectarea glomerulară — Epidemiologie și trăsături generale",
 "Reținerea rangului 3 și a cotei 10–15% dintre cazurile de BRT, cu implicare simetrică.",
 ["În Europa și SUA, afecțiunile glomerulare sunt a treia cauză, după diabet și hipertensiune.","Ele acoperă aproximativ 10–15% dintre cazurile de boală renală terminală.","Nu: diabetul și hipertensiunea preced afecțiunile glomerulare ca și cauză.","Nu: rinichii sunt implicați simetric.","Nu: afectarea interstițială apare în mod obișnuit."]],
 [8,"Cota 10–15% este ușor de mutat pe locul 1 etiologic; distractorii neagă simetria și interstițiul din același paragraf."],["10-15% din aceste cazuri","a treia cea mai frecventă"]),

q("nefrologie-adv-069",["Investigarea bolilor glomerulare (Cadranul 36.9) poate arăta:",
 ["cilindri eritrocitari la microscopia urinară","titru ASO crescut în nefrita poststreptococică","ANCA în vasculite și anti-MBG în boala Goodpasture","crioglobuline crescute în crioglobulinemie","imagistică renală patognomonică pentru NLM"],"ABCD",1353,"Glomerulul și afectarea glomerulară — Cadranul 36.9",
 "Recunoașterea panelului serologic și urinar din Cadranul 36.9, fără a inventa un semn imagistic pentru NLM.",
 ["Cadranul 36.9 listează eritrocitele și cilindrii eritrocitari la microscopia urinară.","Titrul de antistreptolizină-O crescut figurează la nefrita poststreptococică.","ANCA pozitivi apar în unele vasculite, iar anticorpii anti-MBG în sindromul Goodpasture.","Crioglobulinele crescute sunt menționate în crioglobulinemie.","Nu: imagistica renală este de obicei normală, fără semn patognomonic pentru NLM."]],
 [8,"Cadranul grupează markeri reali ușor de permutat; distractorul inventează un semn imagistic inexistent."],["Titru antistreptolizina-O","Anticorpi anti membrană bazală"]),

q("nefrologie-adv-070",["În sindromul nefrotic:",
 ["ficatul nu poate sintetiza albumină","hipoalbuminemia se datorează scăderii PCSK9","crește catabolismul tubular proximal al albuminei","pragul definitoriu al proteinuriei este de 1 g/zi","HDL crește, iar raportul LDL:HDL scade"],"C",1353,"Glomerulul și afectarea glomerulară — Hipoalbuminemia: catabolism tubular",
 "Recunoașterea explicației parțiale a hipoalbuminemiei prin catabolismul albuminei reabsorbite în tubul proximal.",
 ["Nu: ficatul sănătos sintetizează 10–12 g de albumină pe zi; hipoalbuminemia nu se explică prin incapacitatea de sinteză.","Nu: PCSK9 este invocată în hiperlipidemie (internalizarea receptorilor LDL), nu ca mecanism al hipoalbuminemiei.","O explicație parțială a hipoalbuminemiei este catabolismul crescut al proteinelor reabsorbite, în mare parte albumină, în tubii proximali.","Nu: pragul de proteinurie citat pentru sindromul nefrotic este de 3,5 g/zi.","Nu: HDL este neschimbat sau scăzut, iar raportul LDL:HDL crește."]],
 [8,"Capcana mută PCSK9 (lipidică) pe hipoalbuminemie și ignoră catabolismul tubular, detaliul nefolosit din același paragraf."],["tubii proximali","catabolismului proteinelor"]),

q("nefrologie-adv-071",["Edemele și hipercoagulabilitatea din sindromul nefrotic:",
 ["edemul intestinal poate impune inițial diuretic intravenos","se tolerează edem moderat pentru a evita hipotensiunea posturală","hipercoagulabilitatea se însoțește de fibrinogen plasmatic scăzut","restricția hidrică strictă înlocuiește diureticul de ansă","amiloridul nu se folosește în edemul nefrotic rezistent"],"AB",1354,"Glomerulul și afectarea glomerulară — Edeme, absorbție și hipercoagulabilitate",
 "Corelarea edemului mucoasei (diuretic i.v.), a toleranței unui edem moderat și a axei antitrombină–fibrinogen.",
 ["Edemul mucoasei intestinale scade absorbția diureticelor, fiind necesară inițial calea intravenoasă.","Un grad moderat de edeme poate fi acceptat pentru a evita hipotensiunea posturală.","Nu: hipercoagulabilitatea se datorează pierderii urinare de antitrombină și creșterii producției hepatice de fibrinogen.","Nu: diureticul de ansă rămâne baza tratamentului; restricția hidrică nu îl înlocuiește.","Nu: amiloridul 5 mg/zi se adaugă la pacienții neresponsivi la diureticul de ansă, cu monitorizarea potasiului."]],
 [8,"Detaliul mucoasei intestinale este ușor de ignorat în favoarea unei restricții hidrice „intuitive”."],["edemului mucoasei intestinale","antitrombină"]),

q("nefrologie-adv-072",["Patogeneza nefropatiei cu leziuni minime (NLM) implică:",
 ["celule stem CD34 imature, mai degrabă decât limfocite T mature","IL-13, VEGF și expresia podocitară crescută a ANGPTL4","medicamente precum AINS, litiul sau rifampicina","depozite liniare de IgG anti-MBG, ca în boala Goodpasture","rar, infecții precum VHC, HIV sau tuberculoza"],"ABCE",1354,"Glomerulul și afectarea glomerulară — NLM: patogeneză și triggeri",
 "Reținerea axei CD34/IL-13/ANGPTL4 și a listei de medicamente, fără a atribui NLM un pattern anti-MBG.",
 ["Textul atribuie NLM celulelor stem CD34 imature diferențiate, nu limfocitelor T mature.","IL-13, VEGF și expresia podocitară crescută a ANGPTL4 afectează funcția podocitelor.","AINS, litiul, cefalosporinele, rifampicina, ampicilina, bisfosfonații și sulfasalazina sunt citate.","Nu: imunofluorescența în NLM nu evidențiază complexe imune sau anticorpi anti-MBG.","VHC, HIV și tuberculoza sunt cauze infecțioase mai rare."]],
 [8,"Distractorul împrumută patternul liniar al bolii anti-MBG pe o glomerulopatie fără depozite imune."],["celulele stern CD34","ANGPTL4"]),

q("nefrologie-adv-073",["Sindromul nefrotic congenital finlandez și formele genetice de SNRS:",
 ["tipul finlandez este autozomal dominant, prin mutații ale nefrinei","poate fi diagnosticat intrauterin prin AFP amniotică crescută","progresează persistent spre boala renală terminală","răspunde prompt la prednisolon, remisiunea fiind regula","analiza mutațiilor poate fi oferită la debut înainte de 25 de ani"],"BCE",1355,"Glomerulul și afectarea glomerulară — Nefrotic congenital: AFP și genetica SNRS",
 "Reținerea transmiterii AR (nefrina), a AFP amniotice, a progresiei spre BRT și a pragului de 25 de ani pentru analiza mutațiilor.",
 ["Nu: sindromul de tip finlandez este autozomal recesiv, prin mutații ale nefrinei, proteină a fantei de filtrare.","Alfa-fetoproteina crescută în lichidul amniotic permite diagnosticul intrauterin.","Forma finlandeză progresează persistent spre boala renală terminală.","Nu: formele genetice sunt considerate rezistente la corticosteroizi.","Textul propune analiza mutațiilor în SNRS la persoanele cu debut înainte de 25 de ani."]],
 [8,"Capcana clasică rămâne „răspunsul la steroizi”; se adaugă AFP amniotică și pragul de 25 de ani, nefolosite anterior."],["lichidul amniotic","înainte de vârsta de 25 de ani"]),

q("nefrologie-adv-074",["Variantele histologice ale GSFS:",
 ["varianta „tip lesion” are scleroză la polul vascular","varianta colabantă, cu podocite vacuolate, este frecventă în HIVAN","varianta celulară ocluzează segmentar lumenul capilar","primii afectați sunt glomerulii din cortexul superficial","varianta „tip lesion” marchează GSFS secundară obezității"],"BC",1355,"Glomerulul și afectarea glomerulară — GSFS: variante histologice",
 "Diferențierea variantelor tip/colabantă/celulară și a riscului de diagnostic greșit de NLM prin ratarea glomerulilor corticomedulari.",
 ["Nu: varianta „tip lesion” are scleroza la polul tubular, cu evoluție benignă și răspuns favorabil la steroizi.","Varianta colabantă, cu podocite tumefiate și vacuolate, este descrisă în HIVAN.","În varianta celulară, hipercelularitatea segmentară ocluzează lumenul capilar în cel puțin un glomerul.","Nu: glomerulii de la joncțiunea corticomedulară sunt primii afectați și pot fi ratați la biopsia transcutanată.","Nu: „tip lesion” definește forma cu evoluție benignă și răspuns la steroizi, nu GSFS secundară obezității."]],
 [8,"Cele cinci variante sunt ușor de permutat; distractorul mută „tip lesion” pe forma secundară."],["tip lesion","joncţiunii corticomedulare"]),

q("nefrologie-adv-075",["GSFS primară – factorul de permeabilitate și recidiva în grefă:",
 ["citokina 1 cardiotrophin-like este candidat la factorul circulant","suPAR este considerat improbabil drept factor cauzal","abataceptul a fost folosit în hiperexpresia podocitară a CD80","gelul cu ACTH a fost util în recidivele refractare post-transplant","suPAR este factorul circulant cauzal demonstrat cert"],"ABCD",1356,"Glomerulul și afectarea glomerulară — GSFS primară: factorul de permeabilitate",
 "Disocierea candidatului cardiotrophin-like de suPAR și recunoașterea abataceptului/ACTH în recidiva de grefă.",
 ["Un factor circulant de permeabilitate provoacă proteinuria; identitatea lui este necunoscută, citokina 1 cardiotrophin-like fiind un candidat.","Dovezile recente fac puțin probabil ca suPAR să fie factorul cauzal.","Abataceptul (anti-CD80) a fost folosit cu un anumit succes la hiperexpresia podocitară a CD80.","Gelul cu ACTH a fost utilizat cu succes în cazurile refractare post-transplant.","Nu: dovezile recente fac puțin probabil ca suPAR să fie factorul cauzal."]],
 [8,"suPAR, o capcană „la modă”, este explicit respins în text; distractorul îl reinstaurează."],["cardiotrophin-like","Abatacept"]),

q("nefrologie-adv-076",["Bărbat tânăr de culoare, HIV-pozitiv, cu HIVAN confirmat bioptic. Sunt adevărate:",
 ["podocitele infectate supraexprimă factorul Wilms și sinaptopodina","ARV inițiată precoce poate face leziunile reversibile","asociază proteinurie nefrotică, edeme și BCR posibil rapid progresivă","leziunea este identică NLM, fără colaps capilar","leziunile rămân ireversibile chiar sub ARV precoce"],"BC",1356,"Glomerulul și afectarea glomerulară — HIVAN: reversibilitatea sub ARV",
 "Corelarea histologiei colabante cu reversibilitatea sub terapie antiretrovirală precoce.",
 ["Nu: infecția directă a podocitelor cu HIV-1 se asociază cu pierderea factorului tumoral Wilms și a sinaptopodinei.","Terapia antiretrovirală poate determina reversibilitatea leziunilor dacă este inițiată precoce.","Tabloul asociază proteinurie nefrotică, edeme și BCR, care poate avea progresie rapidă.","Nu: HIVAN corespunde variantei colabante de GSFS, nu nefropatiei cu leziuni minime.","Nu: recuperarea este posibilă dacă terapia antiretrovirală este inițiată precoce."]],
 [8,"Vigneta cere legătura colaps–ARV; distractorii o confundă cu NLM sau neagă reversibilitatea."],["factorul tumoral Wilms","Terapia antiretrovirală"]),

q("nefrologie-adv-077",["Glomerulopatia membranoasă secundară se asociază cu:",
 ["penicilamina, sărurile de aur, AINS sau captoprilul","LES, tiroidită, VHB, VHC sau schistosomiază","cancere de plămân, colon, stomac, sân sau limfom","alte cauze, precum sarcoidoza și siclemia","prezența anticorpilor anti-PLA2R circulanți"],"ABCD",1357,"Glomerulul și afectarea glomerulară — GN membranoasă secundară: cauze",
 "Recunoașterea spectrului medicamentos, infecțios, neoplazic și de sistem, cu absența anti-PLA2R.",
 ["Medicamentele citate sunt penicilamina, aurul, AINS, probenecidul, mercurul și captoprilul.","Bolile autoimune (LES, tiroidită) și infecțiile (VHB, VHC, schistosomiază, Plasmodium malariae) figurează în listă.","Cancerele enumerate sunt de plămân, colon, stomac, sân și limfomul.","Sarcoidoza și siclemia sunt citate la „alte cauze”.","Nu: forma secundară se definește tocmai prin absența anticorpilor anti-PLA2R/THSD7A."]],
 [8,"Distractorul inversează markerul serologic care deosebește forma autoimună de cea secundară."],["penicilamină","THSD7A"]),

q("nefrologie-adv-078",["Anticorpii anti-THSD7A din glomerulopatia membranoasă:",
 ["apar la circa 75% dintre pacienți, fiind antigenul major","apar la circa 10% dintre pacienții PLA2R-negativi","apar la peste 90% dintre formele secundare medicamentoase","definesc sindromul nefrotic congenital de tip finlandez","definesc suprapunerea cu boala anti-MBG"],"B",1357,"Glomerulul și afectarea glomerulară — THSD7A versus PLA2R",
 "Reținerea cotelor 3% (PLA2R-pozitivi) și 10% (PLA2R-negativi) și a asocierii cu neoplazie.",
 ["Nu: cota de circa 75% aparține anticorpilor anti-PLA2R (IgG4), antigenul major.","Anti-THSD7A apar la circa 3% dintre pacienții cu glomerulopatie membranoasă și la 10% dintre cei PLA2R-negativi, uneori în asociere cu o neoplazie.","Nu: forma secundară este seronegativă pentru acești anticorpi.","Nu: forma finlandeză este definită de mutațiile nefrinei, nu de anti-THSD7A.","Nu: anticorpii anti-MBG aparțin unei alte boli, boala anti-MBG."]],
 [8,"Permutează 75%, 3% și 10% între PLA2R și THSD7A, capcana numerică a aceluiași paragraf."],["3% din cazurile PLA2R-pozitive","10% dintre pacienţii PLA2R-negativi"]),

q("nefrologie-adv-079",["Amiloidoza AL – tablou clinic:",
 ["apare rareori înainte de 40 de ani","se manifestă prin macroglosie în circa 10% din cazuri","poate debuta cu sindrom de tunel carpian","se asociază tipic cu artrita reumatoidă","macroglosia caracterizează amiloidoza AA, nu AL"],"ABC",1358,"Glomerulul și afectarea glomerulară — Amiloidoza AL: clinic",
 "Fixarea vârstei (>40 de ani), a cotelor 10%/15% (macroglosie/purpură) și a asocierilor limfoproliferative ale AL.",
 ["Amiloidoza AL apare rareori înainte de vârsta de 40 de ani.","Macroglosia apare în aproximativ 10% din cazuri, iar purpura periorbitală în 15%.","Sindromul de tunel carpian poate fi o manifestare precoce.","Nu: amiloidoza AL se asociază cu mielom, macroglobulinemie Waldenström sau limfom non-Hodgkin.","Nu: macroglosia nu este o caracteristică a amiloidozei AA; cotele de 10% și 15% aparțin AL."]],
 [8,"Cotele 10% și 15% sunt ușor de mutat pe forma AA, care tocmai nu are macroglosie."],["aproximativ 10% din cazuri","purpura periorbitală în 15%"]),

q("nefrologie-adv-080",["Diagnosticul amiloidozei cu afectare renală:",
 ["la imagistică, rinichii apar adesea micșorați","scintigrafia SAP radiomarcat cuantifică depozitele in vivo","se poate biopsia rectul, gingia sau grăsimea abdominală","imunohistochimia identifică AA în ~40% și AL în aproape 100%","scintigrafia MAG3 poate înlocui biopsia renală"],"BC",1358,"Glomerulul și afectarea glomerulară — Amiloidoza: SAP și biopsii extra-renale",
 "Completarea diagnosticului cu SAP, rinichi mari și siturile extra-renale, păstrând cota 40% (AL) versus 100% (AA).",
 ["Nu: în amiloidoză rinichii sunt adesea măriți la imagistică.","Scintigrafia cu amiloid seric P (SAP) radiomarcat cuantifică depozitele in vivo.","Dacă histologia renală nu poate fi obținută, se biopsiază rectul, gingiile, grăsimea abdominală sau miocardul.","Nu: imunohistochimia identifică AL în doar ~40% din cazuri, față de aproape 100% în AA.","Nu: MAG3 evaluează obstrucția și perfuzia renală, nu depozitele de amiloid."]],
 [8,"SAP este o tehnică puțin uzuală, ușor de confudat cu MAG3 din investigațiile de la începutul capitolului."],["amiloid seric P","grăsime abdominală"]),

q("nefrologie-adv-081",["Clasificarea nefropatiei diabetice (Cadranul 36.11):",
 ["clasa I: MBG peste 395 nm la femei, peste 430 nm la bărbați","clasa IIb: peste 25% din mezangiu depășește aria lumenului capilar","clasa III: peste 50% din glomeruli cu scleroză globală","clasa I: noduli Kimmelstiel-Wilson în peste 50% din glomeruli","podocituria precoce reflectă apoptoza sau detașarea podocitelor"],"ABE",1359,"Glomerulul și afectarea glomerulară — Nefropatia diabetică: praguri de clasă",
 "Aplicarea pragurilor în nanometri (clasa I) și a definițiilor IIb/IV, plus podocituria precoce.",
 ["Clasa I este îngroșarea izolată a MBG (>395 nm la femei, >430 nm la bărbați), fără expansiune mezangială.","Clasa IIb cere expansiune mezangială severă, cu >25% din mezangiu mai mare decât aria medie a lumenului capilar.","Nu: glomeruloscleroza diabetică avansată cu >50% glomeruloscleroză globală definește clasa IV; clasa III are noduli Kimmelstiel-Wilson.","Nu: nodulii Kimmelstiel-Wilson definesc clasa III, nu clasa I.","Epuizarea podocitelor prin apoptoză sau detașare duce la podociturie la începutul bolii."]],
 [8,"Pragurile 395/430 nm și mutarea nodulilor KW pe clasa I sunt capcane de cadran."],[">395 nm la femei","Podociturie"]),

q("nefrologie-adv-082",["Factori de progresie și terapii adjuvante în nefropatia diabetică:",
 ["fumatul triplează rata de progresie a BCR","pentoxifilina încetinește declinul RFG prin reducerea TNF-α","atrasentanul (antagonist ETAR) reduce albuminuria reziduală","dulaglutida este un inhibitor al cotransportorului SGLT2","fumatul are efect protector, încetinind progresia"],"ABC",1359,"Glomerulul și afectarea glomerulară — Renoprotecție: fumat, pentoxifilină, ETAR",
 "Reținerea factorului ×3 al fumatului și a statutului încă nevalidat al pentoxifilinei și atrasentanului.",
 ["Cadranul 36.12 citează o rată de progresie a BCR de trei ori mai mare la fumători.","Pentoxifilina încetinește scăderea RFG și proteinuria prin reducerea TNF-α, observație care necesită validare.","Atrasentanul, antagonist selectiv ETAR, asociat blocadei SRA reduce albuminuria reziduală, cu nevoie de confirmare pe termen lung.","Nu: dulaglutida este un agonist GLP-1, citat alături de liraglutidă și semaglutidă.","Nu: fumatul se asociază cu o rată de progresie de trei ori mai mare."]],
 [8,"Inversează direcția fumatului (×3 progresie) și tratează două observații preliminare ca și cum ar fi infirmate."],["trei ori mai mare","Atrasentan"]),

q("nefrologie-adv-083",["Proteinuria izolată, fără hematurie, la un pacient asimptomatic:",
 ["este de obicei sub 1 g/zi, cu funcție renală normală","este posturală, benignă, la peste 50% dintre pacienți","este patognomonică pentru amiloidoză și impune biopsie imediată","exclude o leziune glomerulară gravă subiacentă","la peste 3,5 g/zi se încadrează ca sindrom nefritic"],"AB",1360,"Glomerulul și afectarea glomerulară — Proteinurie izolată posturală",
 "Recunoașterea cotei >50% de proteinurie posturală benignă la proteinuria sub 1 g/zi.",
 ["Proteinuria izolată este de obicei sub 1 g/zi, cu funcție renală normală.","Peste 50% dintre acești pacienți au proteinurie posturală, benignă.","Nu: poate fi semnul precoce al mai multor leziuni (membranoasă, IgA, GSFS, diabetică, amiloid), nu este patognomonică.","Nu: poate fi semnul precoce al unei leziuni grave, deși formele febrile sunt ușoare sau tranzitorii.","Nu: proteinuria de 3,5 g/zi definește sindromul nefrotic, nu nefritic."]],
 [8,"Cota 50% posturală este ușor de transformat într-o „patognomonie” de amiloid sau într-un sindrom nefritic."],["Peste 50%","proteinurie post�rală"]),

q("nefrologie-adv-084",["Semiluna și glomerulonefrita rapid progresivă (GNRP):",
 ["semiluna se formează din macrofage și celule epiteliale în mezangiu","GNRP produce insuficiență renală acută în săptămâni sau luni","nefrita acută nu are necroză și semilune, pe un continuum cu GNRP","imunofluorescența distinge patternuri liniar, granular și pauci-imun","semiluna este un depozit liniar de IgG"],"BCD",1360,"Glomerulul și afectarea glomerulară — GNRP: semiluna și continuumul",
 "Definirea histologică a semilunei și plasarea nefritei acute versus GNRP pe același spectru, după Cadranul 36.13.",
 ["Nu: semiluna este un agregat de macrofage și celule epiteliale în spațiul lui Bowman.","GNRP evoluează cu insuficiență renală acută în săptămâni până la luni, cu necroză glomerulară focală ± semilune.","Lipsa necrozei celulare și a semilunelor deosebește nefrita acută de GNRP, pe un continuum.","Cadranul 36.13 distinge patternurile de imunofluorescență liniar, granular și pauci-imun.","Nu: semiluna este un agregat celular; GNRP poate fi liniară, granulară sau pauci-imună."]],
 [8,"Confuzia semilună = depozit liniar IgG este capcana clasică; textul o definește celular."],["spaţiul lui Bowman","Cadranul 36,13"]),

q("nefrologie-adv-085",["Glomerulonefrita poststreptococică – tratament și urmărire:",
 ["profilaxia cu penicilină pe termen lung are dovezi solide","adultul nu necesită urmărire, prognosticul fiind identic copilului","corticosteroizii sunt prima linie la copil, înaintea controlului TA","la adult se recomandă urmărirea anuală a TA și creatininei","abcesul visceral se tratează prin plasmafereză, fără drenaj"],"D",1361,"Glomerulul și afectarea glomerulară — GNPS: tratament și urmărire",
 "Recunoașterea absenței dovezilor pentru profilaxia cu penicilină și a urmăririi anuale la adult.",
 ["Nu: textul afirmă că lipsesc dovezi în sprijinul profilaxiei cu penicilină pe termen lung.","Nu: un număr mic de adulți dezvoltă ulterior HTA sau BCR, de aceea se recomandă urmărire anuală.","Nu: tratamentul vizează TA, diureticele și, la nevoie, dializa; steroizii doar dacă recuperarea este lentă.","La adult se recomandă monitorizarea anuală a TA și a creatininei; profilaxia cu penicilină nu are dovezi.","Nu: abcesul visceral se tratează cu antibiotice și drenaj, cu recuperare în circa 50% din cazuri."]],
 [8,"Intuiția „penicilină de durată după streptococ” este tocmai infirmată de text."],["profilaxiei cu penicilină","monitorizarea anuală"]),

q("nefrologie-adv-086",["Glomerulonefrita din endocardită, șunt infectat sau abces visceral:",
 ["în endocardită, leziunile sunt de obicei focale și segmentare","eradicarea infecției duce de obicei la recuperarea funcției","în abcesul visceral, complementul seric este scăzut","după antibiotice și drenaj, ~50% dintre abcese se recuperează complet","plasmafereza înlocuiește drenajul chirurgical al abcesului"],"ABD",1361,"Glomerulul și afectarea glomerulară — GN infecțioasă non-streptococică",
 "Contrastul endocardită/șunt (focal-segmentar, S. aureus) versus abces visceral (C normal, fără depozite, recuperare ~50%).",
 ["Leziunile din endocardită sau șunt sunt de obicei focale și segmentare; cu Staphylococcus aureus pot apărea semilune.","Antibioticele sau eradicarea chirurgicală a infecției duc de obicei la recuperarea funcției renale.","Nu: în abcesul visceral complementul este normal, iar depozitele imune lipsesc la biopsie.","Recuperarea completă după antibiotice și drenaj survine în aproximativ 50% din cazuri.","Nu: în abcesul visceral drenajul rămâne esențial, alături de antibiotice."]],
 [8,"Capcana este aplicarea hipocomplementemiei poststreptococice pe abcesul visceral, unde C este normal."],["Staphylococcus aureus","aproximativ 50% din cazuri"]),

q("nefrologie-adv-087",["Patogeneza și asocierile nefropatiei cu IgA:",
 ["un studiu genomic a arătat o asociere pe cromozomul 6p (CMH)","galactozilarea anormală privește regiunea balama a IgA2","sunt implicați receptorii CD89 (mieloizi) și CD71 (mezangiali)","se asociază cu boala celiacă, psoriazisul și hepatopatiile cronice","antigenul țintă este PLA2R, ca în glomerulopatia membranoasă"],"ACD",1362,"Glomerulul și afectarea glomerulară — Nefropatia IgA: patogeneză și asocieri",
 "Reținerea locusului 6p, a defectului de galactozilare al IgA1 și a asocierilor extra-renale, distincte de PLA2R.",
 ["Un studiu genomic european a arătat o asociere puternică pe cromozomul 6p, în regiunea CMH/DQ și HLA-B.","Nu: anomalia de galactozilare O-linkată privește regiunea balama a IgA1.","Receptorii CD89 (pe celulele mieloide) și CD71 (pe celulele mezangiale) sunt implicați.","Asocierile includ boli hepatice cronice, carcinoame bronșice, spondiloartrită, boală celiacă, mycosis fungoides și psoriazis.","Nu: PLA2R este antigenul glomerulopatiei membranoase, nu al nefropatiei cu IgA."]],
 [8,"Distractorul mută autoantigenul membranoasei (PLA2R) pe cea mai frecventă GN mondială."],["cromozomul 6p","galactozilarea"]),

q("nefrologie-adv-088",["Boala membranei bazale glomerulare subțiri:",
 ["este autozomal dominantă, cu hematurie microscopică persistentă","subțierea MBG se vede la microscopia optică","evoluează de regulă spre boală renală terminală","nu are un tratament cu beneficiu cunoscut","se transmite legat de X, prin mutații COL4A5"],"AD",1362,"Glomerulul și afectarea glomerulară — MBG subțire versus Alport",
 "Separarea hematuriei familiale benigne (AD, ME, prognostic bun) de Alport legat de X.",
 ["Boala se transmite autozomal dominant și se prezintă cu hematurie glomerulară microscopică persistentă.","Nu: diagnosticul se face prin biopsie, subțierea MBG capilare fiind evidențiată la microscopia electronică.","Nu: prognosticul funcției renale este de obicei foarte bun, deși unii dezvoltă insuficiență de-a lungul deceniilor.","Textul precizează că niciun tratament nu are un beneficiu cunoscut.","Nu: transmiterea legată de X prin COL4A5 definește sindromul Alport, nu boala MBG subțiri."]],
 [8,"Granița vagă Alport–MBG subțire este exploatată prin mutarea geneticii COL4A5 pe forma AD benignă."],["autosomal dominant","microscopie electronică"]),

q("nefrologie-adv-089",["Boala anti-MBG – patogeneză și evoluție:",
 ["autoanticorpii vizează epitopul α3(IV) NC1 al colagenului IV","hidrocarburile sau fumul de țigară pot expune epitopii criptici","IL-12 și interferonul-gamma favorizează formarea semilunelor","netratați, autoanticorpii dispar spontan în decurs de 3 ani","evoluează în cicluri de remisie și reactivare, ca LES"],"ABCD",1363,"Glomerulul și afectarea glomerulară — Anti-MBG: epitop, mediu și single hit",
 "Reținerea epitopului criptic (hidrocarburi/fum), a IL-12/IFN-γ și a dispariției spontane a anticorpilor în 3 ani.",
 ["Specificitatea autoanticorpilor pentru epitopul α3(IV) NC1 al colagenului de tip IV este subliniată.","Expunerea la hidrocarburi sau la fum de țigară este invocată pentru descoperirea epitopilor criptici.","Formarea semilunelor este facilitată de IL-12 și interferon-gamma.","Netratați, autoanticorpii dispar spontan în decurs de 3 ani; boala este de tip „single hit”.","Nu: boala este de tip „single hit”, cu dispariția spontană a autoanticorpilor, spre deosebire de bolile cu remisie și reactivare."]],
 [8,"Capcana „ca LES” este infirmată de dispariția anticorpilor în 3 ani și de formula single hit."],["fum de ţigară","single hit"]),

q("nefrologie-adv-090",["Vasculitele ANCA-asociate – date recente de tratament:",
 ["rituximabul este la fel de eficient în inducția pe 6–12 luni","în PEXIVAS, plasmafereza nu a influențat mortalitatea sau BRT","dozele orale mai mici de glucocorticoizi au redus infecțiile grave","colonizarea căilor aeriene cu Staph. aureus scade riscul de recidivă","în PEXIVAS, plasmafereza a redus mortalitatea și evoluția spre BRT"],"ABC",1364,"Glomerulul și afectarea glomerulară — ANCA: PEXIVAS, rituximab de inducție, S. aureus",
 "Integrarea PEXIVAS (fără beneficiu al plasmaferezei; steroizi mai mici) cu rituximabul de inducție și cu rolul S. aureus.",
 ["Rituximabul este la fel de eficient în inducția pe termen scurt (6–12 luni), cu rate similare de evenimente adverse.","Studiul PEXIVAS (peste 700 de pacienți) nu a arătat un efect al plasmaferezei asupra mortalității sau a evoluției spre BRT.","Dozele orale mai mici de glucocorticoizi au redus infecțiile grave, fără un control mai slab al bolii.","Nu: colonizarea căilor aeriene superioare cu Staph. aureus crește riscul de recidivă; sulfametoxazol/trimetoprim reduce recidivele.","Nu: PEXIVAS nu a arătat că plasmafereza influențează mortalitatea sau evoluția către BRT."]],
 [8,"PEXIVAS răstoarnă intuiția „plasmafereză la GNRP severă”; distractorul reinstaurează dogma pre-studiu."],["PEXIVAS","Staph. aureus"]),

q("nefrologie-adv-091",["Nefropatia cu IgM:",
 ["are hipercelularitate mezangială cu depozite de IgM și complement","răspunde la steroizi în 50%; 10–30% progresează spre BCR","are prognosticul NLM, cu remisiune la peste 95%","are depozite liniare de IgG anti-MBG, fără proliferare mezangială","se prezintă fără hematurie, ca sindrom nefritic pur"],"AB",1365,"Glomerulul și afectarea glomerulară — Nefropatia IgM",
 "Deosebirea de NLM prin răspunsul de 50% la steroizi și riscul 10–30% de BCR/GSFS.",
 ["Histologia arată creșterea celularității mezangiale, cu depozite granulare de IgM și complement.","Răspunsul la steroizi este de doar 50%, iar 10–30% dezvoltă BCR progresivă și GSFS secundară.","Nu: spre deosebire de NLM, prognosticul nu este constant bun, răspunsul la steroizi fiind de 50%.","Nu: depozitele liniare de IgG aparțin bolii anti-MBG; nefropatia cu IgM are depozite mezangiale granulare.","Nu: pacienții au hematurie și sindrom nefrotic."]],
 [8,"Permutează rata de răspuns a NLM (>95%) pe nefropatia IgM, unde steroizii reușesc doar pe jumătate."],["răspunsul la steroizi este de doar 50%","10% şi 30%"]),

q("nefrologie-adv-092",["Nefropatia C1q:",
 ["are depozite mezangiale de C1q, fără incluziuni tubuloreticulare","are constant incluziuni tubuloreticulare, ca nefrita lupică de clasă IV","se colorează pentru DNAJB9 și are fibrile de 20–30 nm","are ca antigen țintă PLA2R, ca membranoasa","se diagnostichează prin ANCA, C1q fiind absent"],"A",1365,"Glomerulul și afectarea glomerulară — Nefropatia C1q versus „lupus seronegativ”",
 "Recunoașterea capcanei de lupus seronegativ: C1q intens la IF, fără incluziuni tubuloreticulare.",
 ["Se deosebește de nefropatia IgM prin depozitele mezangiale de C1q, colorare intensă la imunofluorescență și absența incluziunilor tubuloreticulare la ME.","Nu: incluziunile tubuloreticulare (interferon-α) lipsesc, spre deosebire de lupus.","Nu: colorarea DNAJB9 aparține glomerulopatiei fibrilare.","Nu: PLA2R este antigenul glomerulopatiei membranoase.","Nu: diagnosticul este histologic, prin imunofluorescență cu C1q intens, nu prin ANCA."]],
 [8,"Capcana „lupus seronegativ” este numită în text; distractorii mută markeri din boli învecinate (DNAJB9, PLA2R, ANCA)."],["depunerilor de Clq","incluziunilor tubuloreticulare"]),

q("nefrologie-adv-093",["Gammopatia monoclonală cu semnificație renală (MGRS):",
 ["include boli de depozit: amiloidoza AL, GN fibrilară, MIDD","include boli de precipitare: GN crioglobulinemică","include, prin activarea complementului, nefropatia C3 și SHU atipic","bortezomibul și rituximabul depășesc imunosupresia convențională","paraproteina nu are rol patogenic în leziunea renală"],"ABCD",1366,"Glomerulul și afectarea glomerulară — Spectrul MGRS și terapia țintită",
 "Maparea celor trei categorii MGRS și a superiorității bortezomib/rituximab/daratumumab față de imunosupresia clasică.",
 ["Bolile de depozit includ AL, GN fibrilară/imunotactoidă, MIDD, GN proliferativă cu Ig monoclonale și tubulopatia cu lanțuri ușoare.","GN crioglobulinemică figurează la bolile de precipitare.","Nefropatia C3 cu paraproteinemie și SHU atipic sunt boli prin activarea complementului.","Bortezomibul, rituximabul și posibil daratumumabul au rezultate mai bune decât imunosupresia convențională.","Nu: în MGRS paraproteina produce leziunea renală, iar imunosupresia convențională nu a demonstrat beneficii semnificative."]],
 [8,"Trei categorii (depozit/precipitare/complement) sunt ușor de amestecat; distractorul inversează ierarhia terapeutică."],["daratumumab","MGRS"]),

q("nefrologie-adv-094",["Glomerulopatia cu fibronectină:",
 ["este autozomal recesivă, legată de mutația uteroglobinei","are depuneri negative la colorația Roșu Congo","debutează cu proteinurie între 20 și 40 de ani","fibronectina este o glicoproteină dimerică de ~250 kDa/subunitate","se colorează intens Roșu Congo, ca amiloidoza AL"],"BCD",1366,"Glomerulul și afectarea glomerulară — Glomerulopatia cu fibronectină",
 "Deosebirea de amiloid prin negativitatea Roșu Congo, genetica AD/uteroglobină și vârsta 20–40 de ani.",
 ["Nu: boala este autozomal dominantă, etiologia sugerată fiind mutația uteroglobinei cu pierderea funcției.","Depunerile fibrilare sunt negative la Roșu Congo, ca în formele fibrilară și imunotactoidă.","Se prezintă cu proteinurie între 20 și 40 de ani, apoi HTA, hematurie microscopică și progresie lentă spre BRT.","Fibronectina este o glicoproteină dimerică, de circa 250 kDa pe subunitate.","Nu: negativitatea Roșu Congo o deosebește de amiloid."]],
 [8,"Calibrul și colorația sunt permutabile cu amiloidul; uteroglobina este detaliul genetic nefolosit."],["uteroglobinei","20 şi 40 de ani"]),

q("nefrologie-adv-095",["Nefrita lupică de clasă I și II (Cadranul 36.16):",
 ["clasa I are depozite imune, cu glomeruli normali la microscopia optică","clasa II se manifestă clinic prin boală renală severă","clasa I nu necesită tratament specific","clasa II poate primi hidroxiclorochină și/sau steroizi","clasa I se tratează cu ciclofosfamidă i.v. și plasmafereză"],"ACD",1366,"Glomerulul și afectarea glomerulară — Nefrita lupică: clasele I–II",
 "Aplicarea definițiilor ISN/RPS pentru clasele ușoare și a abținerii terapeutice la clasa I.",
 ["Clasa I este mezangială minimă: depozite imune, glomeruli normali la microscopia optică, asimptomatică.","Nu: clasa II este proliferativă mezangială, cu boală renală ușoară clinic.","Nefrita lupică de clasă I nu necesită tratament specific.","Clasa II are de obicei un curs benign; o parte dintre pacienți primesc hidroxiclorochină și/sau steroizi.","Nu: plasmafereza și ciclofosfamida aparțin formelor proliferative severe, nu clasei I."]],
 [8,"Capcana este „overtreatment” al clasei I, tratată ca GNRP, deși cadranul o descrie asimptomatică."],["Clasa I","hidroxiclorochină"]),

q("nefrologie-adv-096",["Poliarterita nodoasă cu afectare renală:",
 ["produce anevrisme ale aortei, cu HTA și infarcte viscerale","anevrismele apar la arteriografie, pacienții fiind ANCA-negativi","predomină la bărbați și vârstnici, putând asocia hepatita B","evoluează de obicei ca GNRP fulminantă ANCA-pozitivă","răspunde mai bine la imunosupresie decât poliangeita microscopică"],"BC",1368,"Implicarea rinichiului în alte afecțiuni — Poliarterita nodoasă",
 "Deosebirea PAN (artere medii, ANCA-negativ, HTA severă lent progresivă) de MPA pauci-imună.",
 ["Nu: PAN produce dilatarea anevrismală a arterelor medii, nu a aortei, cu hipertensiune, polineuropatie și infarcte ischemice viscerale.","Anevrismele pot fi evidențiate prin arteriografie renală, iar pacienții sunt tipic ANCA-negativi.","PAN predomină la bărbați și vârstnici și se poate asocia cu droguri și hepatita B.","Nu: evoluția rapid progresivă este rară, iar PAN nu este o vasculită ANCA.","Nu: imunosupresia este mai puțin eficientă decât în poliangeita microscopică."]],
 [8,"Confuzia PAN–MPA (ANCA, semilune) este firul roșu; textul le desparte prin calibrul arterial și serologie."],["ANCA negativi","hepatita B"]),

q("nefrologie-adv-097",["Gravidă cu hipertensiune și proteinurie cu debut rapid. Glomerulopatia din preeclampsie:",
 ["persistă cel puțin 6 luni postpartum la 30% dintre paciente","implică sFlt1 supraexprimat, care potențează VEGF și PlGF","implică anticorpi anti-receptor AT1 care cresc NADPH-oxidaza","dispare în 48 de ore, fără leziune histologică","este o vasculită ANCA-PR3 a arteriolelor glomerulare"],"AC",1368,"Implicarea rinichiului în alte afecțiuni — Preeclampsia: sFlt1 și VEGF",
 "Corelarea endoteliozei, a persistenței la 30%/6 luni și a axei sFlt1–VEGF.",
 ["Leziunea asociază inflamație endotelială marcată și obliterarea lumenului capilar; la 30% modificările persistă ≥6 luni după naștere.","Nu: sFlt1 supraexprimat antagonizează VEGF și factorii de creștere placentari, provocând disfuncție endotelială.","Anticorpii împotriva receptorilor angiotensinei II (AT1) cresc NADPH-oxidaza placentară.","Nu: există o leziune histologică (endotelioză), care poate persista sau fi ireversibilă.","Nu: glomerulopatia din preeclampsie nu este o vasculită ANCA."]],
 [8,"Vigneta obstetrică împinge spre „totul trece după naștere”; textul citează persistență la 30% și axa sFlt1."],["sFlt1","30% dintre pacienţi"]),

q("nefrologie-adv-098",["Glomerulonefrita paraneoplazică, după tipul tumorii:",
 ["timom sau limfom Hodgkin: polarizare Th2 și IL-13","limfom B sau leucemie: Ig monoclonală sau crioglobulină","policitemie vera sau trombocitemie: GSFS prin PDGF trombocitar","carcinom epitelial: depozite subepiteliale predominant IgG4","tumori solide: boală anti-MBG, indiferent de linia celulară"],"ABC",1368,"Implicarea rinichiului în alte afecțiuni — GN paraneoplazică",
 "Maparea perechilor tumoră–leziune (Th2/IL-13, crioglobulină, PDGF, IgG1/IgG2).",
 ["Timomul și limfomul Hodgkin se asociază cu polarizare Th2 și IL-13, cu NLM, GNMC sau membranoasă.","Limfomul B și leucemia se leagă de Ig monoclonală, crioglobulină și eventual VHC.","Trombocitoza severă (policitemie vera, trombocitemie esențială, mielofibroză) poate induce GSFS prin PDGF din trombocite.","Nu: în carcinomul epitelial, complexele subepiteliale IgG1 și IgG2 ajută la recunoașterea membranoasei paraneoplazice.","Nu: leziunea depinde de tipul tumorii, nu este o boală anti-MBG comună tumorilor solide."]],
 [8,"Patru perechi tumoră–histologie sunt concepute să fie permutabile; distractorul le reduce la Goodpasture."],["IL-13","lgG1 şi lgG2"]),

q("nefrologie-adv-099",["Pielonefrita xantogranulomatoasă:",
 ["este produsă de E. coli și se vindecă prin antibiotic oral 3 zile","este de obicei bilaterală și se vindecă prin hidratare","se asociază cel mai adesea cu Proteus și calcul coraliform","se diagnostichează prin MAG3, nefrectomia fiind contraindicată","asociază uveită și anticorpi anti-PCR modificată"],"C",1385,"Nefritele tubulointerstițiale — Pielonefrita xantogranulomatoasă",
 "Recunoașterea triadei Proteus–calcul coraliform–nefrectomie, distinctă de NTI medicamentoasă și de NTIU.",
 ["Nu: germenul cel mai frecvent este Proteus, iar antibioticele rareori eradică infecția; tratamentul de elecție este nefrectomia.","Nu: pielonefrita xantogranulomatoasă este de obicei unilaterală.","Este o infecție cronică rară, cel mai adesea cu Proteus, de obicei unilaterală, cu calcul coraliform; tratamentul de elecție este nefrectomia.","Nu: diagnosticul se pune prin CT, iar nefrectomia este tratamentul de elecție.","Nu: uveita și anticorpii anti-PCR modificată caracterizează sindromul NTIU."]],
 [8,"Nefrectomia ca elecție este contraintuitivă față de o „pielonefrită” obișnuită."],["Proteus-ului","calcul coraliform"]),

q("nefrologie-adv-100",["Sindromul nefrită tubulointerstițială–uveită (NTIU):",
 ["asociază uveită, NTI acută, pierdere ponderală și VSH crescut","apare în copilărie și, la adult, mai frecvent la bărbați","se poate asocia cu anticorpi anti-PCR modificată","răspunde la o cură prelungită de corticosteroizi","este o infecție cu Proteus care impune nefrectomie"],"ACD",1386,"Nefritele tubulointerstițiale — Sindromul NTIU",
 "Recunoașterea tabloului uveită–NTI–VSH, a predilecției de sex și a răspunsului la steroizi prelungiți.",
 ["NTIU asociază uveită, NTI acută, pierdere ponderală, anemie și VSH crescut, de cauză necunoscută.","Nu: NTIU apare frecvent în copilărie, iar la adult este mai frecventă la femei.","Se poate asocia cu autoanticorpi anti-proteina C reactivă modificată.","O cură prelungită de corticosteroizi ameliorează funcția renală și uveita.","Nu: infecția cu Proteus și nefrectomia aparțin pielonefritei xantogranulomatoase."]],
 [8,"Distractorul mută nefrectomia din xantogranulomatoasă pe un sindrom steroid-responsiv cu uveită."],["uveită","anti￾proteina C reactivă"]),

q("nefrologie-adv-101",["Nefropatia analgetică:",
 ["urmează consumului cronic de fenacetină sau AINS în doze mari","apare mai frecvent la femeile de vârstă medie","se poate complica cu obstrucție prin papilă necrozată migrată","nu poate produce pierdere de sare și de lichide","este o glomerulopatie cu semilune, ANCA-pozitivă"],"ABC",1386,"Nefritele tubulointerstițiale — Nefropatia analgetică",
 "Corelarea fenacetinei/AINS cu necroza papilară, predilecția feminină și pierderea de sare.",
 ["Urmează consumului cronic de analgezice în doze mari: clasic fenacetină, mai recent AINS.","Apare mai frecvent la femeile de vârstă medie.","Tabloul include anemie, BCR, ITU, hematurie sau obstrucție prin papilă necrozată migrată.","Nu: nefropatia analgetică poate asocia pierdere de lichide și de sare.","Nu: este o NTI cronică cu necroză papilară, nu o vasculită ANCA."]],
 [8,"Necroza papilară și pierderea de sare sunt ușor de înlocuit cu un pattern glomerular ANCA."],["fenacetină","vârstă medie"]),

q("nefrologie-adv-102",["Nefrita tubulointerstițială acută de cauză infecțioasă:",
 ["poate complica infecții cu Hantavirus, EBV, Legionella sau Leptospira","poate fi fatală în febra hemoragică cu Hantavirus","la transplantați, implică CMV, virusul BK sau herpesvirusuri","infecțiile reprezintă circa 70% din cauzele NTI acute","Hantavirusul produce o NTI inofensivă, fără risc vital"],"ABC",1385,"Nefritele tubulointerstițiale — NTI infecțioasă și Hantavirus",
 "Reținerea spectrului viral/bacterian și a cotelor din Cadranul 36.27 (70/15/8/5%).",
 ["NTI acută poate complica infecții cu Hantavirus, EBV, HIV, rujeolă, adenovirus, Legionella, Leptospira, Mycoplasma, Brucella sau Toxoplasma.","Hantavirusul produce febră hemoragică cu NTI și poate fi fatal.","La transplantați sunt implicate CMV, virusul polyoma (BK) și herpesvirusurile.","Nu: medicamentele produc circa 70% din NTI acute, infecțiile ~15%, formele idiopatice ~8% și NTIU ~5%.","Nu: infecția cu Hantavirus este citată ca potențial fatală."]],
 [8,"Cotele 70/15/8/5% sunt permutabile; distractorul banalizează Hantavirusul."],["Hantavirus","70%}"]),

q("nefrologie-adv-103",["Prevenția nefropatiei de contrast:",
 ["se preferă substanțele de contrast hiperosmolare","hidratare cu 1 L ser fiziologic sau bicarbonat 1,4%","N-acetilcisteina are cel mult un beneficiu marginal","dopamina și dializa profilactică nu sunt benefice","N-acetilcisteina poate înlocui hidratarea"],"BCD",1392,"Boala cronică de rinichi — Contrast: hidratare, osmolalitate, NAC",
 "Ierarhizarea măsurilor (doză, osmolalitate, 1 L NaCl/bicarbonat) față de NAC marginal și de dopamină/dializă ineficiente.",
 ["Nu: se minimizează doza și se folosesc substanțe de contrast izo-osmolare sau hipo-osmolare.","Se administrează 1 L ser fiziologic 0,9% sau 1 L bicarbonat 1,4% peri-procedural și 8–12 ore post-procedural.","N-acetilcisteina administrată cu 48 de ore înainte oferă cel mult un beneficiu marginal.","Dopamina, teofilina și dializa profilactică nu sunt benefice.","Nu: hidratarea rămâne esențială, iar N-acetilcisteina nu o înlocuiește."]],
 [8,"NAC „de protocoale vechi” este coborâtă la beneficiu marginal; distractorul o urcă peste hidratare."],["1 L ser fiziologic 0,9%","beneficiu mar￾ginal"]),

q("nefrologie-adv-104",["Nefropatia acută prin precipitare de fosfat:",
 ["poate urma pregătirii digestive cu fosfat de sodiu oral","fosfatul oral este contraindicat în BCR, ICC și hipercalcemie","biopsia arată depuneri masive de fosfați","are în general o recuperare renală bună","fosfatul oral previne nefropatia de contrast"],"ABCD",1392,"Boala cronică de rinichi — Precipitarea de fosfat post-pregătire digestivă",
 "Recunoașterea fosfatului oral de pregătire ca nefrotoxină, a contraindicațiilor și a caracterului suportiv al tratamentului.",
 ["Fosfatul de sodiu oral folosit la pregătirea investigațiilor gastrointestinale este triggerul.","Fosfatul oral este contraindicat în BCR, ICC, obstrucții digestive și hipercalcemie preexistentă.","Biopsiile arată depuneri masive de fosfați; tratamentul este suportiv, cu dializă la nevoie.","Recuperarea renală este în general bună.","Nu: fosfatul oral precipită insuficiența renală acută, nu previne nefropatia de contrast."]],
 [8,"Capcana este transformarea unei cauze de IRA (fosfat oral) într-o măsură „protectoare” peri-contrast."],["fosfatului de sodiu oral","depuneri masive de fosfaţi"]),

q("nefrologie-adv-105",["Boala cronică de rinichi (BCR) – definiție și reversibilitate:",
 ["se definește prin alterare renală persistentă peste 3 săptămâni","în majoritatea stadiilor 1–3, funcția nu se deteriorează continuu","poate fi reversibilă după înlăturarea unei obstrucții","în Africa sub-sahariană, malaria poate produce GN și BCR","în stadiile 1–3 progresează spre dializă în sub 3 luni"],"BCD",1392,"Boala cronică de rinichi — Definiție, reversibilitate și geografie",
 "Fixarea pragului >3 luni, a stabilității stadiilor 1–3 și a excepțiilor reversibile, plus cauzele geografice.",
 ["Nu: BCR implică o alterare de lungă durată, de peste 3 luni, cu potențial progresiv.","În majoritatea stadiilor 1–3 funcția nu continuă să se deterioreze, iar decesul nu survine direct prin boala renală.","Excepțiile reversibile includ înlăturarea obstrucției, imunosupresia în GN/vasculite, tratamentul HTA accelerate și corecția stenozelor critice de artere renale.","Malaria (GN în Africa sub-sahariană) și schistosomiaza obstructivă (Orientul Mijlociu, sudul Irakului) sunt exemplele geografice.","Nu: multe stadii 1–3 nu progresează, iar unele cauze sunt reversibile."]],
 [8,"Intuiția „BCR = dializă inevitabilă” este infirmată de stabilitatea stadiilor 1–3 și de lista de cauze reversibile."],[">3 luni","schistosomiaza"]),

q("nefrologie-adv-106",["Inițierea tratamentului cu ASE în anemia din BCR:",
 ["darbepoetină 300 µg săptămânal, fără monitorizarea TA","epoetină-α 50 U/kg de trei ori pe săptămână","fier oral și o țintă de hemoglobină peste 140 g/L","transfuzii lunare, ASE fiind retrase din uz","epoetină-α 50 U/kg o dată pe lună"],"B",1394,"Boala cronică de rinichi — ASE: doze de start și ținta Hb",
 "Reținerea schemei epoetină 50 U/kg ×3/săptămână versus darbepoetină 30 µg/săptămână și a țintei 100–120 g/L.",
 ["Nu: doza inițială de darbepoetină este 30 µg o dată pe săptămână.","Epoetina-α se începe cu 50 U/kg de trei ori pe săptămână (sau darbepoetină 30 µg/săptămână), cu Hb la 2 săptămâni și țintă 100–120 g/L.","Nu: fierul i.v. este preferat, iar ținta Hb este 100–120 g/L; peste 120 g/L nu s-au arătat beneficii în predializă.","Nu: ASE au schimbat tratamentul, iar transfuziile se evită, inclusiv pentru sensibilizarea HLA.","Nu: doza de 50 U/kg se administrează de trei ori pe săptămână."]],
 [8,"Permutează 50 U/kg, 30 µg și 300 U/kg (doza de „non-responder”) între schemele de start."],["50 U/kg","30 µg o dată pe săptămână"]),

q("nefrologie-adv-107",["Complicațiile și perspectivele tratamentului anemiei din BCR:",
 ["hipertensiunea apare la 30% dintre pacienții care încep ASE","aplazia eritrocitară pură s-a asociat cu epoetina-α s.c. preumplută","inhibitorii de prolilhidroxilază scurtează viața HIF-1α","corecția anemiei reduce transfuziile și sensibilizarea HLA","aplazia eritrocitară pură este o complicație a fierului oral"],"ABD",1394,"Boala cronică de rinichi — ASE: HTA 30%, PRCA, HIF",
 "Legarea cotei de 30% HTA, a PRCA de seringile preumplute și a mecanismului inhibitorilor de prolilhidroxilază.",
 ["Hipertensiunea este un efect secundar important la 30% dintre pacienții la care se inițiază ASE.","Aplazia eritrocitară pură prin anticorpi anti-eritropoietină a fost legată de garnitura de cauciuc a seringilor preumplute cu epoetină-α s.c.","Nu: agenții orali care inhibă prolilhidroxilaza prelungesc viața HIF-1α, stimulând producția endogenă de eritropoietină.","Corecția anemiei evită transfuziile și, astfel, sensibilizarea HLA.","Nu: aplazia eritrocitară pură este legată de ASE administrate s.c., nu de fierul oral."]],
 [8,"PRCA prin garnitura seringii este un detaliu ușor de atribuit fierului; cota 30% HTA trebuie ținută minte."],["30% din pacienţii","prolilhidroxilaza"]),

q("nefrologie-adv-108",["Principiile hemodializei:",
 ["dializantul curge în același sens cu sângele","moleculele mici traversează membrana prin difuziune","în 4 ore pot fi circulați până la 80 L de sânge","inițierea precoce nu a ameliorat supraviețuirea în unele trialuri","o ședință de 4 ore echivalează cu un RFG de 80 ml/min"],"BCD",1399,"Boala cronică de rinichi — Hemodializa: contracurent, 80 L, RFG echivalentă",
 "Contrastul dintre volumul circulat (80 L) și RFG echivalentă modestă (10–12 ml/min), plus mesajul trialurilor de inițiere precoce.",
 ["Nu: sângele anticoagulat trece printr-o membrană semipermeabilă, iar dializantul ultra-pur curge în contracurent.","Moleculele mici traversează membrana prin difuziune, iar presiunea transmembranară permite ultrafiltrarea și convecția.","Într-o ședință standard de 4 ore pot fi circulați până la 80 L de sânge (~300 ml/min).","Inițierea precoce a dializei nu s-a asociat, în unele trialuri, cu ameliorarea supraviețuirii.","Nu: RFG echivalentă este doar 10–12 ml/min pe m²; 80 L este volumul de sânge circulat."]],
 [8,"Permutează 80 L (volum circulat) cu 10–12 ml/min (RFG echivalentă), capcana aritmetică a paginii."],["80 de litri de sânge","10-12 ml/min pe m2"]),

q("nefrologie-adv-109",["Abordul vascular pentru hemodializă:",
 ["debitul necesar, 250–450 mL/min, se obține printr-o FAV","la capital venos sărac se pot folosi proteze vasculare sintetice","se evită venipunctura pe venele destinate fistulei","fistula arteriovenoasă se creează pe brațul dominant","cateterul femoral este abordul definitiv de elecție"],"ABC",1399,"Boala cronică de rinichi — FAV: debit, materiale, timing",
 "Reținerea debitului 250–450 mL/min, a perechii radială/cefalică și a creării FAV din timp pe brațul nedominant.",
 ["O dializă eficientă cere un debit de 250–450 mL/min, obținut prin FAV între artera radială sau brahială și vena cefalică.","La capital venos deficitar sau arteriopatie (de exemplu în diabet) se pot folosi proteze vasculare sintetice.","Venipunctura de rutină pe venele destinate fistulei trebuie evitată.","Nu: FAV se creează din timp, la o creatinină de circa 400–500 µmol/L, pe brațul nedominant.","Nu: FAV rămâne abordul de elecție; cateterul femoral nu este un abord definitiv."]],
 [8,"Debitul 250–450 și creatinina 400–500 sunt ușor de permutat; distractorul promovează cateterul ca elecție."],["250 şi 450 mL/min","vena cefalică"]),

q("nefrologie-adv-110",["Genetica și ciliopatia din boala polichistică renală:",
 ["PKD1 codifică policistina, implicată în interacțiunile celulă-matrice","perturbarea complexului ciliar crește calciul citoplasmatic","mutațiile GANAB explică boala polichistică hepatică asociată","forma autozomal recesivă ține de PKHD1, de obicei letală precoce","PKD2 codifică lanțul COL4A5, ca în sindromul Alport"],"ACD",1405,"Bolile renale chistice — Policistine, cili și GANAB",
 "Legarea cililor/policistinelor de GANAB hepatic și deosebirea de PKHD1 recesiv.",
 ["PKD1 codifică policistina (interacțiuni celulă-celulă și celulă-matrice), iar PKD2 policistina 2, un canal de calciu.","Nu: perturbarea complexului de policistine din cili scade calciul citoplasmatic și duce la chisturi în ductul colector.","Boala polichistică hepatică asociată se datorează mutațiilor GANAB (subunitatea α a glucozidazei II).","Forma autozomal recesivă ține de PKHD1 pe 6p21.1-p12 și este cel mai frecvent letală la vârste mici.","Nu: COL4A5 aparține sindromului Alport, iar PKD2 codifică policistina 2."]],
 [8,"Trei locusuri (PKD1, PKD2, PKHD1, GANAB) sunt concepute să fie amestecate cu COL4A5."],["GANAB","policistina 2"]),

q("nefrologie-adv-111",["Infecțiile intrachistice din BPRAD se tratează cel mai eficient cu:",
 ["penicilina G intravenos","aminoglicozidele, administrate în monoterapie","nitrofurantoinul oral","vancomicina intravenos","co-trimoxazolul sau fluorochinolonele"],"E",1405,"Bolile renale chistice — BPRAD: infecția de chist",
 "Alegerea clasei lipofile (co-trimoxazol, fluorochinolone) care penetrează peretele chistului.",
 ["Nu: penicilina G nu penetrează peretele chistului; textul cere antibiotice lipofile active pe Gram-negativi.","Nu: textul recomandă antibiotice lipofile care penetrează chistul (co-trimoxazol, fluorochinolone), nu aminoglicozide.","Nu: nitrofurantoinul nu figurează; se folosesc co-trimoxazolul sau fluorochinolonele.","Nu: vancomicina nu este un antibiotic lipofil activ pe Gram-negativi, cum cere textul.","Co-trimoxazolul și fluorochinolonele sunt antibiotice lipofile care penetrează peretele chistului și sunt active pe Gram-negativi."]],
 [8,"Penetrarea peretelui chistului selectează lipofilele; distractorii sunt antibiotice uzuale de ITU joasă."],["co-trimoxazolul","fluorochinolonele"]),

q("nefrologie-adv-112",["Boala polichistică renală autozomal dominantă:",
 ["este cea mai frecventă nefropatie ereditară","explică 3–10% dintre pacienții care încep dializa cronică în Occident","creșterea rapidă a chisturilor la RMN prezice pierderea funcției","roscovitina este un inhibitor mTOR, iar sirolimusul un inhibitor CDK","are o prevalență de circa 1 la 2 milioane"],"ABC",1405,"Bolile renale chistice — BPRAD: 1:400–1:1000 și terapii experimentale",
 "Fixarea prevalenței și a cotei 3–10% din dializă, a valorii prognostice a creșterii chisturilor și a țintelor roscovitinei (CDK) și sirolimusului (mTOR).",
 ["BPRAD este cea mai frecventă nefropatie ereditară, cu prevalență de 1:400–1:1.000 la populația albă.","În Occident, BPRAD este nefropatia de bază la 3–10% dintre pacienții care intră în dializă cronică.","Declinul RFG depinde de rata de creștere a chisturilor; cei cu creștere rapidă la RMN pierd funcția mai repede.","Nu: roscovitina este un inhibitor de CDK, iar sirolimusul un inhibitor mTOR, ambele menționate alături de vaptani, pe modele animale.","Nu: prevalența BPRAD este 1:400–1:1.000; 1 la 2 milioane corespunde bolii anti-MBG."]],
 [8,"Permutează 1:400–1:1000 cu 1 la 2 milioane (Goodpasture); roscovitina/sirolimusul sunt detalii nefolosite."],["1:400 şi 1:1.000","roscovitina"]),

q("nefrologie-adv-113",["Chisturile renale dobândite și chisturile simple:",
 ["chisturile dobândite apar pe rinichi nefuncționali, la dializați sau transplantați","chisturile dobândite au potențial de malignizare","chisturile simple mari pot sângera, cu durere sau hematurie","chisturile dobândite reprezintă o formă de BPRAD genetică","chisturile simple ale vârstnicului au de regulă potențial malign"],"ABC",1405,"Bolile renale chistice — Boala chistică dobândită și malignizare",
 "Separarea potențialului malign al chisturilor dobândite de dializă de chisturile simple ale vârstnicului.",
 ["Degenerarea chistică apare de regulă în rinichii nefuncționali ai pacienților tratați prin dializă sau transplant.","Chisturile dobândite ale pacientului cu BRT au potențial de malignizare.","Ocazional, chisturile simple mari produc durere și/sau hematurie prin sângerare intrachistică.","Nu: chisturile dobândite nu echivalează cu BPRAD genetică; apar pe rinichi nefuncționali, la dializați sau transplantați.","Nu: relația este inversă: chisturile dobândite au potențial malign, cele simple ale vârstnicului de obicei nu."]],
 [8,"Potențialul malign al chisturilor de dializă este contraintuitiv față de chisturile simple „de vârstă”."],["potenţial de malignizare","sângerare intrachistică"]),

q("nefrologie-adv-114",["Cauzele de nefrită tubulointerstițială acută (Cadranul 36.27) includ:",
 ["cefalosporine, ciprofloxacină, rifampicină și sulfonamide","diureticele furosemid și tiazidele","alopurinol, carbamazepină, cimetidină, fenitoină, valproat","NTIU (~5%), LES (~2%) și nefropatia IgG4","infecția cu hantavirus, ca principală cauză (~70%)"],"ABCD",1385,"Nefritele tubulointerstițiale — Cadranul 36.27: lista extinsă de medicamente",
 "Completarea listei de medicamente (diuretice, anticonvulsivante, alopurinol) și a cotelor NTIU/LES, fără a inversa ierarhia 70% medicamentos.",
 ["La antibiotice, Cadranul 36.27 enumeră cefalosporinele, ciprofloxacina, eritromicina, rifampicina și sulfonamidele.","Furosemidul și tiazidele figurează la diuretice în Cadranul 36.27.","La „altele” figurează alopurinolul, carbamazepina, cimetidina, fenitoina și valproatul.","Cadranul citează NTIU (~5%) și bolile inflamatorii sistemice (LES ~2%, nefropatia IgG4).","Nu: medicamentele produc ~70% din cazuri; Hantavirusul nu este cauza dominantă."]],
 [8,"Inversează ierarhia 70% medicamentos versus 15% infecțios; lista de anticonvulsivante este detaliul nefolosit."],["carbamazepina","valproat"]),

q("nefrologie-adv-115",["Înainte de biopsia renală transcutanată (Cadranul 36.6) se cere:",
 ["un bilanț de coagulare, care trebuie să fie normal","gruparea și salvarea serului pentru cross-match","explicarea procedurii și consimțământul pacientului","inițierea heparinei în doză terapeutică","poziționarea în decubit dorsal, fără ghidaj ecografic"],"ABC",1352,"Glomerulul și afectarea glomerulară — Biopsia: pregătirea pre-procedurală",
 "Aplicarea pașilor din Cadranul 36.6 care preced puncția (coagulare, cross-match, consimțământ).",
 ["Cadranul 36.6 cere un bilanț de coagulare normal înaintea puncției.","Serul este grupat și salvat pentru cross-match, în eventualitatea unei transfuzii.","Pacientului i se explică procedura complet și i se obține consimțământul.","Nu: heparina terapeutică ar crește riscul hemoragic; nu este un pas pre-biopsie.","Nu: biopsia renală se face în decubit ventral, sub ghidaj ecografic, nu dorsal ca la ficat."]],
 [8,"Pașii „înainte” din același cadran sunt ușor de confundat cu timpul procedural (ventral, apnee) deja consacrat."],["bilanţ de coagulare","cross-match"]),

q("nefrologie-adv-116",["Indicațiile biopsiei renale transcutanate includ:",
 ["investigarea sindroamelor nefritice și nefrotice","afecțiunile renale acute și cronice","hematuria, înaintea investigațiilor urologice","evaluarea de primă intenție a obstrucției pielocaliceale","diagnosticul refluxului vezico-ureteral la copil"],"AB",1351,"Investigații — Biopsia renală: indicații",
 "Recunoașterea indicațiilor biopsiei (nefritic/nefrotic, acut/cronic) și a plasării ei după bilanțul urologic în hematurie.",
 ["Investigarea sindroamelor nefritice și nefrotice este o indicație citată a biopsiei.","Afecțiunile renale acute și cronice figurează explicit printre indicații.","Nu: hematuria devine indicație de biopsie după investigațiile urologice, nu înaintea lor; disfuncția grefei este o altă indicație.","Nu: obstrucția pielocaliceală se evaluează cu renograma MAG3, nu prin biopsie.","Nu: refluxul vezico-ureteral la copil se studiază prin cistouretrografie."]],
 [8,"Capcana mută indicațiile scintigrafiei și ale cistouretrografiei pe o biopsie de parenchim."],["sindroamelor nefritice","disfuncţiei grefei renale"]),

q("nefrologie-adv-117",["Renograma MAG3 în suspiciunea de obstrucție:",
 ["curba nu scade după vârful inițial sau continuă să crească","furosemidul crește debitul urinar și subliniază golirea întârziată","trasorul se fixează static pe tubii proximali, ca DMSA","furosemidul este contraindicat, deoarece maschează obstrucția","este înlocuită de cistouretrografie la adultul cu obstrucție"],"AB",1351,"Investigații — Renograma MAG3: curba și furosemidul",
 "Citirea curbei care platonează/crește și a rolului furosemidului de a demasca golirea întârziată.",
 ["Eșecul scăderii curbei timp-activitate după vârful inițial sau creșterea ei continuă confirmă obstrucția.","Furosemidul se administrează pentru a crește debitul urinar și a sublinia întârzierea golirii.","Nu: legarea statică de tubii proximali caracterizează DMSA, nu studiul dinamic MAG3.","Nu: furosemidul nu este interzis; este un adjuvant diagnostic care subliniază întârzierea golirii.","Nu: cistouretrografia evaluează refluxul la copil, nu obstrucția pielocaliceală a adultului."]],
 [8,"Inversează rolul furosemidului (demască versus maschează) pe aceeași frază a renogramei."],["vârf iniţial","Furosemidul"]),

q("nefrologie-adv-118",["Complicațiile biopsiei renale transcutanate (Cadranul 36.7):",
 ["o mortalitate de aproximativ 10%","ocluzie angiografică sau nefrectomie la 1 din 40 de pacienți","anevrism arteriovenos la ~20%, de regulă nesemnificativ","hematurie macroscopică la sub 0,1% dintre pacienți","anevrism arteriovenos care impune, de regulă, nefrectomia"],"C",1352,"Glomerulul și afectarea glomerulară — Cadranul 36.7: anevrismul și mortalitatea",
 "Reținerea cotei de ~20% anevrisme fără semnificație clinică și a mortalității de ~0,1%, distincte de 1/400.",
 ["Nu: mortalitatea biopsiei renale este de aproximativ 0,1%, nu 10%.","Nu: ocluzia angiografică sau nefrectomia pentru sângerare sunt necesare la circa 1 din 400 de pacienți, nu 1 din 40.","Cadranul 36.7 plasează anevrismul arteriovenos la ~20%, fără semnificație clinică în marea majoritate a cazurilor.","Nu: hematuria macroscopică apare la până la 10% dintre pacienți.","Nu: anevrismul arteriovenos este, în marea majoritate a cazurilor, fără semnificație clinică."]],
 [8,"Permutează 20% (anevrism benign), 0,1% (mortalitate) și 1 din 400 (nefrectomie), trei cifre din același cadran."],["aproximativ 20%","0,1%"]),

q("nefrologie-adv-119",["Termenii din Cadranul 36.8 pentru bolile glomerulare:",
 ["segmental: afectarea unei părți a glomerulului","global: implicarea simetrică a întregului glomerul","modificări ale membranei: îngroșarea peretelui capilar","segmental: întregul glomerul implicat simetric","proliferativ: îngroșare parietală fără hipercelularitate"],"ABC",1352,"Glomerulul și afectarea glomerulară — Cadranul 36.8: segmental versus membrană",
 "Deosebirea segmental/global de „modificările de membrană”, fără a le confunda cu proliferativul.",
 ["Segmental înseamnă că doar o parte a glomerulului este afectată; majoritatea leziunilor focale sunt și segmentare.","Global înseamnă implicarea simetrică a întregului glomerul.","Modificările membranei înseamnă îngroșarea peretelui capilar prin depozite imune sau prin modificări ale membranei bazale.","Nu: implicarea simetrică a întregului glomerul definește termenul „global”, nu „segmental”.","Nu: proliferativ înseamnă creșterea numărului de celule, nu doar îngroșarea peretelui capilar."]],
 [8,"Cuvintele segmental/global/membrană sunt concepute să fie permute cu „difuz” și cu proliferativul."],["doar o parte a glomerulului","Modificări ale membranei"]),

q("nefrologie-adv-120",["Podocitul și membrana bazală glomerulară:",
 ["se atașează de MBG prin α3β1 și distroglicani","diafragma cu fante conține P-caderină și α-, β-catenină","nefrina îl leagă de MBG prin intermediul PLA2R","distroglicanii definesc GSFS secundară obezității","P-caderina reprezintă antigenul Goodpasture"],"AB",1352,"Glomerulul și afectarea glomerulară — Adeziunea podocitară: α3β1 și catenine",
 "Completarea listei diafragmei (P-caderină, catenine) cu moleculele de adeziune la MBG (α3β1, distroglicani).",
 ["Podocitele se atașează de MBG prin molecule de adeziune precum α3β1 și distroglicanii.","P-caderina și α-, β-catenina completează proteinele diafragmei cu fante, alături de nefrină și CD2AP.","Nu: nefrina este o proteină a diafragmei cu fante, nu un înlocuitor al α3β1; PLA2R aparține nefropatiei membranoase.","Nu: distroglicanii sunt molecule de adeziune la MBG și nu definesc GSFS de obezitate.","Nu: antigenul Goodpasture este α3(IV) NC1, nu P-caderina."]],
 [8,"α3β1/distroglicanii (adeziune la MBG) sunt ușor de mutat pe fantă sau pe Goodpasture."],["distroglicani","P-cadherina"]),

q("nefrologie-adv-121",["După insulta imună inițială, leziunea glomerulară secundară implică:",
 ["depunerea de fibrină","agregarea plachetară","infiltrarea cu neutrofile și radicalii liberi","cruțarea interstițiului renal","afectarea unui singur rinichi"],"ABC",1352,"Glomerulul și afectarea glomerulară — Mecanisme secundare post-imune",
 "Recunoașterea cascadei fibrină–plachete–neutrofile–ROS, pe fondul leziunii interstițiale simetrice.",
 ["Depunerea de fibrină este citată printre mecanismele secundare de leziune glomerulară.","Agregarea plachetară figurează în aceeași listă de mecanisme secundare.","Infiltrarea neutrofilelor și injuriile provocate de radicalii liberi completează enumerarea.","Nu: afectarea interstițială apare în mod obișnuit, nu doar cea glomerulară.","Nu: rinichii sunt implicați simetric, bilateral."]],
 [8,"Lista de efecte secundare (fibrină, plachete, ROS) este ușor de înlocuit cu „doar glomerul, un singur rinichi”."],["depunerea de fibrină","radicalii liberi"]),

q("nefrologie-adv-122",["Trăsăturile extraglomerulare ale nefritei lupice includ:",
 ["nefrita tubulointerstițială, la 75% dintre pacienți","poliarterita nodoasă a arterelor medii, ANCA-pozitivă","macroglosia și purpura periorbitală","NTI clasificată de la debut drept clasa VI ISN/RPS","tromboza venoasă renală, incompatibilă cu LES"],"A",1367,"Glomerulul și afectarea glomerulară — Nefrita lupică: NTI la 75%",
 "Reținerea cotei de 75% NTI și a spectrului trombotic (venă renală, stenoză arterială) legat de antifosfolipidici.",
 ["Nefrita tubulointerstițială apare la 75% dintre pacienții cu nefrită lupică.","Nu: PAN ANCA-pozitivă nu este leziunea extraglomerulară lupică descrisă.","Nu: macroglosia și purpura periorbitală aparțin amiloidozei AL, nu LES.","Nu: clasa VI ISN/RPS este glomeruloscleroza, nu NTI.","Nu: tromboza venoasă renală figurează printre trăsăturile extraglomerulare și nu exclude LES."]],
 [8,"Cota 75% NTI este contraintuitivă față de imaginea „doar glomerulară” a nefritei lupice."],["75% dintre pacienţi","tromboza venoasă"]),

q("nefrologie-adv-123",["Inducția în nefrita lupică de clasă III, IV sau V:",
 ["steroizi plus ciclofosfamidă i.v. în doze mari sau MMF","la albi, ciclofosfamida în doze mici este inferioară dozelor mari","ciclofosfamida poate fi inferioară MMF la afro-americani și hispanici","ciclofosfamida orală este superioară MMF indiferent de etnie","se aplică identic clasei I, cu plasmafereză"],"AC",1367,"Glomerulul și afectarea glomerulară — Nefrita lupică: inducție și etnie",
 "Nuanțarea inducției (CYC vs MMF) după etnie, cu alternativa dozelor mici la albi.",
 ["Inducția folosește steroizi cu ciclofosfamidă i.v. în doze mari sau micofenolat de mofetil.","Nu: la populația albă, ciclofosfamida în doze mici are eficacitate similară dozelor mari, cu toxicitate mai redusă.","Ciclofosfamida poate fi inferioară MMF la populațiile afro-americană și hispanică.","Nu: textul nu dă ciclofosfamidei superioritate față de MMF; la afro-americani și hispanici poate fi chiar inferioară.","Nu: clasa I nu necesită tratament specific."]],
 [8,"Etnia (alb vs afro-american/hispanic) permută CYC și MMF; distractorul tratează clasa I ca GNRP."],["populaţia albă","a/ro-americană"]),

q("nefrologie-adv-124",["Menținerea remisiunii în nefrita lupică și rituximabul:",
 ["azatioprina este superioară MMF în terapia de menținere","azatioprina și ciclosporina previn similar recidiva","trialurile randomizate cu rituximab nu au fost consistente","rituximabul poate fi util în formele refractare severe","rituximabul înlocuiește inducția standard în clasa I"],"BCD",1367,"Glomerulul și afectarea glomerulară — Nefrita lupică: menținere și rituximab",
 "Ierarhizarea MMF > AZA ≈ ciclosporină la menținere și rezervarea rituximabului pentru formele refractare.",
 ["Nu: MMF este superior azatioprinei în terapia de menținere.","Azatioprina are eficacitate similară ciclosporinei în reducerea riscului de recidivă.","Rituximabul a dat rezultate favorabile pe termen scurt la unii pacienți, dar trialurile randomizate nu au fost consistente.","Rituximabul poate fi util în nefritele lupice refractare severe.","Nu: clasa I nu se induce cu rituximab; acesta este rezervat formelor refractare severe."]],
 [8,"Capcana este „overtreatment” al clasei I și inversarea MMF versus azatioprină."],["superior azatioprinei","nefritele lu pice refractare"]),

q("nefrologie-adv-125",["Crioglobulinemiile, după tipul imunoglobulinei:",
 ["tipul I: o singură imunoglobulină monoclonală, ca în mielom","tipul II: IgM monoclonală tip factor reumatoid, adesea cu VHC","tipul III: cea mai frecventă afectare glomerulară dintre tipuri","tipul III: antiglobuline IgM monoclonale, ca în mielom","sunt vasculite pauci-imune, cu ANCA-PR3 pozitivi"],"AB",1367,"Glomerulul și afectarea glomerulară — Crioglobuline: tipurile I–III",
 "Maparea tip I monoclonal / tip II IgM-RF+VHC și a predilecției glomerulare pentru tipul II.",
 ["Tipul I constă în crioprecipitarea unui singur tip de imunoglobulină monoclonală, în mielom și alte boli limfoproliferative.","Tipul II are antiglobuline IgM monoclonale cu activitate de factor reumatoid, adesea asociate VHC.","Nu: afectarea glomerulară este mai frecventă în tipul II; tipul II reprezintă 40–60%, iar tipul III 40–50% din cazurile de crioglobulinemie.","Nu: tipul III are antiglobuline IgM policlonale, nu monoclonale ca în mielom.","Nu: crioglobulinemiile nu sunt vasculite ANCA pauci-imune."]],
 [8,"Cotele 40–60%/40–50% și monoclonal versus policlonal sunt ușor de permutat cu mielomul sau ANCA."],["40-60%","factor reumatoid"]),

q("nefrologie-adv-126",["Boala renală crioglobulinemică:",
 ["afectează predominant bărbații, în decada a patra sau a cincea","se asociază cu purpură, artralgii, Raynaud și hepatopatie","antiviralele directe sunt foarte eficiente când cauza este VHC","plasmafereza sau criofiltrarea, în vasculita cu risc vital","devine clinic manifestă tipic în adolescență"],"BCD",1367,"Glomerulul și afectarea glomerulară — Crioglobulinemia: clinic și DAA",
 "Corelarea vârstei/sexului (decada 4–5, predominant femei), a purpurei și a DAA/plasmaferezei.",
 ["Nu: boala devine clinic manifestă în decada a patra sau a cincea, femeile fiind mai frecvent afectate.","Caracteristicile sistemice includ purpura, artralgiile, ulcerele de picior, Raynaud, polineuropatia și afectarea hepatică.","Antiviralele cu acțiune directă sunt extrem de eficiente când cauza este VHC.","Plasmafereza intensivă sau criofiltrarea au fost folosite în vasculita cu risc vital.","Nu: boala devine clinic manifestă în decada a patra sau a cincea, nu în adolescență."]],
 [8,"Plasmafereza de urgență este ușor de înlocuit cu nefrectomia din xantogranulomatoasă; DAA sunt detaliul etiologic."],["a patra sau a cincea","criofiltra"]),

q("nefrologie-adv-127",["Vasculita cu IgA (purpura Henoch–Schönlein):",
 ["erupție, colici abdominale, artralgii și glomerulonefrită","hematurie și/sau proteinurie la circa 30–70% dintre pacienți","GN proliferativă focală, cu depozite mezangiale de IgA","corticosteroizii au eficiență dovedită asupra nefritei","este o formă de PAN, cu anevrisme de artere medii"],"ABC",1367,"Glomerulul și afectarea glomerulară — Purpura Henoch–Schönlein",
 "Recunoașterea tetradei clinice, a cotei 30–70% și a caracterului suportiv (steroizi ineficienți).",
 ["Sindromul cuprinde erupția cutanată caracteristică, colici abdominale, dureri articulare și glomerulonefrită.","Aproximativ 30–70% dintre pacienți au hematurie și/sau proteinurie.","Leziunea este o GN proliferativă focală segmentară, cu hipercelularitate mezangială și depozite predominant de IgA mezangiale.","Nu: nu există tratament cu eficiență dovedită; steroizii sunt ineficienți, îngrijirea fiind de obicei suportivă.","Nu: vasculita cu IgA nu este o PAN ANCA-pozitivă cu anevrisme de artere medii."]],
 [8,"Ineficiența steroizilor este contraintuitivă într-o vasculită IgA; distractorul mută PAN/nefrectomia."],["30-70%","cu steroizi"]),

q("nefrologie-adv-128",["Un bărbat tânăr este investigat pentru boala Fabry. Aceasta:",
 ["este legată de X, prin deficit de α-galactozidază","acumulează globotriaozilceramide în podocite","asociază angiokeratoame, neuropatie și afectare cardiovasculară","se tratează cu agalsidază sau, selectiv, cu migalastat oral","se transmite autozomal recesiv, prin mutații PKHD1"],"ABCD",1367,"Glomerulul și afectarea glomerulară — Boala Fabry: agalsidază și migalastat",
 "Legarea deficitului de α-galactozidază de angiokeratoame și de cele două linii (agalsidază, migalastat).",
 ["Boala Fabry este o boală de stocare lizozomală legată de X, prin deficit de α-galactozidază.","În podocite se acumulează glicosfingolipide (globotriaozilceramide).","Tabloul include angiokeratoame, afectare cardiovasculară, neuropatii și BCR cu proteinurie progresivă.","Agalsidaza încetinește progresia leziunilor cardiace, renale și cutanate; migalastatul oral poate fi eficient în cazuri selectate.","Nu: PKHD1 aparține bolii polichistice autozomal recesive; boala Fabry este legată de X."]],
 [8,"Vigneta cutanată împinge spre vasculită; chaperona orală migalastat este detaliul ușor de omis."],["agalsidază","miga"]),

q("nefrologie-adv-129",["Nefropatia din anemia falciformă:",
 ["se complică frecvent cu scleroză sau necroză papilară","poate asocia diabet insipid de origine centrală","poate asocia acidoză tubulară renală incompletă","poate include ocazional GN membranoasă sau mezangiocapilară cu IgG","are ca leziune dominantă boala anti-MBG, cu semilune"],"ACD",1367,"Implicarea rinichiului în alte afecțiuni — Siclemia: papilă, DIN și ATR",
 "Completarea necrozei papilare, a diabetului insipid nefrogen și a ATR incomplete, plus GN membranoasă/MCGN ocazională.",
 ["Scleroza sau necroza papilară sunt complicații frecvente ale nefropatiei falciforme.","Nu: anemia falciformă poate asocia diabet insipid nefrogen, nu central.","Acidoza tubulară renală incompletă figurează printre complicațiile tubulare.","Ocazional poate apărea GN membranoasă sau mezangiocapilară cu depozite de IgG, fără infecție prealabilă.","Nu: leziunea glomerulară a siclemiei nu este o boală anti-MBG."]],
 [8,"Triada papilă–DIN–ATR este ușor de înlocuit cu un pattern glomerular anti-MBG."],["diabet insipid nefrogen","acidoză tubulară"]),

q("nefrologie-adv-130",["Sclerodermia sistemică și criza renală sclerodermică:",
 ["arterele arcuate și interlobulare au aspect „în foițe de ceapă”","inhibitorii ECA sunt contraindicați în această criză","mortalitatea prin insuficiență renală a devenit rară","CXCL4 se asociază cu fibroza cutanată și pulmonară","este o glomerulonefrită rapid progresivă ANCA-pozitivă"],"ACD",1368,"Implicarea rinichiului în alte afecțiuni — SSc: foițe de ceapă și IECA",
 "Recunoașterea histologiei „foițe de ceapă”, a elecției IECA și a mortalității renale devenite rare.",
 ["La biopsie, arterele arcuate și interlobulare au aspect „în foițe de ceapă” prin proliferare intimală, cu trombi de fibrină și necroză fibrinoidă.","Nu: inhibitorii ECA sunt tratamentul de elecție și au ameliorat semnificativ prognosticul.","Mortalitatea prin insuficiență renală este azi rară, deși sub 30% dintre pacienți progresează spre BRT.","CXCL4, produs de celulele dendritice plasmocitoide, se asociază cu fibroza tegumentară și pulmonară și cu hipertensiunea pulmonară.","Nu: criza renală sclerodermică nu este o vasculită ANCA-pozitivă, iar IECA nu sunt contraindicați."]],
 [8,"IECA ca elecție este contraintuitiv față de o „criză hipertensivă”; distractorul o tratează ca GPA."],["foiţe de ceapă","sub 30%"]),

q("nefrologie-adv-131",["Un copil dezvoltă oligurie la o săptămână după o gastroenterită. În SHU:",
 ["apar hemoliză cu fragmentocite, trombocitopenie și IRA","testele de coagulare sunt alterate, ca în CID","E. coli O157 produce verotoxina (toxina Shiga)","subunitatea A a verotoxinei inhibă sinteza proteică","leziunea este o vasculită ANCA-PR3 pozitivă"],"ACD",1368,"Implicarea rinichiului în alte afecțiuni — SHU+D: O157 și verotoxină",
 "Deosebirea SHU (coagulare normală, O157/verotoxină) de CID și de vasculita ANCA.",
 ["SHU asociază hemoliză intravasculară cu fragmentări eritrocitare, trombocitopenie și IRA prin tromboze de artere mici și arteriole.","Nu: testele de coagulare sunt de regulă normale în SHU, spre deosebire de CID.","SHU+D urmează adesea gastroenteritei cu E. coli O157, care produce verotoxină (toxină Shiga).","Subunitatea A a verotoxinei inhibă sinteza proteică.","Nu: SHU nu este o vasculită ANCA și nu are coagulare consumptivă de tip CID."]],
 [8,"Vigneta post-diarreee cere O157/verotoxină; distractorul o mută pe ANCA sau CID."],["tulpina 0157","verotoxina"]),

q("nefrologie-adv-132",["Tuberculoza tractului urinar:",
 ["leziunile corticale apar prin diseminare ascendentă din vezică","poate duce la stricturi ureterale și vezică contractată","trebuie luată în calcul la pacientul cu piurie sterilă","are un tratament similar tuberculozei pulmonare","are imagistică patognomonică în forma interstițială difuză"],"BCD",1385,"Nefritele tubulointerstițiale — Tuberculoza urinară: vezică contractată și piurie sterilă",
 "Completarea căii hematogene–papilă–vezică contractată, a piuriei sterile și a diagnosticului bioptic în forma interstițială difuză.",
 ["Nu: leziunile corticale urmează diseminării hematogene din faza primară a infecției.","Infecția persistentă diseminează papilar, cu cavități și eliminare de micobacterii; pot urma stricturi ureterale și vezică contractată.","Diagnosticul trebuie luat în calcul la piuria sterilă.","Tratamentul este similar celui din tuberculoza pulmonară.","Nu: în TB interstițială difuză imagistica poate fi normală, diagnosticul fiind bioptic."]],
 [8,"Vezica contractată și slaba valoare a uroculturilor matinale sunt detalii ușor de înlocuit cu „imagistică patognomonică”."],["piurie sterilă","vezici contractate"]),

q("nefrologie-adv-133",["Abcesul renal hematogen stafilococic:",
 ["are adesea urină normală, necomunicând cu bazinetul","se tratează cu flucloxacilină și drenaj chirurgical","se tratează oral, 3 zile, ca o cistită","impune nefrectomie, ca pielonefrita xantogranulomatoasă","se diagnostichează prin renogramă MAG3, nu prin eco sau CT"],"AB",1385,"Nefritele tubulointerstițiale — Abcesul stafilococic: flucloxacilină",
 "Reținerea urinei „normale” (necomunicant) și a perechii flucloxacilină plus drenaj.",
 ["Abcesul nu comunică cu bazinetul, astfel că urina poate fi fără anomalii; extensia perirenală este frecventă.","Tratamentul constă în flucloxacilină și drenaj chirurgical.","Nu: abcesul necesită flucloxacilină și drenaj chirurgical, nu o cură orală scurtă ca în cistită.","Nu: nefrectomia de elecție aparține pielonefritei xantogranulomatoase, nu abcesului stafilococic.","Nu: diagnosticul se pune prin ecografie sau CT; septicemia stafilococică este de regulă prezentă."]],
 [8,"Flucloxacilina plus drenaj este ușor de înlocuit cu nefrectomia xantogranulomatoasei sau cu o cură scurtă de cistită."],["flucloxacilina","drenaj chirurgical"]),

q("nefrologie-adv-134",["Necroza papilară și nefropatia de reflux:",
 ["necroza papilară este de regulă unilaterală, cu pierdere corticală","nefropatia de reflux poate fi unilaterală, cu calice boante polare","cauzele necrozei papilare: analgezice, diabet, siclemie","leziunile tubilor medulari produc pierdere urinară de sodiu","semnul inelului caracterizează nefropatia de reflux"],"BCD",1386,"Nefritele tubulointerstițiale — Papila versus reflux: semnul inelului",
 "Contrastul bilateral/inel/fără pierdere corticală (papilă) versus unilateral/calice boante polare (reflux).",
 ["Nu: necroza papilară este bilaterală și arată semnul inelului, fără pierdere de țesut cortical.","Nefropatia de reflux poate fi unilaterală, cu calice boante, cel mai adesea la polii renali.","Consumul cronic de analgezice, diabetul zaharat și siclemia sunt cauze citate de necroză papilară.","Leziunile tubilor medulari duc la defect de concentrare și pierdere urinară de sodiu.","Nu: semnul inelului aparține necrozei papilare (papila necrozată), nu nefropatiei de reflux."]],
 [8,"Semnul inelului versus calicele boante sunt concepute să fie permute între papilă și reflux."],["Semnul inelului","Calice boante"]),

q("nefrologie-adv-135",["Cauzele de NTI cronică din Cadranul 36.28:",
 ["sunt dominate de peniciline, ca forma acută","au ca agent principal un hantavirus","exclud iradierea, rezervată glomerulopatiilor","includ ciclosporina, 5-aminosalicilații și cadmiul","cuprind cadmiul și plumbul ca factori nefroprotectori"],"D",1386,"Nefritele tubulointerstițiale — Cadranul 36.28: metale și 5-ASA",
 "Recunoașterea listei ciclosporină/5-ASA/cadmiu/plumb/iradiere, distinctă de NTI acută medicamentoasă.",
 ["Nu: penicilinele sunt cauze de NTI acută, nu domină lista de NTI cronică.","Nu: hantavirusul este o cauză infecțioasă de NTI acută, nu agentul principal al formei cronice.","Nu: iradierea figurează printre cauzele de NTI cronică din Cadranul 36.28.","Lista de medicamente și toxice din Cadranul 36.28 include ciclosporina, 5-aminosalicilații, cadmiul, plumbul, titanul și iradierea.","Nu: cadmiul și plumbul sunt nefrotoxice, nu nefroprotectoare."]],
 [8,"Metalele (cadmiu, plumb, titan) sunt detalii nefolosite, ușor de înlocuit cu penicilinele NTI acute."],["Cadmiu, plumb","5-aminosalicilati"]),

q("nefrologie-adv-136",["În NTI cronice, leziunile tubilor medulari determină:",
 ["defecte ale capacității de concentrare a urinii","pierdere urinară de sodiu, cu poliurie","extinderea ulterioară a fibrozei spre corticală","hiperconcentrare maximală a urinii, cu oligurie","vindecare spontană, fără progresie spre BCR"],"ABC",1386,"Nefritele tubulointerstițiale — NTI cronică: concentrare și natriureză",
 "Legarea leziunii medulare de defectul de concentrare/natriureză și de fibroza corticală tardivă.",
 ["Leziunile tubilor medulari produc defecte în capacitatea de concentrare a urinii.","Conservarea defectuoasă a sodiului duce la poliurie și pierdere urinară de sodiu.","Fibroza se extinde ulterior la corticală, cu progresia BCR.","Nu: apare defect de concentrare cu poliurie și pierdere de sodiu, nu hiperconcentrare cu oligurie.","Nu: fibroza se extinde ulterior la corticală, cu progresia BCR."]],
 [8,"Inversează natriureza medulară (pierdere de sare) cu retenția din SHU."],["capacitatea de concentrare","pierdere urinară de sodiu"]),

q("nefrologie-adv-137",["Insuficiența renală acută se definește ca:",
 ["o deteriorare lentă a funcției renale, peste 3 luni","o deteriorare bruscă, în ore–zile, de regulă reversibilă","o leziune care impune biopsie înaintea evaluării pre-/post-renale","o creștere a ureei, marker fidel al RFG","o pierdere ireversibilă a funcției, ca în stadiul G5"],"B",1387,"Insuficiența renală acută — Definiție: ore–zile, reversibilitate",
 "Fixarea ferestrei ore–zile și a reversibilității uzuale în zile–săptămâni, distinctă de pragul >3 luni al BCR.",
 ["Nu: deteriorarea peste 3 luni definește BCR, nu IRA.","IRA este o deteriorare bruscă a funcției renale, de obicei în ore sau zile, de regulă reversibilă în zile–săptămâni.","Nu: clasificarea pre-renală, reno-parenchimatoasă și post-renală precede biopsia.","Nu: ureea și creatinina sunt uneori predictori suboptimali ai funcției renale (Cadranul 36.29).","Nu: IRA este de regulă reversibilă în zile–săptămâni, spre deosebire de stadiul G5."]],
 [8,"Fereastra ore–zile versus >3 luni (BCR) este capcana de stadializare a aceleiași pagini de tranziție."],["ore sau zile","zile-săptămâni"]),

q("nefrologie-adv-138",["Clasificarea IRA după sediul leziunii:",
 ["pre-renală, prin perfuzie deficitară, cu scăderea RFG","reno-parenchimatoasă: glomerulară, tubulară sau vasculară","post-renală: obstrucție cu presiune retrogradă","pre-renală, prin obstrucția căilor urinare","o formă de BCR stadiul G2, fără componentă obstructivă"],"ABC",1387,"Insuficiența renală acută — Clasificarea pre-/intra-/post-renală",
 "Aplicarea triadei perfuzie–parenchim–obstrucție, cu presiunea retrogradă ca mecanism post-renal.",
 ["IRA pre-renală apare prin perfuzie renală deficitară, care reduce RFG.","IRA reno-parenchimatoasă se datorează leziunilor glomerulare, tubulare sau vasculare.","În IRA post-renală rinichii sunt funcționali, dar nu pot excreta, iar presiunea retrogradă afectează funcția renală.","Nu: obstrucția definește IRA post-renală; cea pre-renală se datorează perfuziei deficitare.","Nu: IRA nu este echivalentul stadiului G2 al BCR, iar clasificarea ei include cauzele obstructive."]],
 [8,"Presiunea retrogradă post-renală este detaliul mecanic ușor de omis în favoarea unui „doar glomerular”."],["pre-renale","post-renale"]),

q("nefrologie-adv-139",["În IR inexplicabilă cu rinichi de mărime normală, biopsia exclude:",
 ["forme tratabile de nefrită tubulointerstițială","nefropatia urică cronică, tratată de rutină cu rasburicază","sarcoidoza renală, cu răspuns rapid la corticosteroizi","boala anti-MBG, ca formă de NTI granulomatoasă","obstrucția post-renală, în locul ecografiei"],"AC",1387,"Nefritele tubulointerstițiale — Biopsia rinichiului „normal” și sarcoidoza",
 "Indicarea biopsiei pentru NTI granulomatoasă tratabilă (sarcoid) când rinichii sunt încă normali dimensional.",
 ["Biopsia se indică tocmai pentru a exclude formele tratabile de NTI la rinichi de dimensiuni normale.","Nu: nefropatia hiperuricemică cronică este o entitate controversată, fără indicație de rasburicază de rutină.","NTI granulomatoasă din sarcoidoza renală poate fi prima manifestare a bolii, iar corticosteroizii dau răspuns rapid în majoritatea cazurilor.","Nu: boala anti-MBG este o glomerulopatie, nu o formă de NTI.","Nu: obstrucția se evaluează imagistic, nu prin biopsie de primă intenție."]],
 [8,"Rinichiul de dimensiuni normale într-o IRA „inexplicabilă” cere sarcoid granulomatos, nu Goodpasture."],["rinichi de dimensiuni normale","sarcoidoza renală"]),

q("nefrologie-adv-140",["Sindromul de liză tumorală:",
 ["eliberează acid uric, potasiu și fosfor după liza rapidă","uratul seric poate crește de 4–5 ori, cu uropatie cristalină","are ca risc major hiperpotasemia, limitată prin hidratare","rasburicaza scade uratul prin inhibarea xantin-oxidazei","rasburicaza nu modifică nivelul uratului seric"],"ABC",1392,"Boala cronică de rinichi — Liză tumorală: alantoină și hiper-K+",
 "Ierarhizarea hiper-K+ ca risc major și a rasburicazei care face uratul nedetectabil via alantoină.",
 ["Liza tumorală rapidă, inclusiv sub corticosteroizi, eliberează acid uric, potasiu și fosfor.","Acidul uric seric poate atinge de 4–5 ori valoarea normală, cu uropatie prin cristale.","Riscul major este hiperpotasemia; hidratarea profilactică menține diureza pentru eliminarea potasiului.","Nu: rasburicaza oxidează acidul uric la alantoină, nu inhibă xantin-oxidaza.","Nu: rasburicaza oxidează acidul uric la alantoină, iar nivelurile pot deveni nedetectabile."]],
 [8,"Alantoina și uratul nedetectabil sunt detalii de enzimologie ușor de înlocuit cu „hipo-K+ benign”."],["alantoina","4-5 ori"]),

q("nefrologie-adv-141",["Sindromul hepato-renal:",
 ["presupune vasoconstricție renală, cu rinichi histologic normali","apare în boli hepatice cu hipertensiune portală și ascită","funcția renală nu se recuperează nici după un transplant hepatic reușit","este o necroză tubulară acută hipovolemică","se tratează inițial cu spironolactonă în doze crescânde"],"AB",1392,"Boala cronică de rinichi — HRS: vasoconstricție și transplant hepatic",
 "Recunoașterea caracterului funcțional (vasoconstricție, histologie normală, euvolemie) și a recuperării după transplant hepatic.",
 ["SHR presupune vasoconstricție renală importantă, rinichii fiind histologic normali.","SHR apare în bolile hepatice complicate cu hipertensiune portală și ascită.","Nu: rinichii sunt histologic normali, iar recuperarea renală este observată de obicei după un transplant hepatic reușit.","Nu: pacienții nu sunt hipovolemici, iar rinichii sunt histologic normali, fără necroză tubulară.","Nu: diureticele excesive pot precipita SHR; soluția este transplantul hepatic."]],
 [8,"Euvolemia (nu hipovolemia) și recuperarea după grefă hepatică deosebesc HRS de NTA."],["vasconstricţia renală","transplant hepatic"]),

q("nefrologie-adv-142",["Prevenția IRA de contrast la pacienții cu risc, cateterizați cardiac:",
 ["dializa profilactică, standard care înlocuiește hidratarea","N-acetilcisteina, care înlocuiește protocolul de lichide","lichide ghidate de presiunea telediastolică","dopamina în doză „renală”, superioară hidratării","teofilina, asociată de rutină bicarbonatului"],"C",1392,"Boala cronică de rinichi — Contrast: lichide ghidate de telediastolică",
 "Recunoașterea protocolului ghidat de presiunea telediastolică ca superior hidratării oarbe la cateterizarea cu risc.",
 ["Nu: dializa profilactică nu este benefică în prevenția IRA de contrast.","Nu: N-acetilcisteina are cel mult un beneficiu marginal și nu înlocuiește lichidele.","Un trial arată că administrarea de lichide ghidată de presiunea telediastolică este sigură și mai eficientă în prevenția IRA post-contrast.","Nu: dopamina în doze „renale” nu este benefică.","Nu: teofilina nu este benefică și nu se asociază de rutină bicarbonatului."]],
 [8,"Telediastolica ca ghid de lichide este detaliul de terapie intensivă nefolosit al paginii de contrast."],["telediastolică","cateterizaţi cardiac"]),

q("nefrologie-adv-143",["Prevalența BCR pe grupe de vârstă (Cadranul 36.36):",
 ["stadiul 3: 1,4% sub 65 de ani și 30,9% la ≥85 de ani","stadiile 3–5: 33,4% la ≥85 de ani, față de 1,5% sub 65","stadiul 5 depășește 30% la pacienții sub 65 de ani","stadiul 3 scade după 75 de ani, fiind maxim la tineri","stadiul 4 are o prevalență de circa 30% la vârstnici"],"AB",1393,"Boala cronică de rinichi — Cadranul 36.36: stadiul 3 după vârstă",
 "Memorarea saltului de prevalență a stadiului 3 de la 1,4% (<65) la ~31% (≥85).",
 ["Cadranul 36.36: stadiul 3 crește de la 1,4% sub 65 de ani la 15,4% (65–74), 29,4% (75–84) și 30,9% la ≥85 de ani.","Totalul stadiilor 3–5 ajunge la 33,4% la ≥85 de ani, față de 1,5% sub 65 de ani.","Nu: stadiul 5 rămâne rar (0,03–0,2%); stadiul 3 domină la vârstnici.","Nu: prevalența stadiului 3 crește cu vârsta, până la 30,9% la ≥85 de ani.","Nu: stadiul 4 are o prevalență de ordinul 0,04–2,4%, nu 30%."]],
 [8,"Permutează 1,4% și 30,9% între tineri și foarte vârstnici, capcana de ordin de mărime a cadranului."],["1,4","30,9"]),

q("nefrologie-adv-144",["Progresia BCR, independent de cauză:",
 ["din circa un milion de nefroni, cei rămași preiau filtrarea","nefronii rămași hiperfiltrează și se hipertrofiază","angiotensina II dilată arteriolele postglomerulare","prognosticul se corelează cu leziunea interstițială","este mai rapidă în NTI cronice decât în glomerulopatii"],"ABD",1393,"Boala cronică de rinichi — Hiperfiltrare, Ang II, TGF-β și PAI-1",
 "Legarea milionului de nefroni de hiperfiltrare, de vasoconstricția postglomerulară și de markerii de prognostic (interstițiu > glomerul).",
 ["Fiecare rinichi are aproximativ un milion de nefroni; pe măsură ce se pierd, sarcina de filtrare se răsfrânge asupra celor rămași.","Nefronii rămași sunt supuși hiperfiltrării, cu hipertrofie glomerulară și reducerea rezistenței arteriolare.","Nu: angiotensina II vasoconstrictează arteriolele postglomerulare și stimulează TGF-β și PAI-1.","Prognosticul se corelează cu HTA, proteinuria și leziunea interstițială, nu cu modificările glomerulare.","Nu: glomerulopatiile cronice se deteriorează mai rapid decât nefropatiile tubulointerstițiale cronice."]],
 [8,"Direcția Ang II (eferentă) și ierarhia interstițiu versus glomerul sunt capcanele de progresie."],["un million de nefroni","PAl-1"]),

q("nefrologie-adv-145",["Prognosticul BCR se corelează cu:",
 ["hipertensiunea arterială, mai ales slab controlată","nivelul proteinuriei","gradul de lezare histologică a interstițiului","tipul bolii: glomerulopatiile progresează mai rapid","modificările glomerulare obiectivate histologic"],"ABCD",1393,"Boala cronică de rinichi — Predictori: interstițiu, nu glomerul",
 "Ierarhizarea HTA–proteinurie–interstițiu față de histologia glomerulară, plus viteza mai mare a glomerulopatiilor.",
 ["HTA, mai ales slab controlată, se corelează cu prognosticul BCR, indiferent de cauză.","Proteinuria figurează explicit printre predictorii prognosticului BCR.","Prognosticul se corelează cu gradul de lezare histologică a interstițiului, nu cu modificările glomerulare.","Glomerulopatiile cronice tind să se deterioreze mai rapid decât nefropatiile tubulointerstițiale cronice.","Nu: prognosticul nu se corelează cu modificările obiectivate în glomeruli, ci cu leziunea interstițială."]],
 [8,"Afirmația „interstițiul, nu glomerulul” este contraintuitivă într-un capitol de boli glomerulare."],["lezare histologică a interstiţiului","glomerulopatii cronice"]),

q("nefrologie-adv-146",["Anemia normocromă, normocitară din BCR:",
 ["este agravată de pierderi oculte digestive și pe hemodializă","poate reflecta toxine uremice sau fibroza medulară din HPT","asociază deficite de fier, B12, folat și hematii cu viață scurtă","este ameliorată de IECA, care stimulează eritropoietina","are ca mecanism principal deficitul de fier, nu de EPO"],"ABC",1394,"Boala cronică de rinichi — Anemia: mecanisme dincolo de EPO",
 "Completarea mecanismului principal (EPO) cu pierderi, fibroză HPT, deficite hematinice și interferența IECA.",
 ["Pierderile oculte digestive, prelevările repetate și pierderile pe hemodializă contribuie la anemie.","Măduva este afectată de toxinele uremice sau de fibroza din hiperparatiroidism.","Contribuie deficitele de fier, B12 sau folat și durata de viață scăzută a hematiilor în mediul uremic.","Nu: IECA pot contribui la anemie, interferând cu eliberarea endogenă de eritropoietină.","Nu: mecanismul principal este deficitul de eritropoietină; deficitul de fier este unul dintre factorii adiționali."]],
 [8,"Interferența IECA cu EPO endogen este detaliul farmacologic ușor de inversat."],["Inhibitorii enzimei de conversie","viaţă scăzută"]),

q("nefrologie-adv-147",["Tratamentul anemiei din BCR cu ASE:",
 ["crește rezistența periferică, prin creșterea vâscozității","poate produce rar encefalopatie și orbire corticală tranzitorie","fierul i.v. în doze mari (feritină ~400 µg/L) reduce necesarul de ASE","un agonist peptidic sintetic a fost retras pentru anafilaxie","reduce rezistența periferică și vâscozitatea sângelui"],"ABCD",1394,"Boala cronică de rinichi — ASE: vâscozitate, feritină 400 și anafilaxie",
 "Legarea creșterii rezistenței periferice de ținta de feritină ~400 µg/L și de retragerea peptidului anafilactic.",
 ["Rezistența periferică crește la toți pacienții, prin pierderea vasodilatației hipoxice și prin creșterea vâscozității.","Complicațiile rare includ encefalopatia și orbirea corticală tranzitorie.","Un trial a arătat că fierul i.v. în doze mari, cu feritină țintă în jur de 400 µg/L, este sigur și scade necesarul de ASE.","Peptidul sintetic agonist al receptorului EPO a fost retras din cauza reacțiilor anafilactice.","Nu: sub ASE, rezistența periferică și vâscozitatea cresc, nu scad."]],
 [8,"Feritina 400 µg/L (trial de fier i.v.) este ușor de confudat cu pragul >500 al deficitului funcțional."],["400 µg/L","orbirea corticală"]),

q("nefrologie-adv-148",["Tulburarea mineral-osoasă din BCR (TMO-BCR):",
 ["eroziuni subperiostale și craniu „în piperniță” în HPT secundar","coloană „în tricou de rugby” prin osteoscleroză","HPT terțiar: secreție autonomă de PTH, cu hipocalcemie","osul adinamic: turnover scăzut, FA normală, PTH scăzut","craniul „în piperniță”, semn de osteomalacie"],"ABD",1395,"Boala cronică de rinichi — TMO-BCR: pepperpot, rugger jersey, adinamică",
 "Maparea celor două semne radiologice și deosebirea HPT terțiar (hipercalcemie) de osul adinamic.",
 ["În hiperparatiroidismul secundar apar eroziuni subperiostale la degete și craniu „în piperniță” (pepperpot).","Osteoscleroza vertebrală din HPT persistent dă aspectul de „tricou de rugby” (rugger jersey).","Nu: în HPT terțiar, PTH devine independent de calciu și de 1,25-(OH)2D3, cu hipercalcemie.","Boala osoasă adinamică are turnover scăzut, FA normală și PTH scăzut; niciun tratament nu s-a dovedit eficient.","Nu: craniul „în piperniță” aparține hiperparatiroidismului, nu osteomalaciei."]],
 [8,"Permutează pepperpot, rugger jersey și osul adinamic, trei imagini din aceeași figură."],["pepperpot","tricou de rugby"]),

q("nefrologie-adv-149",["La pacientul dializat, ținta PTH care evită boala osoasă adinamică este:",
 ["sub limita inferioară a normalului","de 2–3 ori limita superioară a normalului","de 10 ori limita superioară a normalului","identică intervalului populației generale","nedetectabilă, prin analogi de vitamină D"],"B",1395,"Boala cronică de rinichi — Ținta PTH 2–3× ULN la dializat",
 "Reținerea ferestrei 2–3× ULN, aleasă tocmai pentru a păstra un turnover care evită osul adinamic.",
 ["Nu: PTH subnormal definește riscul de os adinamic, nu ținta.","La dializați, PTH se menține la de 2–3 ori limita superioară a normalului, pentru a evita boala osoasă adinamică.","Nu: ținta este de 2–3 ori limita superioară, nu de zece ori.","Nu: la dializat, ținta este de 2–3 ori limita superioară, nu intervalul populației generale.","Nu: PTH nedetectabil este nedorit; ținta este de 2–3 ori limita superioară."]],
 [8,"Fereastra 2–3× ULN este ușor de confundat cu „normalizarea completă” care produce os adinamic."],["2-3 ori","boala osoasă adinamică"]),

q("nefrologie-adv-150",["Arteriolopatia calcificantă uremică (calcifilaxia):",
 ["produce plăgi dureroase, ulcere și necroză dermică","asociază calcificări vasculare și tromboze de vase mici","a fost tratată cu tiosulfat de sodiu, cu succes variabil","are mortalitate scăzută în primul an de la diagnostic","este prevenită de warfarină, care activează proteina matrix Gla"],"ABC",1396,"Boala cronică de rinichi — Calcifilaxia: tiosulfat și mortalitate la 1 an",
 "Recunoașterea tabloului cutanat necrotic, a tiosulfatului și a mortalității înalte în primul an.",
 ["Calcifilaxia se manifestă prin pete dureroase, plăgi sau ulcere, escare care nu se vindecă, paniculită și necroză dermică.","Histologic, calcificările vasculare se suprapun cu tromboze de vase mici.","Tiosulfatul de sodiu (antioxidant) și bifosfonații au fost încercați cu succes variabil.","Nu: mulți pacienți decedează în decurs de un an de la diagnostic, infecțiile crescând riscul.","Nu: warfarina inhibă carboxilarea proteinei matrix Gla și favorizează calcificarea."]],
 [8,"Mortalitatea în primul an și tiosulfatul sunt ușor de înlocuit cu un rol „protector” al warfarinei."],["Tiosulfatul de sodiu","an de la data"]),

q("nefrologie-adv-151",["Riscul cardiovascular „non-tradițional” al pacientului uremic:",
 ["ADMA explică parțial un risc de deces crescut cu 52%","inflamația crește fetuina, inhibitor al calcificărilor","vitamina E sau acetilcisteina s-au asociat cu mortalitate redusă","include hiperhomocisteinemia, malnutriția și Chlamydophila","acidul folic asociat cu B6 și B12 reduce mortalitatea"],"ACD",1396,"Boala cronică de rinichi — ADMA 52%/34% și fetuina",
 "Legarea ADMA de riscul crescut și a inflamației de inhibiția fetuinei, cu contrastul vitamina E versus vitaminele B.",
 ["ADMA (dimetilarginina asimetrică) explică în parte un risc de deces crescut cu 52% și de evenimente CV cu 34%.","Nu: inflamația inhibă fetuina, un inhibitor hepatic al calcificărilor vasculare.","Antioxidanții (vitamina E sau acetilcisteina) s-au asociat cu reducerea mortalității de orice cauză și CV.","Lista non-tradițională include hiperhomocisteinemia, malnutriția, stresul oxidativ și Chlamydophila pneumoniae.","Nu: acidul folic cu vitaminele B6/B12 s-a dovedit ineficient."]],
 [8,"Cotele ADMA 52%/34% sunt permutabile cu SHARP; distractorul inversează rezultatul vitaminelor B."],["52%","fetuina"]),

q("nefrologie-adv-152",["Complicațiile extrarenale ale BCR:",
 ["pericardita uremică, cu revărsat adesea hemoragic","pericardita uremică, în care anticoagularea previne tamponada","porfiria cutanată tardivă, prin retenția porfirinelor","amilaze crescute până la de 3 ori, fără boală pancreatică","pericardita uremică, de natură virală banală"],"ACD",1397,"Boala cronică de rinichi — Pericardită hemoragică, PCT și amilază ×3",
 "Deosebirea revărsatului hemoragic uremic (anticoagulare prudentă) de pancreatita „biochimică” și recunoașterea PCT.",
 ["Pericardita uremică însoțește uremia severă sau dializa ineficientă; revărsatul este adesea hemoragic, cu aritmii atriale.","Nu: anticoagulantele se folosesc cu prudență, din cauza riscului de tamponadă; pericardita poate remite cu dializă intensivă.","Porfiria cutanată tardivă din BCR ține de sinteza hepatică scăzută a uroporfirinogen-decarboxilazei și de retenția porfirinelor.","Amilazele serice pot crește până la de trei ori normalul fără boală pancreatică, prin retenția izoenzimei de masă mare.","Nu: pericardita uremică nu este o pericardită virală banală; însoțește uremia severă sau dializa ineficientă."]],
 [8,"Amilaza ×3 „fără pancreatită” și PCT prin decarboxilază sunt detalii ușor de citit ca urgențe chirurgicale."],["uroporfinogen","trei ori limita"]),

q("nefrologie-adv-153",["Anomaliile metabolice și endocrine din BCR:",
 ["necesarul de insulină al diabeticului crește odată cu BCR","alopurinolul sau febuxostatul, în doze mici, previn recurența gutei","hiperprolactinemia poate da galactoree la ambele sexe","oligomenoreea sau amenoreea, frecvente la femeile dializate","colchicina este contraindicată în atacul de gută"],"BCD",1397,"Boala cronică de rinichi — Insulină în scădere, colchicină, galactoree",
 "Direcția necesarului de insulină (scade), tratamentul gutei și galactoreea din hiperprolactinemie.",
 ["Nu: necesarul de insulină scade pe măsură ce BCR progresează, prin catabolism și excreție renală reduse și gluconeogeneză renală diminuată.","Alopurinolul sau febuxostatul în doze mici previn recurențele; în atac, colchicina poate fi folosită.","Hiperprolactinemia se poate manifesta cu galactoree atât la bărbați, cât și la femei.","Puține femei dializate mai au ciclu menstrual; oligomenoreea/amenoreea și pierderea libidoului sunt frecvente.","Nu: în atacul de gută colchicina poate fi folosită, AINS nefrotoxice fiind puțin utile."]],
 [8,"Scăderea (nu creșterea) dozei de insulină în BCR avansată este capcana de diabetologie a paginii."],["necesarul de insulină","galactoree"]),

q("nefrologie-adv-154",["Un pacient profund uremic începe hemodializa. Riscurile neurologice:",
 ["dezechilibrul de dializă: ureea scade mai rapid în SNC decât în sânge","dezechilibrul se previne prin ședințe scurte repetate sau DP","polineuropatia simetrică, posibilă și la dializă inadecvată","dezechilibrul este o hiponatremie prin dializant hipoton","dezechilibrul se previne prin scăderea rapidă a ureei"],"BC",1398,"Boala cronică de rinichi — Dezechilibrul de dializă: edem osmotic",
 "Mecanismul osmotic (uree sânge–SNC) și prevenția prin ședințe scurte sau DP, plus polineuropatia uremică.",
 ["Nu: ureea scade în sânge mai rapid decât în SNC, iar apa trece spre creier, producând edem osmotic cerebral.","Sindromul poate fi evitat prin corecție graduală, cu ședințe scurte repetate de hemodializă, sau prin dializă peritoneală.","Uremia avansată determină polineuropatie simetrică, care poate reapărea la dializă inadecvată.","Nu: sindromul se datorează gradientului de uree dintre sânge și SNC, nu unei hiponatremii prin dializant hipoton.","Nu: corecția bruscă a ureei precipită, nu previne, sindromul."]],
 [8,"Direcția apei (spre SNC-ul încă uremic) este capcana osmotică a primei ședințe."],["edemul osmotic cerebral","hemodializă scurte"]),

q("nefrologie-adv-155",["Când RFG scade sub 20 mL/min/1,73 m², pregătirea pentru substituție include:",
 ["o echipă dedicată, care sprijină alegerea SFR sau a non-dializei","cateterul DP lăsat subcutanat până la începerea dializei","pregătirea transplantului de la donator viu, cea mai bună SFR","crearea FAV după prima ședință de HD pe cateter femural","amânarea oricărei discuții despre SFR până la apariția anuriei"],"ABC",1398,"Boala cronică de rinichi — Pragul 20 mL/min și cateterul DP subcutanat",
 "Aplicarea pragului <20 mL/min pentru consiliere și a strategiei de cateter DP „îngropat”.",
 ["Sub 20 mL/min, o echipă dedicată se ocupă de dietă, medicație, factorii de risc și sprijinul în alegerea SFR sau a non-dializei.","La opțiunea DP, cateterul poate fi lăsat subcutanat și scos la suprafață când începe dializa.","În cazurile potrivite se pregătește transplantul de la donator viu, cea mai bună metodă de SFR.","Nu: FAV se creează din timp, nu după hemodializă de urgență pe cateter.","Nu: discuția despre SFR începe sub 20 mL/min, nu se amână până la anurie."]],
 [8,"Pragul 20 mL/min și cateterul DP îngropat sunt detalii de timing nefolosite, distincte de creatinina 400–500 a FAV."],["20 mL/min","lăsat subcutanat"]),

q("nefrologie-adv-156",["Medicamente de evitat sau de ajustat în BCR:",
 ["tetraciclinele, cu posibila excepție a doxiciclinei","gentamicina, cu monitorizarea nivelului seric","opioidele, care se acumulează în insuficiența renală","doxiciclina, cea mai nefrotoxică dintre tetracicline","gentamicina în doze standard, fără monitorizare serică"],"ABC",1398,"Boala cronică de rinichi — Tetracicline, gentamicină și opioide",
 "Recunoașterea excepției doxiciclinei și a acumulării opioidelor, alături de monitorizarea aminoglicozidelor.",
 ["Tetraciclinele trebuie evitate în BCR, cu posibila excepție a doxiciclinei.","Gentamicina și alte medicamente eliminate renal se folosesc doar în absența unei alternative, cu monitorizarea nivelului seric.","Opioidele se pot acumula în BCR; anticoagulantele orale anti-trombină sunt greu de monitorizat.","Nu: doxiciclina este excepția posibilă, mai sigură, printre tetracicline.","Nu: gentamicina se folosește doar fără alternativă și cere monitorizarea nivelului seric."]],
 [8,"Excepția doxiciclinei și „necroza opioidă” sunt detalii de prescripție ușor de inversat."],["doxiciclinei","opioidele"]),

q("nefrologie-adv-157",["Bicarbonatul din dializantul de hemodializă (Cadranul 36.37) are uzual:",
 ["0–4 mmol/L","137–141 mmol/L","77–236 mmol/L","1,0–1,6 mmol/L","35–40 mmol/L"],"E",1399,"Boala cronică de rinichi — Cadranul 36.37: bicarbonatul dializantului",
 "Reținerea ferestrei 35–40 mmol/L a bicarbonatului, distinctă de K, Na, Ca sau glucoza DP.",
 ["Nu: 0–4 mmol/L este intervalul potasiului din dializant, nu al bicarbonatului.","Nu: 137–141 mmol/L este sodiul uzual al dializantului; bicarbonatul are 35–40 mmol/L.","Nu: 77–236 mmol/L este glucoza din dializantul de DP.","Nu: 1,0–1,6 mmol/L este calciul din dializantul de hemodializă.","Cadranul 36.37 indică pentru bicarbonat 35–40 mmol/L."]],
 [8,"Permutează 35–40 (bicarbonat HD) cu 0–4 (K) și 77–236 (glucoză DP), trei intervale din cadrane învecinate."],["35-40","Bicarbonat"]),

q("nefrologie-adv-158",["Abordul vascular și dializantul în hemodializă:",
 ["cateterul tunelizat se complică cu bacteriemie sau stenoză venoasă","în urgență, cateter temporar netunelizat, de calibru mare","K 1–3 mmol/L în dializant, cu bilanț negativ de 1–2 mmol/kg","sodiul dializantului, uzual 137–141 mmol/L, se individualizează","cateterul tunelizat, abord definitiv preferat față de FAV"],"ABCD",1400,"Boala cronică de rinichi — Cateter tunelizat versus țintele de K și Na",
 "Deosebirea cateterului tunelizat (riscuri) de FAV și reținerea bilanțului de K 1–2 mmol/kg cu Na 137–141.",
 ["Cateterul venos central tunelizat, cu lumen dublu, pe jugulară sau femurală, se asociază cu bacteriemie, tromboză sau stenoză venoasă.","În urgență se folosește un cateter temporar netunelizat, de calibru mare, pe subclavie, jugulară sau femurală.","Un dializant cu K 1–3 mmol/L permite un bilanț negativ de 1–2 mmol/kg pe ședință.","Sodiul dializantului, de obicei 137–141 mmol/L, se individualizează pentru a evita schimburi mari de apă.","Nu: FAV rămâne abordul de elecție; cateterul are un risc semnificativ de bacteriemie."]],
 [8,"Bilanțul de K 1–2 mmol/kg și Na 137–141 sunt ușor de permutat; distractorul promovează cateterul ca elecție."],["1-2 mmol/kg","137-141 mmol/L"]),

q("nefrologie-adv-159",["Hemofiltrarea și hemodiafiltrarea:",
 ["elimină plasma prin convecție, pe o membrană high-flux","hemofiltrarea este contraindicată la pacientul instabil hemodinamic","HDF cu convecție mare țintește β2-microglobulina (11,8 kDa)","hemofiltrarea necesită un dializant în contracurent, ca hemodializa","vizează β2-microglobulina, o proteină de 66 kDa"],"AC",1400,"Boala cronică de rinichi — Hemofiltrare: convecție fără dializant",
 "Contrastul convecție-fără-dializant versus HD, locul la pacientul instabil și ținta β2-microglobulinei 11,8 kDa.",
 ["În hemofiltrare nu există dializant: plasma este eliminată prin convecție pe o membrană high-flux și înlocuită cu lichid de substituție.","Nu: hemofiltrarea poate fi preferată tocmai la pacientul instabil hemodinamic, mai ales în terapie intensivă.","HDF cu convecție mare urmărește moleculele medii, ca β2-microglobulina (11,8 kDa), și prevenția amiloidozei de dializă.","Nu: hemofiltrarea nu folosește dializant; plasma este eliminată prin convecție și înlocuită cu lichid de substituție.","Nu: β2-microglobulina are 11,8 kDa; 66 kDa este masa albuminei."]],
 [8,"Absența dializantului este definiția ușor de ratat; 11,8 kDa distinge β2-microglobulina de albumină."],["high-flux","11,8 kDa"]),

q("nefrologie-adv-160",["Dializa peritoneală (Cadranul 36.38, cateterul Tenckhoff):",
 ["cateterul flexibil este tunelizat, cu vârful în pelvis","dializantul uzual are potasiu 0 mmol/L și lactat 35–40 mmol/L","glucoza (1,36% = 77 mmol/L) asigură ultrafiltrarea osmotică","o soluție mai hipertonă (6,36%) servește DP acută intermitentă","osmolaritatea totală a dializantului este de 35–40 mOsm/kg"],"ABCD",1401,"Boala cronică de rinichi — DP: K zero, 1,36% = 77 mmol/L, Tenckhoff",
 "Reținerea K=0, a conversiei 1,36%→77 mmol/L și a poziției pelvine a cateterului Tenckhoff.",
 ["Cateterul Tenckhoff flexibil este tunelizat subcutanat, cu vârful în pelvis.","Dializantul uzual are potasiu 0 mmol/L și lactat 35–40 mmol/L (Cadranul 36.38).","Glucoza 77–236 mmol/L (ex. 1,36% = 77 mmol/L) determină ultrafiltrarea osmotică.","Un dializant mai hiperton (6,36%) este disponibil pentru DP acută intermitentă.","Nu: osmolaritatea totală este 356–511 mOsm/kg; 35–40 mmol/L este concentrația lactatului."]],
 [8,"Conversia 1,36% = 77 mmol/L și K=0 sunt capcane numerice pe cadranul de DP."],["1,36% = 77 mmol/L","356-511 mOsm/kg"]),

q("nefrologie-adv-161",["Dializa la pacientul debilitat și beneficiile transplantului:",
 ["într-un studiu, ~50% au decedat în primul an de dializă","transplantul crește necesitatea de paratiroidectomie","donatorii din Marea Britanie, 44/milion/an, nu acoperă cererea","mortalitatea în primul an de dializă este sub 2%","anemia persistă de regulă după un transplant reușit"],"AC",1402,"Boala cronică de rinichi — Debilitați: 50%/30% și donatori 44/milion",
 "Contrastul prognosticului nefavorabil al dializei la fragili (50% deces/an 1) cu beneficiile grefei (anemie, infertilitate, paratiroidectomie).",
 ["Într-un studiu, circa 50% dintre pacienți au decedat în primul an de dializă, iar circa 30% au avut declin al statusului funcțional.","Nu: transplantul reușit scade necesitatea de paratiroidectomie și corectează anemia și infertilitatea.","Capacitatea donatorilor în Marea Britanie este de 44/milion populație pe an, depășită de cerere.","Nu: în studiul citat, circa 50% dintre pacienți au decedat în primul an de dializă.","Nu: transplantul reușit corectează anemia."]],
 [8,"Permutează 50% (mortalitate an 1) cu 44 (donatori/milion), două ordine de mărime de pe aceeași pagină."],["44/milion","50% dintre"]),

q("nefrologie-adv-162",["Imunosupresia de transplant (Cadranul 36.40) și donatoarea vie:",
 ["eculizumabul blochează fracțiunea C5 activată a complementului","basiliximabul și daclizumabul blochează receptorul IL-2","alemtuzumabul (anti-CD52) distruge limfocitele B și T","donatoarele au risc crescut de preeclampsie la sarcini ulterioare","belataceptul blochează receptorul IL-2, ca basiliximabul"],"ABCD",1403,"Boala cronică de rinichi — Belatacept, eculizumab și donatoarea gravidă",
 "Maparea țintelor B7/C5/IL-2/CD52 și avertismentul obstetrical pentru donatoare.",
 ["Eculizumabul blochează fracțiunea C5 activată a complementului (Cadranul 36.40).","Basiliximabul și daclizumabul blochează receptorul IL-2, ca tratament de inducție.","Alemtuzumabul (anti-CD52) distruge limfocitele B și T.","Femeile care donează un rinichi au risc mai mare de HTA gestațională sau preeclampsie la sarcinile ulterioare, fără riscuri pentru copii.","Nu: belataceptul (anti-B7) previne implicarea B7–CD28; receptorul IL-2 este blocat de basiliximab și daclizumab."]],
 [8,"Trei anticorpi (B7, C5, CD52) sunt concepuți să fie amestecați; riscul de preeclampsie al donatoarei este detaliul nefolosit."],["Belatacept","preeclampsie"]),

q("nefrologie-adv-163",["După transplantul renal:",
 ["CMV apare la 70% dintre primitorii D+/R− fără valganciclovir","cotrimoxazolul se dă în primele luni contra Pneumocystis","nefropatia BK se tratează prin creșterea imunosupresiei","perfuzia hipotermică pe aparat ameliorează funcția întârziată a grefei","CMV apare la sub 5% dintre primitorii D+/R− fără profilaxie"],"ABD",1404,"Boala cronică de rinichi — CMV 70%, PCP și BK",
 "Reținerea cotei CMV 70% D+/R−, a cotrimoxazolului anti-PCP și a reducerii (nu creșterii) IS în nefropatia BK.",
 ["CMV apare în săptămâni–luni la 70% dintre primitorii seronegativi cu donator pozitiv, în absența profilaxiei cu valganciclovir.","Profilaxia cu cotrimoxazol în primele luni este necesară pentru Pneumocystis jirovecii.","Nu: nefropatia BK (polyomavirus) se gestionează prin reducerea imunosupresiei, singura terapie disponibilă.","Rinichii transportați pe aparat de perfuzie cu hipotermie controlată s-au asociat cu ameliorarea funcției întârziate a grefei.","Nu: fără profilaxie, CMV apare la 70% dintre primitorii seronegativi cu donator pozitiv."]],
 [8,"Cota 70% D+/R− și reducerea IS în BK sunt ușor de inversat spre „crește calcineurinicul, CMV e rar”."],["ganciclovir","Polyomavirus"]),

q("nefrologie-adv-164",["Complicațiile tardive ale grefei renale:",
 ["GSFS primară recidivează rar și tardiv pe grefă","IFTA, numită anterior nefropatie cronică de allogrefă","declinul progresiv al grefei, cu proteinurie <3 g/zi","riscul crescut de carcinoame bazocelulare și spinocelulare","IFTA, diagnosticată prin proteinurie peste 10 g/zi"],"BCD",1404,"Boala cronică de rinichi — Recurențe pe grefă și IFTA",
 "Recunoașterea recurenței precoce a GSFS, a IFTA (fostă nefropatie cronică de allogrefă) și a pragului <3 g/zi.",
 ["Nu: GSFS primară reapare frecvent pe grefă și duce la pierderea ei precoce.","Fibroza interstițială cu atrofie tubulară (IFTA), numită anterior nefropatie cronică de allogrefă, este un aspect histologic frecvent.","Declinul progresiv al grefei se asociază cu proteinurie ușoară-moderată (<3 g/zi); intervențiile nu s-au dovedit încă benefice.","Imunosupresia crește riscul tumorilor cutanate, inclusiv carcinoame bazocelulare și spinocelulare.","Nu: declinul grefei se asociază cu proteinurie ușoară-moderată, sub 3 g/zi, nu peste 10 g/zi."]],
 [8,"Recurența precoce a GSFS și redenumirea IFTA sunt detalii ușor de negat; <3 g/zi distinge de nefrotic."],["<3 g/zi","allogrefă"]),
];
